-- NEBULA HUB MM2 v1.5.0 | BM | AI: NEP
-- Gemini credentials stay on NEBULA CLOUD.

local function createEngine(ctx)
    local Players, RS, RunService, UIS = ctx.Players, ctx.RS, ctx.RunService, ctx.UIS
    local Lighting, me, gui = ctx.Lighting, ctx.me, ctx.gui
    local E = {}
    local alive, born, roundRevision = true, os.clock(), 0
    local flags = {playerESP=false, roleESP=false, coinESP=false, gunESP=false,
        autoCoins=false, walkSpeed=16, jumpPower=50, infiniteJump=false,
        noclip=false, fullbright=false, lowEffects=false}
    local connections, roots, roles, visual = {}, {}, {}, {}
    local originals = setmetatable({}, {__mode="k"})
    local collisionOriginals = setmetatable({}, {__mode="k"})
    local effectOriginals = setmetatable({}, {__mode="k"})
    local lightOriginals = {}
    local cachedMap, coins, droppedGuns = nil, {}, {}
    local mapName, waypoint, target, targetAt, lastMove = "--", nil, nil, 0, 0
    local queryBusy, queryGeneration, pendingQueryToken = false, 0, nil
    local targetCooldown = setmetatable({}, {__mode="k"})
    local spectating, cameraSnapshot = nil, nil
    local boundEvents = setmetatable({}, {__mode="k"})
    local roleNames = {Murderer="ฆาตกร", Sheriff="นายอำเภอ", Hero="ฮีโร่", Innocent="ผู้บริสุทธิ์", Zombie="ซอมบี้", Survivor="ผู้รอดชีวิต"}
    local roleColors = {Murderer=Color3.fromRGB(255,76,99),Sheriff=Color3.fromRGB(75,164,255),Hero=Color3.fromRGB(255,208,84),Innocent=Color3.fromRGB(88,223,163),Zombie=Color3.fromRGB(195,108,255),Survivor=Color3.fromRGB(87,224,235)}
    local function tell(s) if alive then ctx.notify(s) end end
    local function connect(signal, fn)
        local c = signal:Connect(fn)
        connections[#connections+1] = c
        return c
    end
    local function character()
        local ch = me.Character
        return ch, ch and ch:FindFirstChildOfClass("Humanoid"), ch and ch:FindFirstChild("HumanoidRootPart")
    end
    local function partOf(obj)
        if not obj then return nil end
        if obj:IsA("BasePart") then return obj end
        return obj:FindFirstChildWhichIsA("BasePart", true)
    end
    local function pointOf(obj)
        local p = partOf(obj)
        return p and p.Position
    end
    local function distance(a, b) return (a-b).Magnitude end
    local function findMap()
        local _, _, root = character()
        local best, bestDistance, bestScore
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") and obj.Name ~= "Lobby" and not Players:GetPlayerFromCharacter(obj) then
                local bucket, spawn = obj:FindFirstChild("CoinContainer"), obj:FindFirstChild("Spawns")
                if bucket or spawn then
                    local p = pointOf(spawn) or pointOf(bucket)
                    local d = p and root and distance(root.Position,p) or math.huge
                    local score = bucket and 2 or 1
                    if not best or score > bestScore or (score == bestScore and d < bestDistance) then
                        best, bestDistance, bestScore = obj, d, score
                    end
                end
            end
        end
        return best
    end
    local function resetRound()
        roundRevision = roundRevision + 1
        roles = {}
        queryGeneration = queryGeneration + 1
        target, targetAt = nil, 0
    end
    local function validRole(p)
        local r = roles[p]
        if not r or r.character ~= p.Character or r.revision ~= roundRevision or os.clock()-r.at > 30 then return nil end
        return r
    end
    local function applyRoles(data)
        if type(data) ~= "table" then return 0 end
        local nextRoles, count = {}, 0
        for _, p in ipairs(Players:GetPlayers()) do
            local r = data[p.Name] or data[tostring(p.UserId)] or data[p.UserId]
            if type(r)=="table" and roleNames[r.Role]
                and (r.Dead==nil or type(r.Dead)=="boolean")
                and (r.Killed==nil or type(r.Killed)=="boolean") then
                nextRoles[p] = {role=r.Role,inactive=r.Dead==true or r.Killed==true,
                    at=os.clock(),character=p.Character,revision=roundRevision}
                count = count + 1
            end
        end
        roles = nextRoles
        return count
    end
    local function bindEvent(obj)
        if not obj:IsA("RemoteEvent") or boundEvents[obj] then return end
        local name = obj.Name
        if name~="UpdatePlayerData" and name~="RoundEndFade" and name~="RoleSelect" and name~="Fade" then return end
        boundEvents[obj]=true
        connect(obj.OnClientEvent,function(data)
            if not alive then return end
            if name=="UpdatePlayerData" then applyRoles(data)
            elseif name=="Fade" then resetRound() applyRoles(data)
            else resetRound() end
        end)
    end
    function E.queryRoles(quiet)
        local function report(message)if not quiet then tell(message)end end
        if not alive then return end
        if queryBusy then report("กำลังรอข้อมูลบทบาท") return end
        local found
        for _, obj in ipairs(RS:GetDescendants()) do
            if obj.Name=="GetPlayerData" and obj:IsA("RemoteFunction") then found=obj break end
        end
        if not found then report("ไม่พบ GetPlayerData ที่อ่านบทบาทได้ • รอข้อมูลจากเกม") return end
        queryBusy = true
        queryGeneration = queryGeneration + 1
        local token, revision = queryGeneration, roundRevision
        pendingQueryToken=token
        task.spawn(function()
            local ok, data = pcall(function() return found:InvokeServer() end)
            if pendingQueryToken==token then queryBusy=false;pendingQueryToken=nil end
            if not alive or token~=queryGeneration or revision~=roundRevision then return end
            if ok then
                local n=applyRoles(data)
                report(n>0 and ("อ่านบทบาทได้ "..n.." คน • ข้อมูลมีอายุ 30 วินาที") or "เกมไม่ได้ส่ง Role ที่ตรวจสอบได้")
            else report("อ่านบทบาทไม่สำเร็จ") end
        end)
        task.delay(6,function()
            if alive and queryBusy and pendingQueryToken==token and token==queryGeneration then
                queryGeneration=queryGeneration+1
                report("อ่านบทบาทหมดเวลา • รอคำขอเดิมจบก่อนตรวจใหม่")
            end
        end)
    end
    local function timerText()
        local obj=workspace:FindFirstChild("RoundTimerPart")
        if not obj then return "--:--" end
        local surface=obj:FindFirstChild("SurfaceGui")
        local clock=surface and surface:FindFirstChild("Timer")
        local v
        if surface and surface:IsA("SurfaceGui") and surface.Enabled and clock and clock:IsA("TextLabel") and clock.Visible then
            local m,s=clock.Text:match("^%s*(%d+):(%d%d)%s*$")
            if m and tonumber(s)<60 then v=tonumber(m)*60+tonumber(s) end
        end
        if v==nil then v=obj:GetAttribute("Time") end
        if type(v)~="number" or v~=v or v<0 or v==math.huge then return "--:--" end
        return string.format("%02d:%02d",math.floor(v/60),math.floor(v%60))
    end
    local function refreshWorld()
        local m=findMap()
        if m~=cachedMap then cachedMap=m resetRound() end
        mapName=m and m.Name or "รอแมพ"
        coins={}
        local bucket=m and m:FindFirstChild("CoinContainer")
        if bucket then
            local seen={}
            for _,c in ipairs(bucket:GetDescendants())do
                local name=c.Name:lower()
                if name=='coin_server'or name=='candy_server'or name=='coin'or name=='candy'then
                    local part=partOf(c)
                    if part and not seen[part]then seen[part]=true;coins[#coins+1]=part end
                end
            end
        end
        droppedGuns={}
        for obj in pairs(roots) do
            if not obj.Parent then roots[obj]=nil
            elseif obj.Name=="GunDrop" and not obj:FindFirstAncestor("WeaponDisplays") then
                local p=partOf(obj)
                if p then droppedGuns[#droppedGuns+1]=p end
            end
        end
    end
    local function restoreTable(t)
        for obj, props in pairs(t) do
            if obj.Parent then for k,v in pairs(props) do pcall(function() obj[k]=v end) end end
            t[obj]=nil
        end
    end
    local function remember(obj, prop, value)
        originals[obj]=originals[obj] or {}
        if originals[obj][prop]==nil then originals[obj][prop]=obj[prop] end
        obj[prop]=value
    end
    local function movement()
        local ch,h=character()
        if not h then return end
        if flags.walkSpeed>16 then remember(h,"WalkSpeed",flags.walkSpeed)
        elseif originals[h] and originals[h].WalkSpeed~=nil then
            h.WalkSpeed=originals[h].WalkSpeed originals[h].WalkSpeed=nil
        end
        if flags.jumpPower>50 then
            if h.UseJumpPower then remember(h,"JumpPower",flags.jumpPower)
            else remember(h,"JumpHeight",flags.jumpPower*flags.jumpPower/(2*math.max(workspace.Gravity,1))) end
        elseif originals[h] then
            for _,key in ipairs({"JumpPower","JumpHeight"}) do
                if originals[h][key]~=nil then h[key]=originals[h][key] originals[h][key]=nil end
            end
        end
        if flags.noclip and ch then
            for _, obj in ipairs(ch:GetDescendants()) do
                if obj:IsA("BasePart") then
                    if collisionOriginals[obj]==nil then collisionOriginals[obj]=obj.CanCollide end
                    obj.CanCollide=false
                end
            end
        end
    end
    local function restoreCollision()
        for obj,value in pairs(collisionOriginals) do
            if obj.Parent then pcall(function() obj.CanCollide=value end) end
            collisionOriginals[obj]=nil
        end
    end
    local function restoreLight()
        for key,value in pairs(lightOriginals) do pcall(function() Lighting[key]=value end) end
        lightOriginals={}
    end
    local function applyLight()
        local values={Brightness=2,ClockTime=14,FogEnd=100000,GlobalShadows=false,Ambient=Color3.fromRGB(180,180,180)}
        for key,value in pairs(values) do
            if lightOriginals[key]==nil then lightOriginals[key]=Lighting[key] end
            Lighting[key]=value
        end
    end
    local function reduceEffect(obj)
        if not alive or not flags.lowEffects then return end
        if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
            if not effectOriginals[obj] then effectOriginals[obj]={Enabled=obj.Enabled} end
            obj.Enabled=false
        end
    end
    local function clearVisual(key)
        local v=visual[key]
        if v then
            if v.h then v.h:Destroy() end
            if v.b then v.b:Destroy() end
            visual[key]=nil
        end
    end
    local function clearVisuals()
        local keys={}
        for k in pairs(visual) do keys[#keys+1]=k end
        for _,k in ipairs(keys) do clearVisual(k) end
    end
    local function mark(key, adornee, part, text, color, fill)
        local v=visual[key]
        if v and v.adornee~=adornee then clearVisual(key) v=nil end
        if not v then
            local h=Instance.new("Highlight")
            h.Adornee=adornee h.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
            h.FillTransparency=fill or 0.8 h.OutlineTransparency=0 h.Parent=gui
            local b=Instance.new("BillboardGui")
            b.Adornee=part b.AlwaysOnTop=true b.Size=UDim2.fromOffset(180,36)
            b.StudsOffset=Vector3.new(0,2.5,0) b.Parent=gui
            local t=Instance.new("TextLabel")
            t.Size=UDim2.fromScale(1,1) t.BackgroundTransparency=1 t.Font=Enum.Font.GothamBold
            t.TextSize=12 t.TextStrokeTransparency=0.25 t.TextWrapped=true t.Parent=b
            v={h=h,b=b,t=t,adornee=adornee} visual[key]=v
        end
        v.h.FillColor=color v.h.OutlineColor=color v.t.TextColor3=color
        v.t.Text=text v.b.Adornee=part
        local o=ctx.options or {}
        v.h.FillTransparency=o.esp_fill or 0.8
        v.h.OutlineTransparency=o.esp_outline or 0
        v.h.DepthMode=o.esp_wall_mode=='Occluded' and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop
        v.b.AlwaysOnTop=o.esp_wall_mode~='Occluded'
        v.t.TextSize=o.esp_label_size or 12
        v.t.TextStrokeTransparency=o.plus_label_stroke or .25
        v.b.StudsOffset=Vector3.new(0,o.plus_label_height or 2.5,0)
    end
    local function render()
        if ctx.renderESP then ctx.renderESP() return end
        local keep={}
        local _,_,root=character()
        if flags.playerESP or flags.roleESP then
            for _,p in ipairs(Players:GetPlayers()) do
                if p~=me then
                    local ch=p.Character
                    local h=ch and ch:FindFirstChildOfClass("Humanoid")
                    local r=ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))
                    local role=validRole(p)
                    if h and h.Health>0 and r and not (role and role.inactive) then
                        local label=p.DisplayName
                        if root then label=label.." · "..math.floor(distance(root.Position,r.Position)).." studs" end
                        local color=Color3.fromRGB(189,142,255)
                        if flags.roleESP then
                            label=label.."\n"..(role and roleNames[role.role] or "ไม่ทราบบทบาท")
                            color=role and roleColors[role.role] or Color3.fromRGB(175,175,185)
                        end
                        mark(p,ch,r,label,color,0.8) keep[p]=true
                    end
                end
            end
        end
        if flags.coinESP then
            local sorted={}
            for _,p in ipairs(coins) do if p.Parent then sorted[#sorted+1]=p end end
            if root then table.sort(sorted,function(a,b) return distance(a.Position,root.Position)<distance(b.Position,root.Position) end) end
            for i,p in ipairs(sorted) do
                if i>40 then break end
                mark(p,p,p,"เหรียญ",Color3.fromRGB(255,206,93),0.65) keep[p]=true
            end
        end
        if flags.gunESP then
            for _,p in ipairs(droppedGuns) do
                if p.Parent then mark(p,p,p,"ปืนตก",Color3.fromRGB(92,178,255),0.55) keep[p]=true end
            end
        end
        local remove={}
        for key in pairs(visual) do if not keep[key] then remove[#remove+1]=key end end
        for _,key in ipairs(remove) do clearVisual(key) end
    end
    local function stopMove()
        target=nil
        local _,h,r=character()
        if h and r then pcall(function() h:MoveTo(r.Position) end) end
    end
    local function autoWalk(now)
        if not flags.autoCoins then return end
        if ctx.farmController then ctx.farmController(coins,cachedMap,now) return end
        local _,h,r=character()
        if not h or h.Health<=0 or not r or not cachedMap then target=nil return end
        if target and (not target.Parent or not target:IsDescendantOf(cachedMap) or now-targetAt>6 or distance(r.Position,target.Position)<2) then
            if target.Parent then targetCooldown[target]=now+8 end
            target=nil
        end
        if not target then
            local nearest=250 -- never walk from the lobby to a distant loaded round map
            for _,p in ipairs(coins) do
                if p.Parent and (targetCooldown[p] or 0)<=now then
                    local d=distance(r.Position,p.Position)
                    if d<nearest then target=p nearest=d end
                end
            end
            targetAt=now
        end
        if target and now-lastMove>0.8 then
            lastMove=now
            h:MoveTo(target.Position)
        end
    end
    local function restoreCamera()
        local c=workspace.CurrentCamera
        if c then
            local _,h=character()
            local old=cameraSnapshot
            pcall(function()
                c.CameraType=old and old.kind or Enum.CameraType.Custom
                c.CameraSubject=(old and old.subject and old.subject.Parent and old.subject) or h
            end)
        end
        cameraSnapshot=nil spectating=nil
    end
    function E.unspectate() restoreCamera() end
    function E.spectate(name)
        local q=string.lower(tostring(name or ""))
        if q=="" then tell("ใส่ชื่อผู้เล่นก่อน") return false end
        local exact, matches=nil,{}
        for _,p in ipairs(Players:GetPlayers()) do
            if p~=me then
                if string.lower(p.Name)==q then exact=p break end
                if string.find(string.lower(p.Name),q,1,true) or string.find(string.lower(p.DisplayName),q,1,true) then matches[#matches+1]=p end
            end
        end
        local chosen=exact or (#matches==1 and matches[1])
        if not chosen then tell(#matches>1 and "พบหลายคน • ใส่ username ให้ตรง" or "ไม่พบผู้เล่น") return false end
        local h=chosen.Character and chosen.Character:FindFirstChildOfClass("Humanoid")
        local c=workspace.CurrentCamera
        if not h or not c then tell("ยังดูผู้เล่นคนนี้ไม่ได้") return false end
        if not cameraSnapshot then cameraSnapshot={kind=c.CameraType,subject=c.CameraSubject} end
        spectating=chosen c.CameraType=Enum.CameraType.Custom c.CameraSubject=h
        tell("กำลังดู "..chosen.Name) return true
    end
    local function teleportTo(cf)
        local ch,h,r=character()
        if not ch or not h or h.Health<=0 or not r then tell("รอให้ตัวละครเกิดก่อน") return false end
        stopMove()
        local ok=pcall(function() ch:PivotTo(cf) r.AssemblyLinearVelocity=Vector3.zero r.AssemblyAngularVelocity=Vector3.zero end)
        tell(ok and "ย้ายตำแหน่งแล้ว • เกมอาจปรับตำแหน่งกลับ" or "ย้ายตำแหน่งไม่สำเร็จ")
        return ok
    end
    function E.saveWaypoint()
        local _,_,r=character()
        if not r then tell("ไม่พบตัวละคร") return end
        waypoint={cf=r.CFrame,map=cachedMap}
        tell("บันทึกตำแหน่งสำหรับเซสชันนี้แล้ว")
    end
    function E.goWaypoint()
        if not waypoint then tell("บันทึกตำแหน่งก่อน") return end
        if waypoint.map and (not waypoint.map.Parent or waypoint.map~=cachedMap) then tell("แมพเปลี่ยนแล้ว • บันทึกตำแหน่งใหม่") return end
        teleportTo(waypoint.cf)
    end
    local function nearestSpawn(container)
        if not container then return nil end
        local _,_,r=character()
        local best,bestD=nil,math.huge
        for _,p in ipairs(container:GetDescendants()) do
            if p:IsA("BasePart") and (p:IsA("SpawnLocation") or p.Name=="Spawn") then
                local d=r and distance(p.Position,r.Position) or 0
                if d<bestD then best=p bestD=d end
            end
        end
        return best
    end
    function E.goLobby()
        local lobby=workspace:FindFirstChild("Lobby")
        local p=nearestSpawn(lobby and lobby:FindFirstChild("Spawns"))
        if not p then tell("ไม่พบจุดเกิดล็อบบี้") return end
        teleportTo(p.CFrame+Vector3.new(0,4,0))
    end
    function E.goMapSpawn()
        refreshWorld()
        local p=nearestSpawn(cachedMap and cachedMap:FindFirstChild("Spawns"))
        if not p then tell("ไม่พบจุดเกิดของแมพที่โหลดอยู่") return end
        teleportTo(p.CFrame+Vector3.new(0,4,0))
    end
    function E.rejoin()
        local ok=pcall(function() game:GetService("TeleportService"):TeleportToPlaceInstance(game.PlaceId,game.JobId,me) end)
        tell(ok and "ส่งคำขอเข้าเซิร์ฟเวอร์เดิมแล้ว" or "ส่งคำขอเข้าเซิร์ฟเวอร์ไม่ได้")
    end
    function E.set(key,value)
        if not alive or flags[key]==nil then return false end
        if key=="walkSpeed" or key=="jumpPower" then
            value=tonumber(value)
            if not value or value~=value then return false end
            value=math.clamp(value,key=="walkSpeed" and 16 or 50,key=="walkSpeed" and 60 or 100)
        else value=value==true end
        flags[key]=value
        if key=="noclip" and not value then restoreCollision() end
        if key=="fullbright" then if value then applyLight() else restoreLight() end end
        if key=="lowEffects" then
            if value then
                task.spawn(function()
                    for i,obj in ipairs(workspace:GetDescendants()) do
                        if not alive or not flags.lowEffects then return end
                        reduceEffect(obj)
                        if i%200==0 then task.wait() end
                    end
                end)
            else restoreTable(effectOriginals) end
        end
        if key=="autoCoins" and not value then stopMove() end
        if key=="walkSpeed" or key=="jumpPower" then movement() end
        render()
        if ctx.onSettingChanged then ctx.onSettingChanged(key,value) end
        return true
    end
    function E.stopAll()
        for k in pairs(flags) do flags[k]=false end
        flags.walkSpeed=16 flags.jumpPower=50
        if ctx.onSettingChanged then for key,value in pairs(flags) do ctx.onSettingChanged(key,value) end end
        stopMove() clearVisuals() restoreCollision() restoreTable(originals) restoreTable(effectOriginals) restoreLight() restoreCamera()
        resetRound()
    end
    function E.status()
        local _,h=character()
        local role=validRole(me)
        return {map=mapName,timer=timerText(),health=h and string.format("%.0f / %.0f",h.Health,h.MaxHealth) or "--",
            coins=#coins,role=role and (role.inactive and "ออกจากรอบ" or roleNames[role.role]) or "ไม่ทราบบทบาท",
            session=string.format("%02d:%02d",math.floor((os.clock()-born)/60),math.floor((os.clock()-born)%60))}
    end
    function E.copyDiagnostics()
        refreshWorld()
        local s=E.status()
        local _,_,r=character()
        local lines={"NEBULA HUB MM2 diagnostics", "PlaceId="..game.PlaceId,"Map="..s.map,"Timer="..s.timer,"Health="..s.health,"Role="..s.role,"Coin_Server count="..#coins,"GunDrop count="..#droppedGuns,
            "Role source: explicit Role fields from replicated UpdatePlayerData or manual GetPlayerData; expires after 30s",
            "Coin ESP: up to 40 nearby coins; Auto Coins: walking only, 6s retry/8s cooldown"}
        if r then lines[#lines+1]=string.format("Position=%.1f, %.1f, %.1f",r.Position.X,r.Position.Y,r.Position.Z) end
        if cachedMap then
            lines[#lines+1]="Map path="..cachedMap:GetFullName()
            for _,obj in ipairs(cachedMap:GetChildren()) do lines[#lines+1]=obj.ClassName.." | "..obj.Name end
        end
        local timer=workspace:FindFirstChild("RoundTimerPart")
        if timer then
            for _,obj in ipairs(timer:GetDescendants()) do
                if obj:IsA("TextLabel") then lines[#lines+1]="Timer label="..obj:GetFullName().." : "..obj.Text end
            end
        end
        return table.concat(lines,"\n")
    end
    function E.scan() return E.copyDiagnostics() end
    function E.destroy()
        if not alive then return end
        E.stopAll() alive=false
        for _,c in ipairs(connections) do c:Disconnect() end
        connections={}
    end
    if ctx.onCleanup then ctx.onCleanup(E.destroy) end
    connect(me.CharacterAdded,function() restoreCollision() restoreTable(originals) resetRound() end)
    connect(Players.PlayerRemoving,function(p) roles[p]=nil clearVisual(p) if p==spectating then restoreCamera() end end)
    connect(UIS.JumpRequest,function()
        if alive and flags.infiniteJump then
            local _,h=character()
            if h and h.Health>0 then h:ChangeState(Enum.HumanoidStateType.Jumping) end
        end
    end)
    connect(workspace.DescendantAdded,function(obj)
        if obj.Name=="GunDrop" then roots[obj]=true end
        reduceEffect(obj)
    end)
    connect(RS.DescendantAdded,bindEvent)
    for _,obj in ipairs(RS:GetDescendants()) do bindEvent(obj) end
    for _,obj in ipairs(workspace:GetDescendants()) do if obj.Name=="GunDrop" then roots[obj]=true end end
    connect(RunService.Stepped,function() if alive and flags.noclip then movement() end end)
    local slow,fast=0,0
    connect(RunService.Heartbeat,function(dt)
        if not alive then return end
        slow=slow+dt fast=fast+dt
        if slow>=1 then
            slow=0 refreshWorld() movement()
            if spectating then
                local h=spectating.Character and spectating.Character:FindFirstChildOfClass("Humanoid")
                if not h or h.Health<=0 then restoreCamera()
                elseif workspace.CurrentCamera then workspace.CurrentCamera.CameraSubject=h end
            end
        end
        if fast>=0.25 then fast=0 render() autoWalk(os.clock()) end
    end)
    refreshWorld()
    function E.refreshESP(rolesWanted) refreshWorld();if rolesWanted then E.queryRoles(true)end end
    function E.inspect() return {map=cachedMap,coins=coins,guns=droppedGuns,waypoint=waypoint,flags=flags} end
    function E.role(p) local r=validRole(p); return r and r.role or nil end
    function E.roleState(p) local r=validRole(p); return r and r.role or nil,r and r.inactive==true or false end
    function E.opposingRole(selfRole,otherRole)
        if selfRole=='Murderer'or selfRole=='Zombie'then
            return otherRole=='Sheriff'or otherRole=='Hero'or otherRole=='Innocent'or otherRole=='Survivor'
        end
        return otherRole=='Murderer'or otherRole=='Zombie'
    end
    function E.mark(...) return mark(...) end
    function E.finishMarks(keep)
        local remove={};for key in pairs(visual)do if not keep[key]then remove[#remove+1]=key end end
        for _,key in ipairs(remove)do clearVisual(key)end
    end
    function E.teleport(cf) return teleportTo(cf) end
    function E.clearWaypoint()waypoint=nil end
    function E.setWaypoint(cf)waypoint={cf=cf,map=cachedMap}end
    return E
end



-- NEBULA CLOUD · ซาลาเปา 500. On-demand inspection, reversible local changes, bounded records.
local function createRubyPlus(ctx,core,catalog,shared)
    local X={};local O=ctx.options;local defs,enabled,created,stateBackups={},{},{},{}
    local bookmarks,route={},{};local routeIndex,routeClock=1,0
    local savedCamera,snapshot,snapshotActive=nil,nil,nil;local elapsed,timerBorn=0,0
    local frameTimes={};local framesTotal=0;local destroyed=false
    local caches={};local owned=setmetatable({},{__mode='k'})
    local function fail(s)error('RUBY: '..s,0)end
    local function find(name)
        if ctx.gui.Name==name then return ctx.gui end
        for _,obj in ipairs(ctx.gui:GetDescendants())do if obj.Name==name then return obj end end
    end
    local function finite(n)return type(n)=='number'and n==n and math.abs(n)<math.huge end
    local function number(n,lo,hi)if not finite(n)or n<lo or n>hi then fail('Number is outside the supported range')end;return n end
    local function vector(value,lo,hi)
        local a,b,c=tostring(value):match('^%s*([%+%-%.%d]+)%s*,%s*([%+%-%.%d]+)%s*,%s*([%+%-%.%d]+)%s*$')
        return Vector3.new(number(tonumber(a),lo,hi),number(tonumber(b),lo,hi),number(tonumber(c),lo,hi))
    end
    local function parse(d,value)
        if d.valueType=='color'then local v=vector(value,0,255);return Color3.fromRGB(v.X,v.Y,v.Z)end
        if d.valueType=='vector'then return vector(value,-360,360)end
        if d.valueType=='reverb'then return Enum.ReverbType[value]end
        return value
    end
    local function own(obj)
        local p=obj
        while p do if p==ctx.gui or owned[p]or p.Name:find('^RUBY_')then return true end;p=p.Parent end
        return false
    end
    local function objlist(class)
        if not caches[class]then
            local out={};local seen={}
            for _,root in ipairs({workspace,ctx.Lighting,game:GetService('SoundService'),ctx.me:FindFirstChild('Backpack')})do
                if root then for _,obj in ipairs(root:GetDescendants())do
                    if #out>=20000 then break end
                    if not seen[obj]and not own(obj)and obj:IsA(class)then out[#out+1]=obj;seen[obj]=true end
                end end
            end;caches[class]=out
        end
        local out={};for _,obj in ipairs(caches[class])do if obj.Parent then out[#out+1]=obj end end
        return out
    end
    local function new(class,parent)
        local o=Instance.new(class);owned[o]=true;o.Name='SALAPAO_Plus_'..class;o.Parent=parent;created[#created+1]=o;return o
    end
    local function target(d)
        local name=d.target
        if d.batch then return objlist(name)end
        if name=='Lighting'then return {ctx.Lighting}end
        if name=='Terrain'then return {workspace.Terrain}end
        if name=='SoundService'then return {game:GetService('SoundService')}end
        if name=='Humanoid'then local _,h=shared.char();if not h then fail('Character is not ready')end;return {h}end
        local parent=name=='Clouds'and workspace.Terrain or ctx.Lighting
        local o=parent:FindFirstChildOfClass(name)
        if not o then o=new(name,parent)end
        return {o}
    end
    local function write(d,obj,prop,value)
        if not shared.mutate(d.id,obj,prop,value)then fail('Cannot write '..obj.ClassName..'.'..prop..' on this client')end
    end
    local function property(d,value)
        local v=parse(d,value);local items=target(d)
        if #items==0 then fail('No visible '..d.target..' objects are available')end
        for i,obj in ipairs(items)do write(d,obj,d.prop,v);if i%250==0 then task.wait()end end
        return #items
    end
    local function hideObject(d,obj)
        if d.prop=='parts'then
            for _,p in ipairs(obj:GetDescendants())do if p:IsA('BasePart')then write(d,p,'LocalTransparencyModifier',1)end end
        elseif d.prop=='stash'then
            if not X.stash then X.stash=new('Folder',ctx.gui)end
            write(d,obj,'Parent',X.stash)
        else write(d,obj,d.prop,d.hidden)end
    end
    local function encode(v)return ctx.HttpService:JSONEncode(v)end
    local function decode(raw)
        if type(raw)~='string'or #raw>100000 then fail('JSON document must be under 100000 bytes')end
        local ok,v=pcall(function()return ctx.HttpService:JSONDecode(raw)end)
        if not ok or type(v)~='table'then fail('Invalid JSON document')end;return v
    end
    local function copy(v)if type(setclipboard)~='function'then fail('Clipboard API is unavailable')end;setclipboard(tostring(v));return v end
    local function point(v)
        if type(v)~='table'then fail('Expected an x,y,z record')end
        return Vector3.new(number(v.x,-1000000,1000000),number(v.y,-1000000,1000000),number(v.z,-1000000,1000000))
    end
    local function position(p)return {x=p.X,y=p.Y,z=p.Z}end
