            local ch,h,r=shared.char(p)
            if h and h.Health>0 and r then
                local good=true
                if mode=='knife'then good=ch:FindFirstChild('Knife')~=nil or core.role(p)=='Murderer'end
                if mode=='gun'then good=ch:FindFirstChild('Gun')~=nil or core.role(p)=='Sheriff'end
                if mode=='same_team'then good=p.Team~=nil and p.Team==ctx.me.Team end
                if good then candidates[#candidates+1]={p=p,h=h,r=r,d=(r.Position-selfRoot.Position).Magnitude}end
            end
        end end
        if #candidates==0 then fail('No matching living player')end
