    function X.tick(dt)
        if destroyed then return end
        elapsed=elapsed+dt;framesTotal=framesTotal+1;frameTimes[#frameTimes+1]=dt;if #frameTimes>120 then table.remove(frameTimes,1)end
        if O.plus_timer_enabled and elapsed-timerBorn>=O.plus_timer_seconds then shared.stop();return end
        routeClock=routeClock+dt
