            routeClock=routeClock%.25;local _,h,r=shared.char()
            if r and h and h.Health>0 then
                if O.plus_route_record and(#route==0 or(r.Position-point(route[#route])).Magnitude>=O.plus_route_spacing)then
                    if #route<128 then route[#route+1]=position(r.Position)else O.plus_route_record=false end
