            for id,v in pairs(checked)do setPoint(id,v)end
        elseif field=='raycast_a'then return raycast(p.a)
        elseif field=='raycast_camera'then local c=workspace.CurrentCamera;if not c then fail('Camera unavailable')end;return raycast(c.CFrame.Position)
        elseif field=='flatten_y'then for id,v in pairs(p)do setPoint(id,Vector3.new(v.X,p.a.Y,v.Z))end
