-- NEBULA CLOUD / ซาลาเปา: one owned, role-aware camera lock after the default camera.
local function createRubySuperLock(ctx,core,deps)
    local S={};local O=ctx.options;local gui=ctx.gui;local me=ctx.me
    local binding='NEBULA_RUBY_SuperLock_'..tostring(me.UserId)
    local bound,target,targetCharacter,body=false,nil,nil,nil
    local clock,nextAcquire=0,0
    local function status(state,p,role)
        gui:SetAttribute('SuperLockState',state)
        gui:SetAttribute('SuperLockTarget',p and p.Name or '')
        gui:SetAttribute('SuperLockTargetRole',role or '')
    end
    local function releaseBody()
        if body then deps.release('super_lock');body=nil end
    end
    local function clearTarget(state)
        target,targetCharacter=nil,nil;releaseBody();status(state or 'waiting')
    end
    function S.stop()
        if bound then ctx.RunService:UnbindFromRenderStep(binding);bound=false end
        clearTarget('off');clock,nextAcquire=0,0
        gui:SetAttribute('SuperLockActive',false)
    end
    local function holdingGun(character)
        local gun=character and character:FindFirstChild('Gun')
        return gun~=nil and gun:IsA('Tool')and gun.Parent==character
    end
    local function eligible(p,selfRole)
        if not p or p==me or p.Parent~=ctx.Players then return nil end
        local role,inactive=core.roleState(p)
        if inactive or not core.opposingRole(selfRole,role)then return nil end
        local ch,h,r=deps.char(p)
        if not ch or not h or h.Health<=0 or not r or not r.Parent then return nil end
        return ch,h,r,role
    end
    local function step(dt)
        if not O.super_lock then S.stop();return end
        clock=clock+math.max(0,dt)
        local camera=workspace.CurrentCamera
        local character,h,r=deps.char()
        local selfRole,selfInactive=core.roleState(me)
        if not camera or not r or not h or h.Health<=0 or selfInactive then clearTarget('noCharacter');return end
        if not holdingGun(character)then clearTarget('waitingGun');nextAcquire=0;return end
        local ch,_,targetRoot,role=eligible(target,selfRole)
        if target and (not ch or ch~=targetCharacter)then clearTarget();nextAcquire=0;ch,targetRoot,role=nil,nil,nil end
        if not target and clock>=nextAcquire then
            nextAcquire=clock+.1
            local bestDistance=math.huge
            for _,p in ipairs(ctx.Players:GetPlayers())do
                local candidate,_,part,candidateRole=eligible(p,selfRole)
                if candidate then
                    local distance=(part.Position-r.Position).Magnitude
                    if distance<bestDistance then
                        bestDistance=distance;target,targetCharacter=p,candidate;ch,targetRoot,role=candidate,part,candidateRole
                    end
                end
            end
        end
        if not targetRoot then releaseBody();status('waiting');return end
        -- The manual fire action uses the same center point for R6 and R15.
        local goal=targetRoot.Position
        local delta=goal-camera.CFrame.Position
        if delta.Magnitude>.001 then
            local up=math.abs(delta.Unit.Y)>.999 and Vector3.new(1,0,0)or Vector3.new(0,1,0)
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,goal,up)
        end
        if body~=h then releaseBody();body=h end
        deps.mutate('super_lock',h,'AutoRotate',false)
        local facing=Vector3.new(targetRoot.Position.X,r.Position.Y,targetRoot.Position.Z)
        if (facing-r.Position).Magnitude>.001 then r.CFrame=CFrame.lookAt(r.Position,facing)end
        status('locked',target,role)
    end
    function S.setEnabled(value)
        if not value then S.stop();return end
        if bound then return end
        gui:SetAttribute('SuperLockError',nil);local character=deps.char()
        clearTarget(holdingGun(character)and'waiting'or'waitingGun');clock,nextAcquire=0,0
        ctx.RunService:BindToRenderStep(binding,Enum.RenderPriority.Camera.Value+1,function(dt)
            local ok,err=pcall(step,dt)
            if not ok then
                O.super_lock=false;S.stop();status('error')
                gui:SetAttribute('SuperLockError',tostring(err):sub(1,180))
                if ctx.changed then ctx.changed()end
            end
        end)
        bound=true;gui:SetAttribute('SuperLockActive',true)
    end
    ctx.connect(ctx.Players.PlayerRemoving,function(p)if p==target then clearTarget();nextAcquire=0 end end)
    ctx.connect(me.CharacterAdded,function()clearTarget('noCharacter');nextAcquire=0 end)
    ctx.onCleanup(S.stop);status('off');gui:SetAttribute('SuperLockActive',false)
    return S
end

-- NEBULA CLOUD / ซาลาเปา: 50 equipment tools, real shared chat and explicit persistence.
local function createRubyEquipment(ctx,definitions,deps)
 local E={messages={},muted={},bookmarks={},savedIds={},draft='',attachment=nil,joined=false,view='live',version=nil,status='worldDisconnected',revision=0}
 local alive=true;local busy=false;local pending=false;local activeOperation;local epoch=0;local lastPoll=0;local saveAt=nil;local defaults,defs={},{}
 local O=ctx.options;local me=tostring(ctx.me.UserId);local file='SALAPAO_equipment_'..me..'.json'
 for _,d in ipairs(definitions)do if d.equipment then defs[d.id]=d;defaults[d.id]=d.default end end
 local function word(k)return ctx.translate(k)end
 local function changed()if not alive then return end;E.revision=E.revision+1;ctx.gui:SetAttribute('EquipmentRevision',E.revision);ctx.gui:SetAttribute('WorldJoined',E.joined);ctx.gui:SetAttribute('WorldMessageCount',#E.messages);ctx.gui:SetAttribute('WorldBusy',busy);if deps.render then deps.render(E)end end
 local function fail(k)error(word(k),0)end
 local function status(k)E.status=k;changed()end
 local function api(method,path,body,raw)
  local data,code,err=deps.api(method,path,body,raw)
  if not data then error(tostring(err or('HTTP '..tostring(code))),0)end;return data
 end
 local function transaction(fn,operation)
  if pending then fail('worldBusy')end
  pending=true;activeOperation=operation;busy=true;local token=epoch;status('worldWorking')
  if operation and ctx.health then ctx.health.record(operation,'pending')end
  task.spawn(function()
   local ok,result=pcall(fn,function()return alive and token==epoch end)
   pending=false;activeOperation=nil;if not alive or token~=epoch then return end
   busy=false;E.status=ok and'worldReady'or'worldError';E.error=not ok and tostring(result)or nil
   if operation and ctx.health then ctx.health.record(operation,ok and'done'or'error',not ok and result or nil)end;changed()
  end);return true
 end
 local function checkedMessages(list)
  if type(list)~='table'or #list>100 then fail('worldInvalid')end
  local out,seen={},{}
  for _,m in ipairs(list)do
   if type(m)~='table'or type(m.id)~='string'or #m.id~=36 or not m.id:match('^[%x%-]+$')or type(m.authorId)~='string'or not m.authorId:match('^%d+$')or type(m.text)~='string'or #m.text>8000 or type(m.seq)~='number'or type(m.createdAt)~='number'then fail('worldInvalid')end
   if not seen[m.id]then
    local image=m.image
    if image and(type(image)~='table'or type(image.id)~='string'or #image.id~=36 or not image.id:match('^[%x%-]+$')or image.url~='/api/v1/world/images/'..image.id or type(image.bytes)~='number'or image.bytes>1048576 or not({['image/png']=true,['image/jpeg']=true,['image/webp']=true})[image.mime])then fail('worldInvalid')end
    out[#out+1]={id=m.id,seq=m.seq,authorId=m.authorId,text=m.text,createdAt=m.createdAt,image=image};seen[m.id]=true
   end
  end
  table.sort(out,function(a,b)return a.seq<b.seq end);return out
 end
 local function idList(set)local out={};for id,on in pairs(set)do if on then out[#out+1]=id end end;table.sort(out);return out end
 function E.snapshot(includeMemory)
  local options={};for id,d in pairs(defs)do if d.default~=nil and d.field~='import_settings'and d.field~='world_mute_user'then options[id]=O[id]end end
  local data={schema=1,options=options,mutes=idList(E.muted),bookmarks=idList(E.bookmarks),savedMessageIds=E.savedIds,draft=E.draft}
  if includeMemory and ctx.memorySnapshot then data.memory=ctx.memorySnapshot()end
  return data
 end
 local function validate(doc)
  if type(doc)~='table'or doc.schema~=1 or type(doc.options)~='table'or type(doc.draft)~='string'or #doc.draft>8000 then fail('worldInvalid')end
  local options={}
  for id,d in pairs(defs)do if d.default~=nil and d.field~='import_settings'and d.field~='world_mute_user'then
   local v=doc.options[id];if v==nil then v=d.default end
   if d.kind=='toggle'and type(v)~='boolean'or d.kind=='number'and(type(v)~='number'or v~=v or v<d.min or v>d.max)or d.kind=='text'and(type(v)~='string'or #v>300)then fail('worldInvalid')end
   if id=='eq_fire_color'then local r,g,b=tostring(v):match('^(%d+),(%d+),(%d+)$');if not r or tonumber(r)>255 or tonumber(g)>255 or tonumber(b)>255 then fail('worldInvalid')end end
   options[id]=v
  end end
  local sets={}
  for _,key in ipairs({'mutes','bookmarks','savedMessageIds'})do
   local values=doc[key]or{};if type(values)~='table'or #values>100 then fail('worldInvalid')end
   sets[key]={};for _,id in ipairs(values)do if type(id)~='string'or(key=='mutes'and not id:match('^%d+$'))or(key~='mutes'and(#id~=36 or not id:match('^[%x%-]+$')))then fail('worldInvalid')end;sets[key][#sets[key]+1]=id end
  end
  return {schema=1,options=options,draft=doc.draft,mutes=sets.mutes,bookmarks=sets.bookmarks,savedMessageIds=sets.savedMessageIds}
 end
 local function apply(doc)
  local data=validate(doc)
  for id,v in pairs(data.options)do O[id]=v end
  E.draft=data.draft;E.muted={};for _,id in ipairs(data.mutes)do E.muted[id]=true end
  E.bookmarks={};for _,id in ipairs(data.bookmarks)do E.bookmarks[id]=true end;E.savedIds=data.savedMessageIds
  if deps.draft then deps.draft(E.draft)end
  ctx.changed();changed()
 end
 local function localSave()
  if type(writefile)~='function'then fail('worldFileUnsupported')end
  local doc={schema=1,userId=me,data=E.snapshot(),messages=E.messages};local encoded=ctx.HttpService:JSONEncode(doc)
  if #encoded>400000 then fail('worldInvalid')end;writefile(file,encoded);E.localSaved=true;return true
 end
 local function cloudSave(accept)
  if E.version==nil then local current=api('GET','/api/v1/ruby-equipment');if not accept()then return end;E.version=current.version end
  local result=api('PUT','/api/v1/ruby-equipment',{expectedVersion=E.version,data=E.snapshot()});if not accept()then return end;E.version=result.version
 end
 function E.saveMemoryCloud()
  if not ctx.memorySnapshot then fail('hmInvalid')end
  return transaction(function(accept)
   local current=api('GET','/api/v1/ruby-equipment');if not accept()then return end
   local data=current.data or E.snapshot();data.memory=ctx.memorySnapshot()
   local result=api('PUT','/api/v1/ruby-equipment',{expectedVersion=current.version,data=data});if accept()then E.version=result.version end
  end,'memory_center')
 end
 function E.loadMemoryCloud()
  if not ctx.memoryRestore then fail('hmInvalid')end
  return transaction(function(accept)
   local current=api('GET','/api/v1/ruby-equipment');if not accept()then return end
   if not current.data or not current.data.memory then fail('worldNoSaved')end
   ctx.memoryRestore(current.data.memory);E.version=current.version
  end,'memory_center')
 end
 local function refresh(accept,before)
  local data=api('GET','/api/v1/world/messages'..(before and('?before='..tostring(before))or''));if not accept()then return end
  local list=checkedMessages(data.messages)
  if before then for _,m in ipairs(E.messages)do list[#list+1]=m end;while #list>100 do table.remove(list)end;E.messages=checkedMessages(list);E.view='archive'
  else E.messages=list;E.view='live'end;lastPoll=os.clock()
 end
 function E.visible()
  local out={};local q=tostring(O.eq_world_search or''):lower()
  for _,m in ipairs(E.messages)do
   if not E.muted[m.authorId]and(not O.eq_world_only_mine or m.authorId==me)and(not O.eq_world_bookmarks_only or E.bookmarks[m.id])and(q==''or(m.text..' '..m.authorId):lower():find(q,1,true))then out[#out+1]=m end
  end;return out
 end
 local function latest(own)
  local list=E.visible();for i=#list,1,-1 do if not own or list[i].authorId==me then return list[i]end end;fail('worldNoMessages')
 end
 local function clipboard(value)if type(setclipboard)~='function'then fail('worldClipboardUnsupported')end;setclipboard(value);return value end
 function E.leave()epoch=epoch+1;busy=false;E.joined=false;if activeOperation and ctx.health then ctx.health.record(activeOperation,'cancelled')end;activeOperation=nil;status('worldDisconnected')end
 function E.send(raw)
  if pending then fail('worldBusy')end
  local text=tostring(raw or E.draft):match('^%s*(.-)%s*$');if not E.joined then fail('worldJoinFirst')end
  if text==''and not E.attachment then fail('worldEmpty')end;if #text>8000 then fail('worldInvalid')end
  local image=E.attachment and E.attachment.id or nil
  if not E.retry or E.retry.text~=text or E.retry.imageId~=image then E.retry={text=text,imageId=image,clientId=deps.guid()}end
  return transaction(function(accept)
   api('POST','/api/v1/world/messages',E.retry);if not accept()then return end
   E.retry=nil
   if E.draft:match('^%s*(.-)%s*$')==text then E.draft='';if deps.draft then deps.draft('')end end
   if E.attachment and E.attachment.id==image then E.attachment=nil end
   refresh(accept)
  end)
 end
 function E.setDraft(value)
  local raw=tostring(value);local limited=raw
  if utf8 and utf8.codes then
   local count=0;for position,codepoint in utf8.codes(raw)do count=count+(codepoint>65535 and 2 or 1);if count>2000 then limited=raw:sub(1,position-1);break end end
  elseif #raw>2000 then local cut=2000;while cut>0 and raw:byte(cut+1)>=128 and raw:byte(cut+1)<192 do cut=cut-1 end;limited=raw:sub(1,cut)end
  E.draft=limited;if limited~=raw and deps.draft then deps.draft(limited)end
  if O.eq_auto_save then saveAt=os.clock()+2 end
  if ctx.memoryDirty then ctx.memoryDirty()end
 end
 function E.set(field,value,d)
  if d and(d.kind=='toggle'or d.kind=='number'or(d.kind=='text'and field~='import_settings'and field~='world_mute_user'))then
   if field=='fire_color'then local r,g,b=tostring(value):match('^(%d+),(%d+),(%d+)$');if not r or tonumber(r)>255 or tonumber(g)>255 or tonumber(b)>255 then fail('worldInvalid')end end
   if d.kind=='text'and(type(value)~='string'or #value>300)then fail('worldInvalid')end
   O[d.id]=value;if O.eq_auto_save then saveAt=os.clock()+2 end;changed();return value
  end
  if field=='fire_reset'then for id,default in pairs(defaults)do if id:match('^eq_fire_')then O[id]=default end end;ctx.changed();changed()
  elseif field=='world_open'then deps.open();changed()
  elseif field=='world_join'then return transaction(function(accept)local data=api('GET','/api/v1/world/session');if not accept()then return end;if tostring(data.robloxId)~=me then fail('wrongAccount')end;E.joined=true;refresh(accept)end,d and d.id)
  elseif field=='world_leave'then E.leave()
  elseif field=='world_refresh'then return transaction(function(accept)refresh(accept)end,d and d.id)
  elseif field=='world_load_older'then local first=E.messages[1];if not first then fail('worldNoMessages')end;return transaction(function(accept)refresh(accept,first.seq)end,d and d.id)
  elseif field=='world_clear_view'then E.messages={};E.view='archive';changed()
  elseif field=='world_copy_latest'then return clipboard(latest().text)
  elseif field=='world_copy_transcript'then local out={};for _,m in ipairs(E.visible())do out[#out+1]='Roblox #'..m.authorId..': '..m.text end;return clipboard(table.concat(out,'\n'))
  elseif field=='world_export'then return ctx.HttpService:JSONEncode({schema=1,messages=E.visible()})
  elseif field=='world_bookmark_latest'then local m=latest();E.bookmarks[m.id]=not E.bookmarks[m.id];if #idList(E.bookmarks)>100 then E.bookmarks[m.id]=nil;fail('worldInvalid')end;changed()
  elseif field=='world_mute_user'then local id=tostring(value):match('^%s*(%d+)%s*$');if not id or #id>20 or id==me or #idList(E.muted)>=100 then fail('worldInvalid')end;E.muted[id]=true;changed()
  elseif field=='world_unmute_all'then E.muted={};changed()
  elseif field=='world_report_latest'then local id=latest().id;return transaction(function()api('POST','/api/v1/world/reports',{messageId=id})end,d and d.id)
  elseif field=='world_delete_own_latest'then local id=latest(true).id;return transaction(function(accept)api('DELETE','/api/v1/world/messages/'..id);refresh(accept)end,d and d.id)
  elseif field=='world_stats'then return ctx.HttpService:JSONEncode({joined=E.joined,view=E.view,messages=#E.messages,visible=#E.visible(),muted=#idList(E.muted),bookmarks=#idList(E.bookmarks),busy=busy})
  elseif field=='world_image_remove'then E.attachment=nil;changed()
  elseif field=='world_open_upload_page'then return clipboard(ctx.cloud..'/community')
  elseif field=='world_copy_image_link'then local image=E.attachment;for i=#E.messages,1,-1 do if image then break end;image=E.messages[i].image end;if not image then fail('worldNoImage')end;return clipboard(ctx.cloud..image.url)
  elseif field=='world_attachment_report'then return ctx.HttpService:JSONEncode({attachment=E.attachment or false,maximumBytes=1048576,formats={'PNG','JPEG','WebP'}})
  elseif field=='world_upload_image'then
   if type(readfile)~='function'then fail('worldFileUnsupported')end
   local path=tostring(O.eq_world_image_path or'');if path==''or path:find('..',1,true)or path:match('^[/\\]')or path:find(':',1,true)or #path>240 then fail('worldImagePath')end
   local bytes=readfile(path);if type(bytes)~='string'or #bytes>1048576 then fail('worldImageLimit')end
   local mime=bytes:sub(1,8)=='\137PNG\r\n\26\n'and'image/png'or bytes:sub(1,2)=='\255\216'and'image/jpeg'or(bytes:sub(1,4)=='RIFF'and bytes:sub(9,12)=='WEBP'and'image/webp')
   if not mime then fail('worldImageLimit')end
   return transaction(function(accept)local data=api('POST','/api/v1/world/images',bytes,{['Content-Type']=mime,['X-Upload-ID']=deps.guid()});if not accept()then return end;E.attachment=data.image;changed()end,d and d.id)
  elseif field=='export_settings'then return ctx.HttpService:JSONEncode(E.snapshot())
  elseif field=='import_settings'then local ok,data=pcall(function()return ctx.HttpService:JSONDecode(value)end);if not ok then fail('worldInvalid')end;apply(data)
  elseif field=='save_local'then localSave();status('worldSaved')
  elseif field=='load_local'then
   if type(readfile)~='function'then fail('worldFileUnsupported')end;local raw=readfile(file);if type(raw)~='string'or #raw>400000 then fail('worldInvalid')end
   local doc=ctx.HttpService:JSONDecode(raw);if type(doc)~='table'or tostring(doc.userId)~=me then fail('worldInvalid')end;apply(doc.data);E.localMessages=checkedMessages(doc.messages or{});status('worldSaved')
  elseif field=='save_cloud'then return transaction(cloudSave,d and d.id)
  elseif field=='load_cloud'then return transaction(function(accept)local data=api('GET','/api/v1/ruby-equipment');if not accept()then return end;if not data.data then fail('worldNoSaved')end;apply(data.data);E.version=data.version end,d and d.id)
  elseif field=='world_save_history'then E.savedIds={};for _,m in ipairs(E.messages)do E.savedIds[#E.savedIds+1]=m.id end;return transaction(function(accept)cloudSave(accept);if accept()and type(writefile)=='function'then localSave()end end,d and d.id)
  elseif field=='world_load_saved_history'then return transaction(function(accept)local data=api('GET','/api/v1/ruby-equipment?history=1');if not accept()then return end;E.messages=checkedMessages(data.messages or{});E.version=data.version;E.view='archive'end,d and d.id)
  elseif field=='save_report'then return ctx.HttpService:JSONEncode({schema=1,localFile=file,localSaved=E.localSaved==true,cloudVersion=E.version or 0,savedMessages=#E.savedIds,autoSave=O.eq_auto_save==true})
  else fail('worldInvalid')end
  return true
 end
 local elapsed=0
 ctx.connect(ctx.RunService.Heartbeat,function(dt)
  elapsed=elapsed+dt;if elapsed<.5 then return end;elapsed=elapsed%.5
  if saveAt and os.clock()>=saveAt and O.eq_auto_save then saveAt=nil;local ok,err=pcall(localSave);if not ok then E.status='worldError';E.error=tostring(err);changed()end end
  if E.joined and E.view=='live'and O.eq_world_auto_refresh and deps.visible()and not pending and os.clock()-lastPoll>=(O.eq_world_poll_seconds or 8)then
   lastPoll=os.clock();transaction(function(accept)refresh(accept)end)
  end
 end)
 ctx.onCleanup(function()alive=false;epoch=epoch+1;E.joined=false end)
 E.validate=validate;E.changed=changed;return E
end

-- NEBULA CLOUD / ซาลาเปา: explicit one-click shots through the currently equipped MM2 gun.
local function createRubyExtra(ctx,core,deps)
    local X={};local alive=true;local pending=false;local revision=0
    local nextShot=-math.huge;local worker;local sent=0
    local gui=ctx.gui
    local function message(key)return ctx.translate(key)end
    local function state(key,target)
        if not alive then return end
        gui:SetAttribute('ExtraShotState',key);gui:SetAttribute('ExtraShotTarget',target or'')
        gui:SetAttribute('ExtraShotBusy',pending)
    end
    local function fail(key)error(message(key),0)end
    local function gunReady()
        local ch,h,r=deps.char()
        if not ch or not h or h.Health<=0 or not r then fail('extraNoCharacter')end
        local _,inactive=core.roleState(ctx.me);if inactive then fail('extraNoCharacter')end
        local gun=ch:FindFirstChild('Gun')
        if not gun or not gun:IsA('Tool')or gun.Parent~=ch then fail('extraNeedGun')end
        if gun.Enabled==false then fail('extraGunNotReady')end
        return ch,gun,r
    end
    local function visible(ch,origin,part)
        if deps.isVisible then return deps.isVisible(ch,origin,part)end
        local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances={ch};params.IgnoreWater=true
        local hit=workspace:Raycast(origin,part.Position-origin,params)
        return not hit or hit.Instance:IsDescendantOf(part.Parent)
    end
    local function opponent(origin,wallMode,ch)
        local best,part,character;local distance=math.huge
        local selfRole=core.roleState(ctx.me)
        local locked=ctx.options.super_lock and gui:GetAttribute('SuperLockState')=='locked'and gui:GetAttribute('SuperLockTarget')
        for _,p in ipairs(ctx.Players:GetPlayers())do if p~=ctx.me and p.Parent==ctx.Players then
            local role,inactive=core.roleState(p);local ch,h,r=deps.char(p)
            if core.opposingRole(selfRole,role)and not inactive and ch and h and h.Health>0 and r and r.Parent
                and(wallMode or visible(ctx.me.Character,origin,r))then
                if locked and p.Name==locked then return p,r,ch end
                local d=(r.Position-origin).Magnitude
                if d<distance then best,part,character,distance=p,r,ch,d end
            end
        end end
        return best,part,character
    end
    local function route(ch,gun)
        local event=gun:FindFirstChild('Shoot')
        if event then
            if not event:IsA('RemoteEvent')then fail('extraUnsupported')end
            local hand=ch:FindFirstChild('RightHand')or ch:FindFirstChild('Right Arm')or gun:FindFirstChild('Handle')
            if not hand or not hand:IsA('BasePart')then fail('extraUnsupported')end
            return event,'Shoot',hand
        end
        local localScript=gun:FindFirstChild('KnifeLocal')
        local beam=localScript and localScript:FindFirstChild('CreateBeam')
        local remote=beam and beam:FindFirstChild('RemoteFunction')
        if not remote or not remote:IsA('RemoteFunction')then fail('extraUnsupported')end
        return remote,'CreateBeam'
    end
    function X.shoot()
        if not alive then fail('extraCancelled')end
        if pending then fail('extraPending')end
        if os.clock()<nextShot then fail('extraCooldown')end
        local ch,gun,r=gunReady()
        local wallMode=ctx.options.shot_through_walls~=false
        local target,part,targetCharacter=opponent(r.Position,wallMode,ch)
        if not target then core.queryRoles(true);target,part,targetCharacter=opponent(r.Position,wallMode,ch)end
        if not target then fail(wallMode and'extraNoMurderer'or'extraVisibleTarget')end
        gui:SetAttribute('ExtraShotMode',wallMode and'IgnoreWalls'or'VisibleOnly')
        local remote,method,hand=route(ch,gun)
        local token=revision;pending=true;state('sending',target.Name)
        nextShot=os.clock()+1
        local timedOut=false
        local function dispatch()
            -- Recheck the same character, gun and role immediately before this one request.
            local ok=pcall(function()
                if not alive or token~=revision or ctx.me.Character~=ch or gun.Parent~=ch then fail('extraCancelled')end
                gunReady()
                local currentRole,dead=core.roleState(target)
                local selfRole=core.roleState(ctx.me)
                local current,humanoid,root=deps.char(target)
                if target.Parent~=ctx.Players or current~=targetCharacter or not humanoid or humanoid.Health<=0 or not root or not root.Parent or dead or not core.opposingRole(selfRole,currentRole)then fail('extraNoMurderer')end
                if not wallMode and not visible(ch,r.Position,root)then fail('extraBlocked')end
                local aim=root.Position
                gui:SetAttribute('ExtraShotMethod',method)
                if method=='Shoot'then remote:FireServer(CFrame.new(hand.Position),CFrame.new(aim))
                else remote:InvokeServer(1,aim,'AH2')end
            end)
            pending=false
            if alive then gui:SetAttribute('ExtraShotBusy',false)end
            if not alive or token~=revision then return end
            if timedOut then return end
            if ok then sent=sent+1;gui:SetAttribute('ExtraShotCount',sent);state('sent',target.Name)
            else state('failed',target.Name)end
        end
        if method=='Shoot'then dispatch()else
            worker=task.spawn(dispatch)
            task.delay(6,function()
                if alive and token==revision and pending then timedOut=true;state('timeout',target.Name)end
            end)
        end
        return true
    end
    function X.stop()
        revision=revision+1
        -- A sent server request cannot be retracted; retain its in-flight guard until it finishes.
        state(pending and'cancelled'or'idle')
    end
    ctx.onCleanup(function()
        alive=false;revision=revision+1
        if worker and type(task.cancel)=='function'then pcall(task.cancel,worker)end
    end)
    gui:SetAttribute('ExtraShotCount',0);state('idle')
    return X
end

