-- NEBULA CLOUD | Salapao v1.0.4 | Local movement controller; currency is server-owned.
local function createSalapaoFarm(ctx,core,deps)
    local F={};local O=ctx.options;local alive=true
    local target,mapSeen,reachedAt,lastStep,mapAt,born,attemptedAt=nil,nil,nil,nil,0,0,0
    local attempted,reached,skipped=0,0,0
    local visited=setmetatable({},{__mode='k'})
    local function status(key,part)
        if not alive then return end
        ctx.gui:SetAttribute('FarmState',key)
        ctx.gui:SetAttribute('FarmTarget',part and part.Name or '')
        ctx.gui:SetAttribute('FarmTargetsReached',reached)
        ctx.gui:SetAttribute('FarmTargetsSkipped',skipped)
    end
    local function halt(key)
        local _,h,r=deps.char()
        if h and r then h:MoveTo(r.Position)end
        status(key)
    end
    function F.reset(key,clear)
        target=nil;reachedAt=nil;lastStep=nil;mapSeen=nil
        if clear then
            visited=setmetatable({},{__mode='k'});attempted=0;reached=0;skipped=0;born=ctx.now()
        end
        halt(key or 'stopped')
    end
    function F.stats()
        return {attempted=attempted,reached=reached,skipped=skipped,elapsed=math.max(0,ctx.now()-born)}
    end
    function F.tick(coins,map,now)
        if not alive then return end
        if not O.auto_coins then halt('stopped');return end
        local ch,h,r=deps.char()
        if not ch or not h or not r or h.Health<=0 then target=nil;status('dead');return end
        if not map then target=nil;reachedAt=nil;mapSeen=nil;halt('waiting_round');return end
        if map~=mapSeen then
            target=nil;reachedAt=nil;lastStep=nil;mapSeen=map;mapAt=now
            visited=setmetatable({},{__mode='k'})
        end
        local _,inactive=core.roleState(ctx.me)
        if inactive then target=nil;reachedAt=nil;halt('waiting_round');return end
        if now-mapAt<(O.plus_farm_resume_delay or 0)then halt('waiting_round');return end
        if h.Health<(O.plus_farm_health or 1)or r.Position.Y<(O.plus_farm_safe_height or -100)then halt('paused_safety');return end
        if O.plus_farm_ground and deps.inAir(h)then halt('paused_safety');return end
        if O.plus_farm_typing and deps.typing()then halt('paused_typing');return end
        if O.plus_farm_equipped and ch:FindFirstChildOfClass('Tool')then halt('paused_equipped');return end
        if (O.plus_farm_stop_limit and reached>=(O.plus_farm_limit or 100))
            or(O.plus_farm_stop_time and now-born>=(O.plus_farm_duration or 3600))then
            O.auto_coins=false;core.set('autoCoins',false);target=nil;halt('limit')
            if ctx.changed then ctx.changed()end;return
        end
        if O.plus_farm_confirm_map then
            local _,distance=deps.nearest(deps.spawns())
            if distance>100 then halt('waiting_round');return end
        end
        local danger,distance=deps.threat()
        if O.avoid_murderer and danger and distance<(O.avoid_radius or 25)then
            local _,_,other=deps.char(danger)
            local away=other and(r.Position-other.Position)
            if away and away.Magnitude>0 then h:MoveTo(r.Position+away.Unit*(O.avoid_radius or 25))end
            target=nil;reachedAt=nil;status('avoiding');return
        end
        if target then
            if not target.Parent or not target:IsDescendantOf(map)then target=nil;reachedAt=nil
            else
                local near=(target.Position-r.Position).Magnitude<=(O.plus_farm_reach or 3)
                if near and not reachedAt then reached=reached+1;reachedAt=now end
                if reachedAt then
                    h:MoveTo(r.Position);status('contact',target)
                    if now-reachedAt<.45 then return end
                    visited[target]=now+math.max(.5,O.plus_farm_cooldown or 8)
                    target=nil;reachedAt=nil
                elseif now-attemptedAt>(O.plus_farm_timeout or 6)then
                    skipped=skipped+1
                    if O.skip_stuck_coin then visited[target]=now+(O.plus_farm_cooldown or 8)end
                    if O.farm_jump_stuck then h.Jump=true end
                    target=nil
                end
            end
        end
        if not target then
            local best,scoreBest
            for _,part in ipairs(coins or {})do
                if part.Parent and part:IsDescendantOf(map)and(visited[part]or 0)<=now then
                    local distance=(part.Position-r.Position).Magnitude
                    local accept=distance<=(O.farm_range or 250)
                        and(not O.pause_farm_near_lobby or distance<250)
                        and math.abs(part.Position.Y-r.Position.Y)<=(O.plus_farm_y or 100)
                    if O.plus_farm_ignore_tiny and part.Size.Magnitude<.25 then accept=false end
                    if O.plus_farm_visible and not deps.visible(part)then accept=false end
                    local sort=O.plus_farm_sort or 'Nearest'
                    local score=sort=='Farthest'and-distance or sort=='Lowest'and part.Position.Y
                        or sort=='Highest'and-part.Position.Y or distance
                    if accept and(not best or score<scoreBest)then best,scoreBest=part,score end
                end
            end
            target=best;attemptedAt=now
            if best then attempted=attempted+1 else halt('no_targets');return end
        end
        if not lastStep or now-lastStep>=math.max(.1,O.plus_farm_step or .25)then
            local step=lastStep and math.min(2,now-lastStep)or .25;lastStep=now
            deps.move(target.Position,step,O.farm_speed or 35,O.farm_mode or 'Walk')
        end
        status('moving',target)
    end
    function F.destroy()if not alive then return end;F.reset('stopped');alive=false end
    F.reset('stopped',true)
    return F
end

    -- NEBULA CLOUD / RUBY: observed client states, never a claim of server-side effects.
local function createRubyHealth(ctx,catalog)
 local H={records={},events={},revision=0};local defs={}
 for _,d in ipairs(catalog)do defs[d.id]=d end
 local function clipped(s,n)local cut=math.min(#s,n);while cut>0 and s:byte(cut+1)and s:byte(cut+1)>=128 and s:byte(cut+1)<192 do cut=cut-1 end;return s:sub(1,cut)end
 function H.redact(raw)
  return clipped(tostring(raw or''):gsub('neb_%x+','[token]'):gsub('AIza[%w_%-]+','[key]'):gsub('[Bb]earer%s+[^%s]+','Bearer [token]'),400)
 end
 function H.record(id,state,reason)
  if not defs[id]and id~='system:update'then return end
  local entry={id=id,state=state,reason=H.redact(reason),at=os.time()}
  H.records[id]=entry;H.events[#H.events+1]=entry;if #H.events>100 then table.remove(H.events,1)end
  H.revision=H.revision+1;ctx.gui:SetAttribute('HealthRevision',H.revision)
 end
 function H.snapshot(query,filter)
  local rows={};local count={total=#catalog,enabled=0,error=0,pending=0,untried=0}
  local code=ctx.gui:GetAttribute('Language')or'TH';query=tostring(query or''):lower()
  for _,d in ipairs(catalog)do
   local previous=H.records[d.id];local state
   if previous and(previous.state=='error'or previous.state=='pending'or previous.state=='cancelled')then state=previous.state
   elseif d.kind=='toggle'then state=ctx.options[d.id]==true and'enabled'or'off'
   elseif d.kind=='action'then state=previous and'done'or'untried'
   elseif d.kind=='report'then state=previous and'done'or'untried'
   else state='configured'end
   local memory=ctx.memory
   if d.id=='memory_center'and memory then if memory.state=='hmWriteError'or memory.state=='hmLoadError'or memory.state=='hmInvalid'then state='error'elseif memory.state=='hmNoFiles'then state='unavailable'end end
   if count[state]~=nil then count[state]=count[state]+1 end
   local label=d[code]or d[code:lower()]or d.en
   if(query==''or(d.id..' '..label):lower():find(query,1,true))and(not filter or filter=='all'or filter==state)then
    rows[#rows+1]={id=d.id,label=label,state=state,at=previous and previous.at or 0,reason=d.id=='memory_center'and ctx.memory and(state=='error'or state=='unavailable')and ctx.translate(ctx.memory.state)or previous and previous.reason or''}
   end
  end
  return rows,count
 end
 function H.report()
  local rows,count=H.snapshot('','all');local issues,enabled={},{}
  for _,row in ipairs(rows)do if row.state=='error'then issues[#issues+1]=row elseif row.state=='enabled'then enabled[#enabled+1]=row.id end end
  return {schema=1,brand='NEBULA CLOUD',version=ctx.gui:GetAttribute('Version'),scope='Observed client settings and request outcomes; game server effects are not verified',counts=count,issues=issues,enabled=enabled,events=H.events,updateError=H.records['system:update'],services=ctx.healthServices and ctx.healthServices()or{}}
 end
 return H
end

