    -- Share one one-second role/data poll across ESP and Super Lock.
    local ESP_INTERVAL=1
    local espElapsed,espActive,espRoles,espRefreshes=0,false,false,0
    local function tickESP(dt)
        local roleWanted=O.super_lock or O.player_esp or O.role_esp or O.tracers or O.boxes or O.head_markers or O.offscreen_arrows
        local wanted=roleWanted or O.coin_esp or O.gun_esp or O.spawn_esp or O.waypoint_esp
        if not wanted then
            espElapsed=0;espActive=false;espRoles=false;gui:SetAttribute('ESPAutoRefreshActive',false);return
        end
        local immediate=not espActive or(roleWanted and not espRoles)
        espActive=true;espRoles=roleWanted==true
        espElapsed=immediate and 0 or espElapsed+dt
        if immediate or espElapsed+1e-9>=ESP_INTERVAL then
            espElapsed=immediate and 0 or espElapsed%ESP_INTERVAL
            if espElapsed>ESP_INTERVAL-1e-8 then espElapsed=0 end
            core.refreshESP(espRoles);ctx.renderESP();espRefreshes=espRefreshes+1
            gui:SetAttribute('ESPRefreshCount',espRefreshes)
        end
        gui:SetAttribute('ESPAutoRefreshActive',true)
    end
    gui:SetAttribute('ESPRefreshInterval',ESP_INTERVAL)
    gui:SetAttribute('ESPRefreshCount',0)
    local filter
    local effects={
        hide_particles={'ParticleEmitter','Enabled',false},hide_trails={'Trail','Enabled',false},
        hide_beams={'Beam','Enabled',false},hide_smoke={'Smoke','Enabled',false},hide_fire={'Fire','Enabled',false},
        hide_sparkles={'Sparkles','Enabled',false},disable_bloom={'BloomEffect','Enabled',false},
        disable_blur={'BlurEffect','Enabled',false},disable_dof={'DepthOfFieldEffect','Enabled',false},
        disable_sunrays={'SunRaysEffect','Enabled',false},disable_color_correction={'ColorCorrectionEffect','Enabled',false},
        low_material={'BasePart','Material',Enum.Material.SmoothPlastic},hide_decals={'Decal','Transparency',1},
        hide_textures={'Texture','Transparency',1},hide_surface_guis={'SurfaceGui','Enabled',false},
        hide_billboard_guis={'BillboardGui','Enabled',false},hide_point_lights={'PointLight','Enabled',false},
        hide_spot_lights={'SpotLight','Enabled',false},hide_surface_lights={'SurfaceLight','Enabled',false},
        mute_sounds={'Sound','Volume',0},
    }
    local visualRevision=0
    local function visualObject(obj)
        if obj==filter then return end
        for id,spec in pairs(effects)do
            local matches=obj:IsA(spec[1]) and not (id=='hide_decals' and obj:IsA('Texture')) and not (id=='low_material' and obj:IsA('Terrain'))
            if O[id] and matches then mutate(id,obj,spec[2],spec[3])end
        end
        if O.mute_looped_sounds and obj:IsA('Sound') and obj.Looped then mutate('mute_looped_sounds',obj,'Volume',0)end
        if active.sound_volume and obj:IsA('Sound')then mutate('sound_volume',obj,'Volume',O.sound_volume)end
    end
    local function visualGlobals()
        if O.full_bright then
            mutate('full_bright',L,'Brightness',2);mutate('full_bright',L,'Ambient',Color3.fromRGB(180,180,180))
        end
        if O.no_fog then mutate('no_fog',L,'FogEnd',100000);mutate('no_fog',L,'FogStart',100000)end
        if O.no_shadows then mutate('no_shadows',L,'GlobalShadows',false)end
        if O.water_waves then mutate('water_waves',workspace.Terrain,'WaterWaveSize',0);mutate('water_waves',workspace.Terrain,'WaterWaveSpeed',0)end
        if O.terrain_decoration then
            if not mutate('terrain_decoration',workspace.Terrain,'Decoration',false)then fail('Terrain decoration is not writable in this client')end
        end
        for id,spec in pairs({water_transparency={workspace.Terrain,'WaterTransparency'},clock_time={L,'ClockTime'},exposure={L,'ExposureCompensation'}})do
            if active[id]then mutate(id,spec[1],spec[2],O[id])end
        end
        if active.saturation or active.contrast or active.color_tint then
            if not filter then filter=make('ColorCorrectionEffect',{Name='SALAPAO_LocalColorFilter'},L)end
            if active.saturation then mutate('saturation',filter,'Saturation',O.saturation)end
            if active.contrast then mutate('contrast',filter,'Contrast',O.contrast)end
        end
    end
    local function applyVisuals()
        visualGlobals();visualRevision=visualRevision+1;local revision=visualRevision
        task.spawn(function()
            local objects=list(workspace)
            for _,root in ipairs({L,game:GetService('SoundService')})do for _,obj in ipairs(list(root))do objects[#objects+1]=obj end end
            for i,obj in ipairs(objects)do
                if not alive or revision~=visualRevision then return end
                visualObject(obj);if i%200==0 then task.wait()end
            end
        end)
    end
    local function restoreLighting()
        for _,id in ipairs({'full_bright','no_fog','no_shadows','clock_time','exposure','saturation','contrast','color_tint','disable_bloom','disable_blur','disable_dof','disable_sunrays','disable_color_correction'})do
