    local function importPreferences(raw)
        local ok,data=pcall(function()return ctx.HttpService:JSONDecode(raw)end)
        if not ok or type(data)~='table' or data.version~=1 or type(data.values)~='table'then fail('Invalid preference JSON')end
        local checked={}
        for id,value in pairs(data.values)do
            local d=defs[id];if not d then fail('Unknown preference: '..tostring(id))end
            if d.kind=='toggle' and type(value)~='boolean'then fail('Invalid toggle: '..id)end
            if d.kind=='number' and (type(value)~='number' or value~=value or value<d.min or value>d.max)then fail('Invalid number: '..id)end
            if d.kind=='choice'then local found=false;for _,v in ipairs(d.choices)do if value==v then found=true end end;if not found then fail('Invalid choice: '..id)end end
            if d.kind~='toggle' and d.kind~='number' and d.kind~='choice'then fail('Preference is not writable: '..id)end
            checked[#checked+1]={id,value}
        end
        -- Validate the entire document before applying any changes.
        R.stopAll()
        for _,item in ipairs(checked)do local success,err=R.set(item[1],item[2]);if not success then fail(err)end end
        return 'Preferences loaded'
    end
    local function vectorText(value,max)
        local x,y,z=tostring(value):match('^%s*([%+%-%.%d]+)%s*,%s*([%+%-%.%d]+)%s*,%s*([%+%-%.%d]+)%s*$')
        x,y,z=tonumber(x),tonumber(y),tonumber(z)
        if not x or not y or not z or x~=x or y~=y or z~=z then fail('Use x,y,z numeric format')end
        if math.abs(x)>(max or 10000) or math.abs(y)>(max or 10000) or math.abs(z)>(max or 10000)then fail('Vector is out of range')end
        return Vector3.new(x,y,z)
    end
