        if type(data)~='table' or type(data.data)~='table'then fail('Invalid public server list')end
        for _,server in ipairs(data.data)do
            if type(server.id)=='string' and server.id~=game.JobId and tonumber(server.playing) and tonumber(server.maxPlayers) and server.playing<server.maxPlayers then
                game:GetService('TeleportService'):TeleportToPlaceInstance(game.PlaceId,server.id,me);return
