    function R.set(id,value)
        local d=defs[id];if not d then return false,'Unknown feature' end
        local healthBefore=ctx.health.records[id]
        local ok,result=pcall(function()
            if d.kind=='number'then
                value=tonumber(value);if not value or value~=value or value<d.min or value>d.max then fail('Value must be between '..d.min..' and '..d.max)end
            elseif d.kind=='toggle'then if type(value)~='boolean'then fail('Expected true or false')end
            elseif d.kind=='choice'then local found=false;for _,v in ipairs(d.choices)do if value==v then found=true end end;if not found then fail('Unknown choice')end end
            serial=serial+1;order[id]=serial
            if d.system then if not ctx.systemCommand then fail('System interface is not ready')end;return ctx.systemCommand(d.id)end
            if d.equipment then
                if not ctx.equipmentCommand then fail('Equipment interface is not ready')end
                local result=ctx.equipmentCommand(d.field,value,d);if d.kind~='action'and d.kind~='report'then active[id]=true end
                if d.kind=='report'then ctx.report(d,result)end;return result
            end
            if d.ultra then local result=ultra.set(d,value);if d.kind~='action'and d.kind~='report'then active[id]=true end;return result end
            if d.plus then local result=plus.set(d,value);if d.kind=='toggle'or d.kind=='number'or d.kind=='choice'or d.kind=='text'then active[id]=true end;return result end
            if d.kind=='action' or d.kind=='text'then
                if not actions[id]then fail('Missing action: '..id)end
                local answer=actions[id](value)
                if d.kind=='text' then O[id]=value end
                return answer
            elseif d.kind=='report'then
                if not reports[id]then fail('Missing report: '..id)end
                local report=reports[id]();ctx.report(d,report);return report
            end
            if value==true and (id=='spectate' or id=='camera_orbit' or id=='follow_target' or id=='orbit_target' or id=='keep_distance' or id=='face_target') and not selected then fail('Select a player first')end
            if id=='zoom_min' and value>(O.zoom_max or 128)then fail('Minimum zoom exceeds maximum zoom')end
            if id=='zoom_max' and value<(O.zoom_min or .5)then fail('Maximum zoom is below minimum zoom')end
            O[id]=value;active[id]=true
            if d.kind=='toggle' and not value then release(id)end
            if id=='infinite_jump' or id=='noclip'then core.set(id=='infinite_jump' and 'infiniteJump' or 'noclip',value)end
            if id=='auto_coins'then core.set('autoCoins',value);farmTarget=nil;farm.reset(value and'searching'or'stopped',value)end
            -- ESP role polling is synchronized below for every ESP display mode.
            if id=='spectate'then if value then O.super_lock=false;superLock.stop();if not core.spectate(selected.Name)then fail('Selected player is not ready')end else core.unspectate()end end
            if id=='freecam' or id=='camera_orbit' or id=='aimlock'or id=='super_lock'then
                if value then for _,mode in ipairs({'freecam','camera_orbit','aimlock','super_lock','spectate'})do if mode~=id then O[mode]=false;release(mode);if mode=='super_lock'then superLock.stop()end end end;core.unspectate()
                else core.unspectate()end
            end
            if id=='super_lock'then
                if value then O.face_target=false;O.spin_character=false;release('face_target');release('spin_character')end
                superLock.setEnabled(value)
            elseif value and (id=='face_target'or id=='spin_character')then O.super_lock=false;superLock.stop()end
            if id=='freecam' and value and workspace.CurrentCamera then
                local pitch,yaw=workspace.CurrentCamera.CFrame:ToOrientation();freeYaw=yaw;freePitch=pitch
            end
            if id=='favorites'then ctx.favoritesOnly(value)end
            if value==true then
                if id=='auto_equip_gun'then O.auto_equip_knife=false elseif id=='auto_equip_knife'then O.auto_equip_gun=false end
                if id=='face_target'then O.spin_character=false elseif id=='spin_character'then O.face_target=false end
                if id=='fly'then O.freeze=false;release('freeze')end
            end
            if (d.page=='appearance' or d.page=='world')then applyVisuals()end
            if id=='fly' and not value then release('fly')end
            if id=='air_walk' and not value then destroy(airPlatform);airPlatform=nil end
            tickESP(0);ctx.renderESP()
            return value
        end)
        if not ok then
            if d.kind=='toggle'then O[id]=false;release(id)end
            errors[#errors+1]=id..': '..tostring(result);if #errors>80 then table.remove(errors,1)end
            ctx.health.record(id,'error',result)
            say(tostring(result));return false,tostring(result)
        end
        if ctx.health.records[id]==healthBefore then ctx.health.record(id,'done')end
        if ctx.changed then ctx.changed()end
        return true,result
    end
    ctx.connect(U.InputChanged,function(input,processed)
        if not O.freecam or processed then return end
        if input.UserInputType==Enum.UserInputType.Touch or (input.UserInputType==Enum.UserInputType.MouseMovement and U:IsMouseButtonPressed(Enum.UserInputType.MouseButton2))then
            local delta=input.Delta or Vector3.new()
            freeYaw=freeYaw-delta.X*(O.plus_look_sensitivity or .004);freePitch=math.max(-1.5,math.min(1.5,freePitch-delta.Y*(O.plus_look_sensitivity or .004)*(O.plus_invert_look and -1 or 1)))
        end
    end)
    local function tickMovement(dt)
        local ch,h,r=char();if not ch or not h or not r or h.Health<=0 then return end
        for id,spec in pairs({walk_speed={h,'WalkSpeed'},jump_power={h,'JumpPower'},jump_height={h,'JumpHeight'},gravity={workspace,'Gravity'},hip_height={h,'HipHeight'},auto_rotate={h,'AutoRotate'}})do
            if active[id]then mutate(id,spec[1],spec[2],O[id])end
        end
        if active.jump_power then mutate('jump_power',h,'UseJumpPower',true)end
        if active.jump_height then mutate('jump_height',h,'UseJumpPower',false)end
        if O.sprint then mutate('sprint',h,'WalkSpeed',O.sprint_speed)end
        if O.crouch then mutate('crouch',h,'HipHeight',math.max(-2,O.hip_height-1.5))end
        if O.freeze then mutate('freeze',r,'Anchored',true)end
        if O.platform_stand then mutate('platform_stand',h,'PlatformStand',true)end
        if O.local_invisible then for _,obj in ipairs(list(ch))do if obj:IsA('BasePart')then mutate('local_invisible',obj,'LocalTransparencyModifier',1)end end end
        if cameraOffset and active.camera_offset then mutate('camera_offset',h,'CameraOffset',cameraOffset)end
        if O.auto_jump and clock-lastJump>(O.plus_jump_interval or 1) then h.Jump=true;lastJump=clock end
        if O.bunny_hop and h.MoveDirection.Magnitude>.1 and h.FloorMaterial~=Enum.Material.Air then h.Jump=true end
        if O.fly then
            local y=vertical
            if not U:GetFocusedTextBox()then if U:IsKeyDown(Enum.KeyCode.Space)then y=1 elseif U:IsKeyDown(Enum.KeyCode.LeftControl)then y=-1 end end
            mutate('fly',h,'PlatformStand',true)
            mutate('fly',r,'AssemblyLinearVelocity',h.MoveDirection*O.fly_speed+Vector3.new(0,y*(y>=0 and(O.plus_ascend_speed or O.fly_speed)or(O.plus_descend_speed or O.fly_speed)),0))
        end
        if O.air_walk then
            if not airPlatform then airPlatform=make('Part',{Name='SALAPAO_LocalAirPlatform',Anchored=true,CanCollide=true,CanTouch=false,CanQuery=false,Transparency=.65,
                Color=Color3.fromRGB(220,35,60),Size=Vector3.new(7,.3,7)},workspace)end
            airPlatform.Size=Vector3.new(O.plus_platform_width or 7,.3,O.plus_platform_width or 7);airPlatform.Transparency=O.plus_platform_alpha or .65
            airPlatform.CFrame=CFrame.new(r.Position-Vector3.new(0,3.3,0))
        end
        if O.fall_rescue and savedGround and r.Position.Y<O.rescue_height then core.teleport(savedGround)end
        local _,_,targetRoot=char(selected)
        if selected and targetRoot then
            if O.face_target then local p=targetRoot.Position;local goal=Vector3.new(p.X,r.Position.Y,p.Z);if (goal-r.Position).Magnitude>.1 then r.CFrame=CFrame.lookAt(r.Position,goal)end end
            local delta=r.Position-targetRoot.Position
            if O.follow_target and delta.Magnitude>O.follow_distance then h:MoveTo(targetRoot.Position+delta.Unit*O.follow_distance)end
            if O.keep_distance and delta.Magnitude<O.follow_distance and delta.Magnitude>.1 then h:MoveTo(targetRoot.Position+delta.Unit*O.follow_distance)end
            if O.orbit_target then orbitAngle=orbitAngle+dt;h:MoveTo(targetRoot.Position+Vector3.new(math.cos(orbitAngle)*O.orbit_radius,0,math.sin(orbitAngle)*O.orbit_radius))end
        end
        if O.spin_character then r.CFrame=r.CFrame*CFrame.Angles(0,math.rad(O.spin_speed)*dt,0)end
        if O.auto_gun then
            local gun=nearest(core.inspect().guns)
            if gun then local danger,d=threat();if not O.avoid_murderer or not danger or d>O.avoid_radius then moveToward(gun.Position,dt,O.farm_speed,O.farm_mode)end end
        end
    end
    local function tickCamera(dt)
        local c=workspace.CurrentCamera;if not c then return end
        if active.fov then mutate('fov',c,'FieldOfView',O.fov)end
        if active.zoom_min then mutate('zoom_min',me,'CameraMinZoomDistance',O.zoom_min)end
        if active.zoom_max then mutate('zoom_max',me,'CameraMaxZoomDistance',O.zoom_max)end
        if O.first_person then mutate('first_person',me,'CameraMode',Enum.CameraMode.LockFirstPerson)end
        local _,h,r=char();local _,_,targetRoot=char(selected)
        if O.freecam then
            mutate('freecam',c,'CameraType',Enum.CameraType.Scriptable)
            if r then mutate('freecam',r,'Anchored',true)end
            local move=h and h.MoveDirection or Vector3.new()
            local cf=CFrame.new(c.CFrame.Position+(move+Vector3.new(0,vertical,0))*O.freecam_speed*dt)*CFrame.Angles(0,freeYaw,0)*CFrame.Angles(freePitch,0,0)
            mutate('freecam',c,'CFrame',cf)
        elseif O.camera_orbit and selected and targetRoot then
            cameraAngle=cameraAngle+math.rad(O.camera_orbit_speed)*dt
            mutate('camera_orbit',c,'CameraType',Enum.CameraType.Scriptable)
            local position=targetRoot.Position+Vector3.new(math.cos(cameraAngle)*O.orbit_radius,O.plus_orbit_height or 5,math.sin(cameraAngle)*O.orbit_radius)
            mutate('camera_orbit',c,'CFrame',c.CFrame:Lerp(CFrame.lookAt(position,targetRoot.Position),1-math.exp(-(O.plus_orbit_smoothing or 8)*dt)))
        elseif O.aimlock then
            local p=threat();local _,h2,r2=char(p)
            if p and h2 and h2.Health>0 and r2 then
                local screen,onScreen=c:WorldToViewportPoint(r2.Position);local center=c.ViewportSize/2
                local distance=(Vector2.new(screen.X,screen.Y)-center).Magnitude
                if onScreen and distance<=O.aim_radius and (not O.aim_require_los or visibleTarget(r2))then
                    local goal=CFrame.lookAt(c.CFrame.Position,r2.Position+Vector3.new(0,1.2,0))
                    c.CFrame=c.CFrame:Lerp(goal,1-math.exp(-O.aim_smoothing*dt))
                end
            end
        end
        if active.plus_camera_roll or O.plus_camera_level then
            local pitch,yaw=c.CFrame:ToOrientation();c.CFrame=CFrame.new(c.CFrame.Position)*CFrame.Angles(pitch,yaw,O.plus_camera_level and 0 or math.rad(O.plus_camera_roll or 0))
        end
        cross.Position=UDim2.new(.5,O.plus_cross_x or 0,.5,O.plus_cross_y or 0)
        for _,arm in ipairs(arms)do
            local color=O.plus_cross_color or '255,60,85';local r,g,b=color:match('(%d+)%s*,%s*(%d+)%s*,%s*(%d+)');arm.BackgroundColor3=Color3.fromRGB(tonumber(r)or 255,tonumber(g)or 60,tonumber(b)or 85);arm.BackgroundTransparency=O.plus_cross_alpha or 0
        end
        local stroke=circle:FindFirstChildOfClass('UIStroke');if stroke then
            local r,g,b=(O.plus_circle_color or '235,60,90'):match('(%d+)%s*,%s*(%d+)%s*,%s*(%d+)');stroke.Color=Color3.fromRGB(tonumber(r)or 235,tonumber(g)or 60,tonumber(b)or 90);stroke.Thickness=O.plus_circle_width or 1;stroke.Transparency=O.plus_circle_alpha or .2
        end
        cross.Visible=O.crosshair==true;circle.Visible=O.fov_circle==true
        local s,g=O.crosshair_size,O.crosshair_gap
        arms[1].Size=UDim2.fromOffset(s,O.plus_cross_width or 2);arms[1].Position=UDim2.fromOffset(g,-1)
        arms[2].Size=UDim2.fromOffset(s,O.plus_cross_width or 2);arms[2].Position=UDim2.fromOffset(-g-s,-1)
        arms[3].Size=UDim2.fromOffset(O.plus_cross_width or 2,s);arms[3].Position=UDim2.fromOffset(-1,g)
        arms[4].Size=UDim2.fromOffset(O.plus_cross_width or 2,s);arms[4].Position=UDim2.fromOffset(-1,-g-s)
        circle.Size=UDim2.fromOffset(O.fov_circle_radius*2,O.fov_circle_radius*2)
    end
    local function tickWorld()
        local snap=core.inspect();local _,h,r=char()
        if snap.map~=lastMap then
            if lastMap and not O.resume_next_round then O.auto_coins=false;core.set('autoCoins',false);if ctx.changed then ctx.changed()end end
            if O.round_notifications then say('Map: '..(snap.map and snap.map.Name or '--'))end
            lastMap=snap.map;farmTarget=nil;roundStart=nil;visited=setmetatable({},{__mode='k'})
        end
        if O.auto_spawn_save and not roundStart and r and snap.map then
            local spawn,distance=nearest(spawns())
            if spawn and distance<80 then roundStart=spawn.CFrame+Vector3.new(0,4,0)end
        end
        if r and h and h.FloorMaterial~=Enum.Material.Air and r.Position.Y>O.rescue_height then savedGround=r.CFrame end
        for _,p in ipairs(P:GetPlayers())do
            local role=core.role(p)
            if O.role_notifications and role and knownRoles[p]~=role then say(p.Name..': '..role)end
            knownRoles[p]=role
        end
        for _,gun in ipairs(snap.guns)do if O.gun_notifications and not knownGuns[gun]then say('Gun: '..gun:GetFullName())end;knownGuns[gun]=true end
        local danger,d=threat()
        if O.threat_alert and danger and d<O.avoid_radius and clock-lastThreat>5 then lastThreat=clock;say('Knife threat: '..danger.Name..' · '..math.floor(d)..' studs')end
        if h then
            local backpack=me:FindFirstChild('Backpack')
            local name=O.auto_equip_gun and 'Gun' or O.auto_equip_knife and 'Knife' or nil
            local tool=name and backpack and backpack:FindFirstChild(name)
            if tool and tool:IsA('Tool')then h:EquipTool(tool)end
        end
        if O.auto_activate_tool and me.Character and clock-lastTool>=.5 then
            local tool=me.Character:FindFirstChildOfClass('Tool')
            if tool then lastTool=clock;tool:Activate()end
        end
    end
    ctx.connect(P.PlayerAdded,function(p)if O.join_notifications then say('+ '..p.Name)end end)
    ctx.connect(P.PlayerRemoving,function(p)
        if O.join_notifications then say('- '..p.Name)end
        knownRoles[p]=nil;if selected==p then selected=nil;O.target_player='';O.spectate=false;core.unspectate();if ctx.changed then ctx.changed()end end
        if screenMarkers[p]then for _,obj in pairs(screenMarkers[p])do destroy(obj)end;screenMarkers[p]=nil end
    end)
    ctx.connect(workspace.DescendantAdded,visualObject)
    ctx.connect(L.DescendantAdded,visualObject)
    ctx.connect(game:GetService('SoundService').DescendantAdded,visualObject)
    local sampleTime,sampleFrames,lastError=0,0,0
    ctx.connect(ctx.RunService.Heartbeat,function(dt)
        if not alive then return end
        clock=clock+dt;slow=slow+dt;sampleTime=sampleTime+dt;sampleFrames=sampleFrames+1
        if sampleTime>=1 then fps=sampleFrames/sampleTime;sampleTime=0;sampleFrames=0 end
        local ok,err=pcall(function()
            plus.tick(dt);ultra.tick(dt);tickESP(dt);tickMovement(math.min(dt,.2));tickCamera(math.min(dt,.2))
            if slow>=1 then slow=slow%1;tickWorld()end
            flyControls.Visible=O.fly==true or O.freecam==true
            hud.Visible=O.performance_hud==true
            if hud.Visible then local _,_,r=char();hud.Text=string.format('ซาลาเปา · %.0f FPS\n%s\nRole: %s',fps,r and tostring(r.Position)or '--',core.role(me)or ctx.unknownRole())end
        end)
        if not ok and clock-lastError>5 then
            lastError=clock;errors[#errors+1]='update: '..tostring(err);if #errors>80 then table.remove(errors,1)end;ctx.health.record('system:update','error',err);say(tostring(err))
        end
    end)
    function R.definition(id)return defs[id]end
    function R.handlerExists(id)
        local d=defs[id];if not d then return false end
        if d.system or d.equipment then return true end
        if d.ultra then return ultra.handlerExists(id)end
        if d.plus then return plus.handlerExists(id)end
        return d.kind=='toggle' or d.kind=='number' or d.kind=='choice' or actions[id]~=nil or reports[id]~=nil
    end
    function R.destroy()
        if not alive then return end
        R.stopAll();farm.destroy();alive=false;ctx.renderESP=nil;ctx.farmController=nil;destroy(overlay);destroy(flyControls)
    end
    return R
end

