    local box=make('Frame',{Name='LoadingCard',AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
        Size=UDim2.fromOffset(580,340),BackgroundColor3=C.card,BorderSizePixel=0,ZIndex=101},overlay);corner(box,20)
    local scale=make('UIScale',{Name='LoadingScale',Scale=1},box)
    local function fit()
        local size=overlay.AbsoluteSize
        if not size or size.X<=0 or size.Y<=0 then local camera=workspace.CurrentCamera;size=camera and camera.ViewportSize or Vector2.new(800,450)end
        scale.Scale=math.max(.1,math.min((size.X-28)/580,(size.Y-28)/340,1))
    end
    track(overlay:GetPropertyChangedSignal('AbsoluteSize'),fit);fit()
    local diamond=make('Frame',{Name='LoadingRuby',AnchorPoint=Vector2.new(.5,.5),Position=UDim2.new(.5,0,0,62),
        Size=UDim2.fromOffset(44,44),Rotation=45,BackgroundColor3=C.red,BorderSizePixel=0,ZIndex=102},box);corner(diamond,8)
    make('UIGradient',{Color=ColorSequence.new(C.red,C.darkRed),Rotation=35},diamond)
    local heading=text(box,'LoadingBrand',100,40,27);heading.Text='ซาลาเปา v1';heading.TextXAlignment=Enum.TextXAlignment.Center;heading.ZIndex=102
    local caption=text(box,'LoadingTitle',143,34,17);caption.Text=tr('loadingTitle');caption.TextXAlignment=Enum.TextXAlignment.Center;caption.ZIndex=102
    local stage=text(box,'LoadingStage',184,40,14);stage.Text=tr('loadStart');stage.TextColor3=C.muted;stage.TextXAlignment=Enum.TextXAlignment.Center;stage.ZIndex=102
    local rail=make('Frame',{Name='LoadingRail',Position=UDim2.new(.08,0,0,240),Size=UDim2.new(.84,0,0,8),
        BackgroundColor3=C.bg,BorderSizePixel=0,ZIndex=102},box);corner(rail,4)
    local fill=make('Frame',{Name='LoadingProgress',Size=UDim2.fromScale(0,1),BackgroundColor3=C.red,
        BorderSizePixel=0,ZIndex=103},rail);corner(fill,4)
    local percent=text(box,'LoadingPercent',258,26,14);percent.Text='0%';percent.TextXAlignment=Enum.TextXAlignment.Center;percent.ZIndex=102
    local branding=text(box,'LoadingCloud',294,24,11);branding.Text='NEBULA CLOUD';branding.TextColor3=C.muted;branding.TextXAlignment=Enum.TextXAlignment.Center;branding.ZIndex=102
    local exit=make('TextButton',{Name='CloseLoading',Position=UDim2.new(1,-46,0,8),Size=UDim2.fromOffset(38,38),
        BackgroundTransparency=1,BorderSizePixel=0,Text='×',TextSize=26,TextColor3=C.muted,ZIndex=104},box)
    track(exit.Activated,function()gui:Destroy()end)
    local stageKey='loadStart'
    rubyBoot={screen=overlay,stage=stage,preview=false}
    function rubyBoot.update(key,value,yieldFrame)
        if not alive then return false end
        stageKey=key;stage.Text=tr(key);caption.Text=tr('loadingTitle')
        local n=math.clamp(value,0,1);fill.Size=UDim2.fromScale(n,1);percent.Text=tostring(math.floor(n*100+.5))..'%'
        gui:SetAttribute('LoadingStage',key);gui:SetAttribute('LoadingProgress',n)
        if yieldFrame then task.wait(.03)end
        return alive
    end
    function rubyBoot.finish()
        if not alive then return end
        local failure=gui:GetAttribute('ExpansionError')or gui:GetAttribute('FocusError')or gui:GetAttribute('ReferenceError')or gui:GetAttribute('WidgetsError')or gui:GetAttribute('PlusUIError')or gui:GetAttribute('MotionError')or gui:GetAttribute('LanguagesError')or gui:GetAttribute('ChatError')or gui:GetAttribute('GlassError')or gui:GetAttribute('ExtraUIError')or gui:GetAttribute('WorldUIError')or gui:GetAttribute('SystemUIError')
        if failure then
            rubyBoot.update('loadFailed',1,false);stage.Text=tr('loadFailed')..'\n'..tostring(failure):sub(1,140)
            gui:SetAttribute('LoadingComplete',false);return
        end
        rubyBoot.update('loadReady',1,false);gui:SetAttribute('LoadingComplete',true)
        -- A short final frame leaves a readable completion state, with no fake network progress.
        task.delay(.25,function()if alive and not rubyBoot.preview then overlay.Visible=false end end)
    end
    track(gui:GetAttributeChangedSignal('Language'),function()
        if alive then caption.Text=tr('loadingTitle');stage.Text=tr(rubyBoot.preview and'loadingPreview'or stageKey)end
    end)
    if not rubyBoot.update('loadAssets',.08,true)then return end
end

-- Embed the PNG once when a permitted client supports local custom images.
-- Studio and clients without custom-image support use a transparent 3D ruby below.
local function decode64(data)
    local chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local values={};for i=1,#chars do values[chars:sub(i,i)]=i-1 end
    local result,acc,bits={},0,0
    for i=1,#data do
        local value=values[data:sub(i,i)]
        if value then
            acc=acc*64+value;bits=bits+6
            if bits>=8 then
                bits=bits-8;result[#result+1]=string.char(math.floor(acc/2^bits)%256)
                acc=acc%2^bits
            end
        end
    end
    return table.concat(result)
end
local logoAsset
local customAsset=getcustomasset or getsynasset
if type(customAsset)=='function' and type(writefile)=='function' then
    local ok,result=pcall(function()
        local filename='SALAPAO_atlas_1_0_2.png'
        writefile(filename,decode64(LOGO_ATLAS_BASE64))
        return customAsset(filename)
    end)
    if ok and type(result)=='string' then logoAsset=result end
end
local function triangle(model,a,b,c,color)
    local ab,ac,bc=b-a,c-a,c-b
    if ab:Dot(ab)>ac:Dot(ac) and ab:Dot(ab)>bc:Dot(bc) then
        c,a=a,c
    elseif ac:Dot(ac)>bc:Dot(bc) then a,b=b,a end
    ab,ac,bc=b-a,c-a,c-b
    local right=ac:Cross(ab).Unit
    local back=bc.Unit
    local up=bc:Cross(right).Unit
    local h=math.abs(ab:Dot(up))
    local function wedge(mid,x,y,z,length)
        if length<0.001 or h<0.001 then return end
        make('WedgePart',{Name='RubyFacet',Anchored=true,CanCollide=false,CanTouch=false,
            CanQuery=false,Material=Enum.Material.SmoothPlastic,Color=color,
            Size=Vector3.new(0.005,h,length),CFrame=CFrame.fromMatrix(mid,x,y,z)},model)
    end
    wedge((a+b)/2,right,up,back,math.abs(ab:Dot(back)))
    wedge((a+c)/2,-right,up,-back,math.abs(ac:Dot(back)))
end
local function gemLogo(host,name,size,position)
    local view=make('ViewportFrame',{Name=name,Size=UDim2.fromOffset(size,size),Position=position,
        BackgroundTransparency=1,BorderSizePixel=0,Ambient=Color3.fromRGB(230,220,207),
        LightColor=Color3.fromRGB(255,248,238),LightDirection=Vector3.new(-1,-2,-3),Active=false},host)
    local world=make('WorldModel',{},view)
    local model=make('Model',{Name='SalapaoBun'},world)
    local function ball(name,size,position,color)
        return make('Part',{Name=name,Shape=Enum.PartType.Ball,Size=size,Position=position,
            Anchored=true,CanCollide=false,CanTouch=false,CanQuery=false,Material=Enum.Material.SmoothPlastic,Color=color},model)
    end
    ball('Bun',Vector3.new(2,1.6,1.8),Vector3.new(),Color3.fromRGB(255,239,216))
    for i=1,8 do local a=i*math.pi/4;ball('Pleat',Vector3.new(.34,.7,.34),Vector3.new(math.cos(a)*.3,.65,math.sin(a)*.3),Color3.fromRGB(247,223,192))end
    model.WorldPivot=CFrame.new()
    local camera=make('Camera',{FieldOfView=35,CFrame=CFrame.lookAt(Vector3.new(0,.6,5.2),Vector3.new(0,.15,0))},view)
    view.CurrentCamera=camera
    local image,wrap
    if logoAsset then
        wrap=make('Frame',{Name=name..'ImageHost',Size=UDim2.fromOffset(size,size),Position=position,
            BackgroundTransparency=1,BorderSizePixel=0,Active=false},host)
        image=make('ImageLabel',{Name=name..'TextureA',Size=UDim2.fromScale(1,1),BackgroundTransparency=1,
            BorderSizePixel=0,Image=logoAsset,ScaleType=Enum.ScaleType.Fit,
            ImageRectSize=Vector2.new(128,128),ImageRectOffset=Vector2.new()},wrap)
        track(image:GetPropertyChangedSignal('IsLoaded'),function()view.Visible=not image.IsLoaded end)
    end
    logoRenderers[#logoRenderers+1]=function(frame)
        if image and image.IsLoaded then
            view.Visible=false;local current=math.floor(frame)%40
            image.ImageRectOffset=Vector2.new((current%8)*128,math.floor(current/8)*128)
        else view.Visible=true;model:PivotTo(CFrame.Angles(0,-frame*math.pi*2/40,0))end
    end
    return view
end


