local HttpService=game:GetService('HttpService')
local httpRequest=(syn and syn.request) or request or http_request
local CLOUD='https://nebula-cloud-bm.sahachat222333.chatgpt.site'
local born=os.clock()
local aiToken,aiSession,device,aiBusy=nil,nil,nil,false
local pairRevision=0
local aiState,aiErrorText='disconnected',''
local history,messages={},{}
local function api(method,path,payload,token)
    if type(httpRequest)~='function' then return nil,0,tr('unsupportedHTTP') end
    local headers={['Content-Type']='application/json'}
    if token then headers.Authorization='Bearer '..token end
    local opts={Url=CLOUD..path,Method=method,Headers=headers}
    if payload then opts.Body=HttpService:JSONEncode(payload) end
    local ok,res=pcall(httpRequest,opts)
    if not ok or type(res)~='table' then return nil,0,'Network request failed' end
    local parsed,data=pcall(function() return HttpService:JSONDecode(res.Body or '') end)
    local code=tonumber(res.StatusCode or res.Status or 0)
    if not parsed or type(data)~='table' then return nil,code,'Invalid server response' end
    if code<200 or code>=300 then return nil,code,data.error or ('HTTP '..code) end
    return data,code,nil
end

