local function renderAIState()
    aiStatus.Text=tr(aiState)..(aiErrorText~='' and ('\n'..aiErrorText) or '')
    aiInput.PlaceholderText=tr('aiPlaceholder')
    sendAIButton.Text=tr(aiBusy and 'sending' or 'send')
    connectAIButton.Text=tr(aiToken and 'retryAI' or 'connectAI')
    if device then pairLabel.Text=tr('pairCode')..': '..tostring(device.userCode)..'\n'..tr('pendingAI') end
    if aiSession then
        quota.Text=tr('quota')..' · '..tostring(aiSession.dailyLimit or 100)..'\n'..
            tr('used')..': '..tostring(aiSession.used or 0)..' · '..tr('remaining')..': '..tostring(aiSession.remaining or 0)
    else quota.Text=tr('quota')..' · '..tr('unknown') end
    for _,message in ipairs(messages) do message.obj.Text=tr(message.role)..'\n'..message.value end
end
local rubyPlusPlayerList
local function refresh()
    if not alive then return end
    local ch=player.Character
    local root=ch and ch:FindFirstChild('HumanoidRootPart')
    local hum=ch and ch:FindFirstChildOfClass('Humanoid')
    local position=root and string.format('%.1f, %.1f, %.1f',root.Position.X,root.Position.Y,root.Position.Z) or tr('unavailable')
    local display=player.DisplayName==player.Name and player.Name or player.DisplayName..' (@'..player.Name..')'
    local people=Players:GetPlayers()
    status.Text=tr(scanning and 'live' or 'paused')
    details.Text=string.format('%s: %s\n%s: %d\n%s: %s\n%s: %s\n%s: %s',
        tr('player'),display,tr('players'),#people,tr('character'),tr(ch and 'ready' or 'waiting'),
        tr('position'),position,tr('place'),tostring(game.PlaceId))
    profile.Text=tr('profile')..'\n'..display..'\nID: '..tostring(player.UserId)
    homeStats.Text=tr('players')..': '..#people..'\n'..tr('character')..': '..tr(ch and 'ready' or 'waiting')..'\nNEP · '..tr(scanning and 'on' or 'off')
    local names={}
    for _,p in ipairs(people) do names[#names+1]=p.DisplayName..'  (@'..p.Name..')' end
    playerList.Text=tr('players')..': '..#people..'\n\n'..table.concat(names,'\n')
    local bridge=gui:GetAttribute('PlusReady')and rubyPlusPlayerList
    if bridge then local list,count=bridge();playerList.Text=tr('players')..': '..count..'\n\n'..list end
    local listHeight=math.max(120,70+#people*24)
    playerListCard.Size=UDim2.new(1,0,0,listHeight);playerList.Size=UDim2.new(1,-32,0,listHeight-24)
    characterDetails.Text=tr('character')..': '..tr(ch and 'ready' or 'waiting')..'\n'..
        tr('position')..': '..position..'\n'..tr('health')..': '..(hum and string.format('%.0f / %.0f',hum.Health,hum.MaxHealth) or tr('unavailable'))..'\n'..
        tr('speed')..': '..tostring(hum and hum.WalkSpeed or tr('unavailable'))..'\n'..tr('jump')..': '..tostring(hum and hum.JumpPower or tr('unavailable'))
    sessionDetails.Text=tr('place')..': '..tostring(game.PlaceId)..'\n'..tr('job')..': '..tostring(game.JobId or '')..'\n'..
        tr('uptime')..': '..math.floor(os.clock()-born)..' '..tr('seconds')
    autoButton.Text=tr('auto')..'  ·  '..tr(scanning and 'on' or 'off')
    languageButton.Text=tr('language')..'  ·  '..LANG_NAMES[LANGS[langIndex]]
    fontButton.Text=tr('font')..'  ·  '..fonts[fontIndex]
    spinButton.Text=tr('spin')..'  ·  '..tr(spinning and 'on' or 'off')
    waveButton.Text=tr('waves')..'  ·  '..tr(waves and 'on' or 'off')
    hide:SetAttribute('AccessibleLabel',tr('hide'));close:SetAttribute('AccessibleLabel',tr('close'))
    bubble:SetAttribute('AccessibleLabel',tr('open'));renderAIState()
end
