-- NEBULA CLOUD / RUBY conversation controller. Tokens stay in this script's memory only.
local rubyAI={options={},queued=nil,lastFailed=nil,lastUser=nil,guide=false,revision=0}
do
local function chatOption(key,default)local value=rubyAI.options['ultra_ai_'..key];if value==nil then return default end;return value end
local function aiChanged()
    gui:SetAttribute('AIRequestState',aiBusy and'Waiting'or'Idle')
    gui:SetAttribute('AIConnectionState',aiState)
    gui:SetAttribute('AIQueuedMessage',rubyAI.queued~=nil)
    renderAIState();if rubyAI.render then rubyAI.render()end;if rubyAI.memoryDirty then rubyAI.memoryDirty()end
end
local function addMessage(role,value)
    chatEmpty.Visible=false
    local row=make('Frame',{Name='ChatRow',Size=UDim2.new(1,-4,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,BorderSizePixel=0,LayoutOrder=#messages+1},chat)
    row:SetAttribute('MessageRole',role)
    local l=make('TextLabel',{Name='ChatMessage',Size=UDim2.new(.9,-8,0,0),
        AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=role=='you'and C.darkRed or C.bg,BackgroundTransparency=.15,BorderSizePixel=0,
        TextColor3=role=='you'and C.muted or C.text,Font=Enum.Font[fonts[fontIndex]],TextSize=21,
        TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
        Text=tr(role)..'\n'..value,LayoutOrder=#messages+1},row)
    corner(l,12);make('UIPadding',{PaddingTop=UDim.new(0,12),PaddingBottom=UDim.new(0,12),PaddingLeft=UDim.new(0,14),PaddingRight=UDim.new(0,14)},l)
    l:SetAttribute('MessageRole',role)
    messages[#messages+1]={obj=l,row=row,role=role,value=value,time=os.date('%H:%M:%S')}
    if rubyAI.messageDecorator then rubyAI.messageDecorator(messages[#messages])end
    if #messages>40 then local first=table.remove(messages,1);(first.row or first.obj):Destroy()end
    for i,m in ipairs(messages)do (m.row or m.obj).LayoutOrder=i end
    task.defer(function()if alive and chatOption('auto_scroll',true)then chat.CanvasPosition=Vector2.new(0,math.max(0,chatLayout.AbsoluteContentSize.Y-chat.AbsoluteSize.Y))end end)
    if rubyAI.render then rubyAI.render()end
end
local function validateSession(revision)
    local session,code,err=api('GET','/api/v1/session',nil,aiToken)
    if not alive or revision~=pairRevision then return false end
    if not session then
        if code==401 then aiToken=nil;aiSession=nil end
        aiState='connectionFailed';aiErrorText=tostring(err);aiChanged();return false
    end
    if tostring(session.robloxId)~=tostring(player.UserId)then
        aiToken=nil;aiSession=nil;aiState='wrongAccount';aiErrorText='';aiChanged();return false
    end
    aiSession=session;aiState=session.configured and'connected'or'serverUnconfigured';aiErrorText='';aiChanged()
    return session.configured==true
end
local function cancelChat()
    rubyAI.revision=rubyAI.revision+1;aiBusy=false;rubyAI.lastFailed=rubyAI.lastUser;if aiInput.Text==''and rubyAI.lastUser then aiInput.Text=rubyAI.lastUser end;aiState=aiToken and'connected'or'disconnected';aiErrorText=tr('chat9Stopped');aiChanged()
end
local function disconnectAI()
    pairRevision=pairRevision+1;rubyAI.revision=rubyAI.revision+1;aiToken=nil;aiSession=nil;device=nil;aiBusy=false
    aiState='disconnected';aiErrorText='';gui:SetAttribute('AIConnectionGuideReady',false);rubyAI.guide=false;rubyAI.queued=nil
    pairCard.Visible=false;pairURL.Visible=false;copyPairButton.Visible=false;aiChanged()
end
local sendMessage,beginPair
local function safeDevice(data)
    if type(data)~='table'or type(data.deviceId)~='string'or #data.deviceId~=48 or not data.deviceId:match('^%x+$')then return false end
    if type(data.deviceSecret)~='string'or #data.deviceSecret~=64 or not data.deviceSecret:match('^%x+$')then return false end
    return data.verificationUrl==CLOUD..'/connect/device/'..data.deviceId
end
beginPair=function()
    rubyAI.guide=true;gui:SetAttribute('AIConnectionGuideReady',false)
    if device or aiState=='connecting'then aiChanged();return end
    if type(httpRequest)~='function'then aiState='unsupportedHTTP';aiErrorText=tr('chat9Unsupported');aiChanged();return end
    pairRevision=pairRevision+1;local revision=pairRevision
    aiToken=nil;aiSession=nil;aiState='connecting';aiErrorText='';aiChanged()
    task.spawn(function()
        local data,_,err=api('POST','/api/v1/device/start',{robloxId=tostring(player.UserId)})
        if not alive or revision~=pairRevision then return end
        if not data or not safeDevice(data)then
            aiState='connectionFailed';aiErrorText=data and tr('chat9InvalidLink')or tostring(err);aiChanged();return
        end
        device=data;pairURL.Text=data.verificationUrl;pairCard.Visible=true;pairURL.Visible=true;copyPairButton.Visible=true
        aiState='pendingAI';aiErrorText='';gui:SetAttribute('AIConnectionGuideReady',true);aiChanged()
        local interval=math.max(4,math.min(10,tonumber(data.interval)or 4))
        local attempts=math.floor(math.min(600,tonumber(data.expiresIn)or 600)/interval)
        for _=1,attempts do
            task.wait(interval);if not alive or revision~=pairRevision then return end
            local approved,code,pollError=api('POST','/api/v1/device/poll',{deviceId=data.deviceId,deviceSecret=data.deviceSecret})
            if not alive or revision~=pairRevision then return end
            if approved and code==200 and approved.status=='approved'and type(approved.token)=='string'and approved.token:match('^neb_%x+$')and #approved.token==68 then
                aiToken=approved.token;device=nil;pairCard.Visible=false;pairURL.Visible=false;copyPairButton.Visible=false
                if validateSession(revision)then
                    rubyAI.guide=false;local queued,shown=rubyAI.queued,rubyAI.queuedShown;rubyAI.queued=nil;rubyAI.queuedShown=nil;aiChanged()
                    if queued then sendMessage(queued,shown)end
                end
                return
            elseif code~=202 then
                device=nil;aiState='connectionFailed';aiErrorText=code==410 and tr('chat9Expired')or tostring(pollError or('HTTP '..code));aiChanged();return
            end
        end
        if alive and revision==pairRevision then device=nil;aiState='connectionFailed';aiErrorText=tr('chat9Expired');aiChanged()end
    end)
end
rubyAI.payload=function(message)
    local context={};local pairsLimit=math.max(0,math.min(6,math.floor(chatOption('context_limit',6))))
    for i=math.max(1,#history-pairsLimit*2+1),#history do context[#context+1]={role=history[i].role,text=history[i].text}end
    local language=chatOption('language','Interface')
    local codes={Thai='TH',English='EN',Chinese='ZH',Japanese='JA',Korean='KO',Spanish='ES',French='FR',German='DE',Portuguese='PT',Russian='RU',Indonesian='ID'}
    local preferences={style=chatOption('response_style','Concise'),maxTokens=math.floor(chatOption('response_limit',2048)),language=codes[language]or LANGS[langIndex]}
    local payload={message=message,history=context,preferences=preferences}
    if rubyAI.memoryPayload then payload.memory=rubyAI.memoryPayload()end
    return payload
end
sendMessage=function(raw,alreadyShown)
    if aiBusy then return false end
    local message=tostring(raw or aiInput.Text):match('^%s*(.-)%s*$')
    if message==''then aiState='emptyMessage';aiErrorText='';aiChanged();return false end
    if #message>4000 then aiState='tooLong';aiErrorText='';aiChanged();return false end
    if not aiToken then rubyAI.queued=message;rubyAI.queuedShown=alreadyShown;beginPair();return false end
    if aiSession and not aiSession.configured then aiState='serverUnconfigured';aiChanged();return false end
    aiBusy=true;rubyAI.lastUser=message;rubyAI.lastFailed=nil;rubyAI.revision=rubyAI.revision+1
    local revision,pair=rubyAI.revision,pairRevision
    if aiInput.Text:match('^%s*(.-)%s*$')==message then aiInput.Text=''end
    if not alreadyShown then addMessage('you',message)end
    aiErrorText='';aiState='sending';aiChanged()
    local payload=rubyAI.payload(message)
    task.spawn(function()
        local data,code,err=api('POST','/api/v1/chat',payload,aiToken)
        if not alive or revision~=rubyAI.revision or pair~=pairRevision then return end
        aiBusy=false
        if not data or type(data.reply)~='string'or data.reply==''then
            rubyAI.lastFailed=message;aiState='aiError';aiErrorText=tr('chat9Error')..'\n'..tostring(err or('HTTP '..code))
            if aiInput.Text==''then aiInput.Text=message end
            if code==401 then aiToken=nil;aiSession=nil end
            aiChanged();return
        end
        addMessage('assistant',data.reply);history[#history+1]={role='user',text=message};history[#history+1]={role='model',text=(function()local reply=data.reply;if #reply>8000 then local cut=8000;while cut>0 and reply:byte(cut+1)>=128 and reply:byte(cut+1)<192 do cut=cut-1 end;reply=reply:sub(1,cut)end;return reply end)()}
        local function total()local n=0;for _,turn in ipairs(history)do n=n+#turn.text end;return n end
        while #history>12 or total()>20000 do table.remove(history,1);table.remove(history,1)end
        aiState='connected';aiErrorText='';aiChanged();validateSession(pair)
    end)
    return true
end
local function clearConversation()
    if aiBusy then cancelChat()end
    for _,message in ipairs(messages)do (message.row or message.obj):Destroy()end
    messages={};history={};rubyAI.queued=nil;rubyAI.lastFailed=nil;rubyAI.lastUser=nil;chatEmpty.Visible=true;aiChanged()
end
rubyAI.send=sendMessage;rubyAI.start=beginPair;rubyAI.disconnect=disconnectAI;rubyAI.cancel=cancelChat
rubyAI.add=addMessage;rubyAI.changed=aiChanged;rubyAI.clear=clearConversation
track(disconnectAIButton.Activated,disconnectAI)
track(connectAIButton.Activated,function()if aiToken then disconnectAI()end;beginPair()end)
track(sendAIButton.Activated,function()sendMessage()end)
track(clearChatButton.Activated,clearConversation)
track(aiInput.FocusLost,function(enter)if enter and chatOption('send_enter',false)then sendMessage()end end)
local cleanupAI=onCleanup
onCleanup=function()
    pairRevision=pairRevision+1;rubyAI.revision=rubyAI.revision+1;aiToken=nil;device=nil;history={};rubyAI.queued=nil
    if cleanupAI then cleanupAI()end
end

rubyAI.option=chatOption
end


local open,openTween,openConnection=true,nil,nil
local targetPosition=Vector2.new(12,24)
local width,height=730,540
local function clamp(value,low,high) return math.max(low,math.min(high,value)) end
local function surfaceSize()
    local size=surface.AbsoluteSize
    if size.X<1 or size.Y<1 then
        local cam=workspace.CurrentCamera;return cam and cam.ViewportSize or Vector2.new(390,844)
    end
    return size
end
local function clampPosition(pos,w,h)
    local size=surfaceSize()
    return Vector2.new(clamp(pos.X,6,math.max(6,size.X-w-6)),clamp(pos.Y,6,math.max(6,size.Y-h-6)))
end
local function cancelOpenTween()
    if openConnection then openConnection:Disconnect();openConnection=nil end
    if openTween then openTween:Cancel();openTween=nil end
end
local function resize(reset)
    cancelOpenTween()
    local size=surfaceSize()
    width=math.max(260,math.min(1040,size.X-32));height=math.max(230,math.min(700,size.Y-32))
    panel.Size=UDim2.fromOffset(width,height)
    local wide=width>=600
    nav.Position=UDim2.fromOffset(12,wide and 96 or 88)
    nav.Size=wide and UDim2.new(0,150,1,-138) or UDim2.new(1,-24,0,46)
    navLayout.FillDirection=wide and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
    nav.AutomaticCanvasSize=wide and Enum.AutomaticSize.Y or Enum.AutomaticSize.X
    nav.ScrollingDirection=wide and Enum.ScrollingDirection.Y or Enum.ScrollingDirection.X
    for _,b in pairs(tabs) do b.Size=wide and UDim2.new(1,-5,0,44) or UDim2.fromOffset(135,44) end
    content.Position=UDim2.fromOffset(wide and 178 or 12,wide and 96 or 146)
    content.Size=wide and UDim2.new(1,-192,1,-138) or UDim2.new(1,-24,1,-184)
    gui:SetAttribute('NavigationLayout',wide and 'sidebar' or 'horizontal')
    if reset then targetPosition=Vector2.new((size.X-width)/2,(size.Y-height)/2) end
    targetPosition=clampPosition(targetPosition,width,height)
    panel.Position=UDim2.fromOffset(targetPosition.X,targetPosition.Y);panel.Visible=open
    local bp=clampPosition(Vector2.new(bubble.Position.X.Offset,bubble.Position.Y.Offset),64,64)
    bubble.Position=UDim2.fromOffset(bp.X,bp.Y)
end
local function setOpen(value)
    cancelOpenTween();open=value
    if open then
        panel.Visible=true;panel.Position=UDim2.fromOffset(targetPosition.X,surfaceSize().Y+20)
        openTween=TweenService:Create(panel,TweenInfo.new(gui:GetAttribute('ReduceMotion')and 0 or 0.32,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),
            {Position=UDim2.fromOffset(targetPosition.X,targetPosition.Y)})
    else
        openTween=TweenService:Create(panel,TweenInfo.new(gui:GetAttribute('ReduceMotion')and 0 or 0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.In),
            {Position=UDim2.fromOffset(targetPosition.X,surfaceSize().Y+20)})
        openConnection=track(openTween.Completed,function(state)
            if alive and not open and state==Enum.PlaybackState.Completed then panel.Visible=false end
        end)
    end
    openTween:Play()
end
track(hide.Activated,function() setOpen(false) end)
track(close.Activated,function() gui:Destroy() end)
track(resetButton.Activated,function() resize(true) end)
track(resetAllButton.Activated,function()
    langIndex=1;fontIndex=1;spinning=true;waves=true;scanning=true;wave.Visible=true
    applyLanguage();applyFont();resize(true);switchPage('home')
end)
local drag,draggedBubble
local function draggable(handle,obj,isBubble)
    track(handle.InputBegan,function(input)
        if input.UserInputType~=Enum.UserInputType.Touch and input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
        if not isBubble then cancelOpenTween() end
        drag={input=input,start=input.Position,origin=Vector2.new(obj.Position.X.Offset,obj.Position.Y.Offset),
            obj=obj,bubble=isBubble,moved=false}
        if isBubble then draggedBubble=false end
    end)
end
draggable(header,panel,false);draggable(bubble,bubble,true)
track(UIS.InputChanged,function(input)
    if not drag then return end
    local touch=drag.input.UserInputType==Enum.UserInputType.Touch
    if (touch and input~=drag.input) or (not touch and input.UserInputType~=Enum.UserInputType.MouseMovement) then return end
    local delta=input.Position-drag.start
    if delta.Magnitude>6 then drag.moved=true end
    if not drag.moved then return end
    local pos=clampPosition(drag.origin+Vector2.new(delta.X,delta.Y),drag.bubble and 64 or width,drag.bubble and 64 or height)
    drag.obj.Position=UDim2.fromOffset(pos.X,pos.Y)
    if drag.bubble then draggedBubble=true else targetPosition=pos end
end)
track(UIS.InputEnded,function(input)
    if drag and (input==drag.input or (drag.input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then drag=nil end
end)
track(bubble.Activated,function() if not draggedBubble then setOpen(not open) end;draggedBubble=false end)
track(UIS.InputBegan,function(input,processed)
    if not processed and input.KeyCode==menuHotkey then setOpen(not open) end
end)
track(surface:GetPropertyChangedSignal('AbsoluteSize'),function() resize(false) end)

local scanElapsed,logoElapsed,phase,logoFrame=0,0,0,0
track(RunService.Heartbeat,function(dt)
    if not alive then return end
    scanElapsed=scanElapsed+dt
    if scanning and scanElapsed>=3 then scanElapsed=scanElapsed%3;refresh() end
    if spinning then
        logoElapsed=logoElapsed+dt
        local steps=math.floor((logoElapsed+0.000000001)*LOGO_FPS)
        if steps>0 then
            logoElapsed=logoElapsed-steps/LOGO_FPS;logoFrame=(logoFrame+steps)%LOGO_FRAMES
            for _,render in ipairs(logoRenderers) do render(logoFrame) end
            gui:SetAttribute('LogoFrame',logoFrame);gui:SetAttribute('SpriteFrame',math.floor(logoFrame/4))
        end
    end
    if open and waves then
        phase=(phase+dt)%1000
        wave.Position=UDim2.new((math.sin(phase*1.2)+1)*0.3,0,1,-2)
        wave.BackgroundTransparency=0.15+0.35*(math.sin(phase*2)+1)/2
        headerGradient.Rotation=15+math.sin(phase*0.5)*12
    end
end)
track(Players.PlayerAdded,function() if scanning then refresh() end end)
track(Players.PlayerRemoving,function() task.defer(function() if alive and scanning then refresh() end end) end)
track(player.CharacterAdded,function() task.defer(function() if alive then refresh() end end) end)
switchPage('home');applyLanguage();resize(true);setOpen(true)
for _,render in ipairs(logoRenderers) do render(0) end
gui:SetAttribute('LogoFrame',0);gui:SetAttribute('SpriteFrame',0)

