t"]=0,["min"]=-100,["max"]=100,["step"]=1,["widget"]="range-slider"},{["id"]="salapao_workspace_1_yOffset",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="yOffset",["kind"]="number",["page"]="studioPage",["th"]="เลื่อนทุกเลเยอร์แนวตั้ง · 1",["en"]="Canvas vertical offset · 1",["default"]=0,["min"]=-100,["max"]=100,["step"]=1,["widget"]="range-slider"},{["id"]="salapao_workspace_1_export",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="export",["kind"]="report",["page"]="studioPage",["th"]="ส่งออกเลเยอร์เป็น JSON · 1",["en"]="Export canvas layers · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_import",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="import",["kind"]="text",["page"]="studioPage",["th"]="นำเข้าเลเยอร์จาก JSON · 1",["en"]="Import canvas layers · 1",["default"]="",["widget"]="text-input"},{["id"]="salapao_workspace_1_copy",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="copy",["kind"]="action",["page"]="studioPage",["th"]="คัดลอก JSON ของเลเยอร์ · 1",["en"]="Copy canvas JSON · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_save",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="save",["kind"]="action",["page"]="studioPage",["th"]="บันทึกเลเยอร์ลงเครื่อง · 1",["en"]="Save canvas locally · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_load",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="load",["kind"]="action",["page"]="studioPage",["th"]="เปิดเลเยอร์จากเครื่อง · 1",["en"]="Load local canvas · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_hideAll",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="hideAll",["kind"]="action",["page"]="studioPage",["th"]="ซ่อนเลเยอร์ทั้งหมด · 1",["en"]="Hide all layers · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_showAll",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="showAll",["kind"]="action",["page"]="studioPage",["th"]="แสดงเลเยอร์ทั้งหมด · 1",["en"]="Show all layers · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_resetAll",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="resetAll",["kind"]="action",["page"]="studioPage",["th"]="คืนค่าเลเยอร์ทั้งหมด · 1",["en"]="Reset all layers · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_centerAll",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="centerAll",["kind"]="action",["page"]="studioPage",["th"]="จัดทุกเลเยอร์ไว้กลางจอ · 1",["en"]="Center all layers · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_summary",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="summary",["kind"]="report",["page"]="studioPage",["th"]="สรุปเลเยอร์ที่เปิดอยู่ · 1",["en"]="Active layer summary · 1",["widget"]="command-button"},{["id"]="salapao_workspace_1_selected",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="selected",["kind"]="number",["page"]="studioPage",["th"]="หมายเลขเลเยอร์ที่เลือก · 1",["en"]="Selected layer number · 1",["default"]=1,["min"]=1,["max"]=24,["step"]=1,["widget"]="range-slider"},{["id"]="salapao_workspace_1_centerSelected",["salapao"]=true,["group"]="workspace",["slot"]=1,["field"]="centerSelected",["kind"]="action",["page"]="studioPage",["th"]="จัดเลเยอร์ที่เลือกไว้กลางจอ · 1",["en"]="Center selected layer · 1",["widget"]="command-button"}}
for _,d in ipairs(SALAPAO_ADDITIONS)do RUBY_CONTROLS[#RUBY_CONTROLS+1]=d end
RUBY_CONTROLS[#RUBY_CONTROLS+1]={id='shot_through_walls',page='extraPage',kind='toggle',
    th='โหมดยิงเป้าหลังกำแพง',en='Target behind walls',zh='瞄准墙后目标',
    default=true,widget='switch'}
for _,d in ipairs(RUBY_CONTROLS)do
    if d.id=='farm_mode'then d.choices={'Walk','Tween','Teleport'}end
end


if not rubyBoot.update('loadTools',0.5,true)then return end
local rubyControlUI
-- Install the expansion after the base GUI is visible, so setup errors are reportable.
local function installRubyExpansion()
    local favorites,rows,featureOptions,cleanups={},{},{},{}
    local favoritesOnly=false
    local language=function()return LANGS[langIndex]end
    local function label(d)return d[language()]or d[language():lower()]or d.en end
    local words={
        TH={search='ค้นหาฟีเจอร์…',apply='ใช้ค่า',copy='คัดลอกรายงาน',report='รายงาน',done='ดำเนินการแล้ว',unknown='ไม่ทราบบทบาท',error='ฟีเจอร์มีข้อผิดพลาด'},
        EN={search='Search features…',apply='Apply',copy='Copy report',report='Report',done='Action completed',unknown='Unknown role',error='Feature error'},
        ZH={search='搜索功能…',apply='应用',copy='复制报告',report='报告',done='已执行',unknown='未知角色',error='功能错误'},
    }
    for _,code in ipairs(LANGS)do if not words[code]then
        words[code]=RUBY_LOCALES[code]
    end end
    local function word(key)local code=language();if code=='TH'or code=='EN'or code=='ZH'then return words[code][key]end;return tr(({copy='copyReport',unknown='unknownRole'})[key]or key)end
    local search=make('TextBox',{Name='FeatureSearch',Size=UDim2.fromOffset(145,44),LayoutOrder=-10,
        BackgroundColor3=C.card,BorderSizePixel=0,Text='',PlaceholderText=word('search'),
        ClearTextOnFocus=false,TextColor3=C.text,TextSize=12,Font=Enum.Font.Gotham},nav);corner(search,10)
    fontTargets[#fontTargets+1]=search
    local reportCard=card(pages.nep,'FeatureReportCard',280);reportCard.LayoutOrder=-10;reportCard.Visible=false
    local reportBox=make('TextBox',{Name='FeatureReport',Size=UDim2.new(1,-24,1,-66),Position=UDim2.fromOffset(12,10),
        BackgroundTransparency=1,BorderSizePixel=0,Text='',TextEditable=false,MultiLine=true,ClearTextOnFocus=false,
        TextColor3=C.text,TextSize=12,Font=Enum.Font.Code,TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,
        TextYAlignment=Enum.TextYAlignment.Top},reportCard)
    local reportCopy=make('TextButton',{Name='CopyFeatureReport',Size=UDim2.new(1,-24,0,40),Position=UDim2.new(0,12,1,-48),
        BackgroundColor3=C.darkRed,BorderSizePixel=0,Text=word('copy'),TextColor3=C.text,TextSize=13,Font=Enum.Font.Gotham},reportCard);corner(reportCopy,9)
    track(reportCopy.Activated,function()copy(reportBox.Text,reportBox)end)
    local function notify(message)
        if alive then footer.Text='RUBY · '..tostring(message):sub(1,170)end
    end
    local function filterRows()
        local query=search.Text:lower()
        for _,row in pairs(rows)do
            local hay='';if query~=''then local translated={row.d.id};for _,code in ipairs(LANGS)do translated[#translated+1]=row.d[code]or row.d[code:lower()]or''end;hay=table.concat(translated,' '):lower()end
            row.frame.Visible=(query=='' or hay:find(query,1,true)~=nil) and (not favoritesOnly or favorites[row.d.id]==true)
            row.star.Text=favorites[row.d.id] and '★' or '☆'
        end
    end
    local refreshRows
    local context={Players=Players,RS=game:GetService('ReplicatedStorage'),RunService=RunService,UIS=UIS,
        Lighting=game:GetService('Lighting'),HttpService=HttpService,me=player,gui=gui,options=featureOptions,
        connect=track,cloud=CLOUD,httpRequest=httpRequest,notify=notify,translate=tr,
        onCleanup=function(fn)cleanups[#cleanups+1]=fn end,
        connections=connections,
        refreshPlayerList=function()refresh()end,
        favoriteIDs=function()local list={};for id,on in pairs(favorites)do if on then list[#list+1]=id end end;table.sort(list);return list end,
        setFavoriteIDs=function(ids)for k in pairs(favorites)do favorites[k]=nil end;for _,id in ipairs(ids)do favorites[id]=true end;filterRows()end,
        clearFavorites=function()for k in pairs(favorites)do favorites[k]=nil end;filterRows()end,
        unknownRole=function()return word('unknown')end,
        focusSearch=function()search:CaptureFocus()end,
        favoritesOnly=function(value)favoritesOnly=value;filterRows()end,
        changed=function()if alive and refreshRows then refreshRows()end end,
        report=function(d,value)
            if not alive then return end
            reportCard.Visible=true;reportBox.Text=label(d)..'\n\n'..tostring(value)
            switchPage('nep');pages.nep.CanvasPosition=Vector2.new(0,0)
        end,
    }
    local oldCleanup=onCleanup
    onCleanup=function()
        for i=#cleanups,1,-1 do pcall(cleanups[i])end
        if oldCleanup then oldCleanup()end
    end
    local engine=createEngine(context)
    local inherited={};for _,d in ipairs(RUBY_CONTROLS)do if not d.salapao then inherited[#inherited+1]=d end end
    local tools=createRubyTools(context,engine,inherited)
    local overlay=make('ScreenGui',{Name='SALAPAO_CANVAS',ResetOnSpawn=false,DisplayOrder=85,IgnoreGuiInset=false},parent)
    local grid=make('Frame',{Name='CanvasGrid',Size=UDim2.fromScale(1,1),BackgroundTransparency=1,Visible=false},overlay)
    local gridSize
    local function drawGrid(enabled,spacing)
        grid.Visible=enabled==true;if not enabled or gridSize==spacing then return end;gridSize=spacing
        for _,o in ipairs(grid:GetChildren())do o:Destroy()end
        for i=1,math.ceil(4000/spacing)do
            make('Frame',{Size=UDim2.new(0,1,1,0),Position=UDim2.fromOffset(i*spacing,0),BackgroundColor3=C.muted,BackgroundTransparency=.7,BorderSizePixel=0},grid)
            make('Frame',{Size=UDim2.new(1,0,0,1),Position=UDim2.fromOffset(0,i*spacing),BackgroundColor3=C.muted,BackgroundTransparency=.7,BorderSizePixel=0},grid)
        end
    end
    local function paintLayer(obj,s)
        local function col(raw)local r,g,b=raw:match('^%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*$');return Color3.fromRGB(tonumber(r),tonumber(g),tonumber(b))end
        obj.Text=s.text;obj.AnchorPoint=Vector2.new(.5,.5);obj.Position=UDim2.fromScale(s.x/100,s.y/100)
        obj.Size=UDim2.fromOffset(s.width,s.height);obj.TextSize=s.fontSize;obj.Rotation=s.rotation
        obj.TextTransparency=1-s.opacity;obj.TextColor3=col(s.textColor);obj.BackgroundColor3=col(s.bgColor)
        obj.BackgroundTransparency=1-s.bgOpacity;obj.Font=Enum.Font[s.font];obj.TextXAlignment=Enum.TextXAlignment[s.alignment]
    end
    local extra=createSalapaoExtra({now=os.clock,rgb=Color3.fromRGB,paint=paintLayer,grid=drawGrid,
        label=function(i)local obj=make('TextLabel',{Name='Layer_'..i,TextWrapped=true,BorderSizePixel=0,Text=''},overlay);corner(obj,12);return obj end,
        length=function(s)local ok,n=pcall(utf8.len,s);return ok and n or #s end,
        copy=function(s)if type(setclipboard)=='function'then local ok,e=pcall(setclipboard,s);return ok,e end;context.report({th='ข้อความสำหรับคัดลอก',en='Copy text'},s);return true end,
        report=context.report,notify=notify,
        encode=function(d)return HttpService:JSONEncode(d)end,
        decode=function(raw)local ok,d=pcall(function()return HttpService:JSONDecode(raw)end);if ok then return d end;return nil,'JSON ไม่ถูกต้อง'end,
        saveWorkspace=function(doc)if type(writefile)~='function'then return false,'ตัวรันนี้บันทึกไฟล์ไม่ได้'end;return pcall(writefile,'SALAPAO_canvas.json',HttpService:JSONEncode(doc))end,
        loadWorkspace=function()if type(readfile)~='function'then return nil,'ตัวรันนี้อ่านไฟล์ไม่ได้'end;local ok,d=pcall(function()local raw=readfile('SALAPAO_canvas.json');assert(#raw<900000,'ไฟล์ใหญ่เกินไป');return HttpService:JSONDecode(raw)end);if ok then return d end;return nil,tostring(d)end,
        save=function(i,n)if type(writefile)~='function'then return false,'ตัวรันนี้บันทึกไฟล์ไม่ได้'end;return pcall(writefile,'SALAPAO_note_'..i..'.json',HttpService:JSONEncode({title=n.title,body=n.body}))end,
        load=function(i)if type(readfile)~='function'then return nil,'ตัวรันนี้อ่านไฟล์ไม่ได้'end;local ok,doc=pcall(function()local raw=readfile('SALAPAO_note_'..i..'.json');assert(#raw<150000,'ไฟล์ใหญ่เกินไป');return HttpService:JSONDecode(raw)end);if ok then return doc end;return nil,tostring(doc)end,
    },SALAPAO_ADDITIONS)
    local oldGet,oldSet,oldExists,oldDefinition,oldStop=tools.get,tools.set,tools.handlerExists,tools.definition,tools.stopAll
    tools.get=function(id)if extra.defs[id]then return extra.get(id)end;return oldGet(id)end
    tools.set=function(id,value)if extra.defs[id]then return extra.set(id,value)end;return oldSet(id,value)end
    tools.handlerExists=function(id)return extra.defs[id]~=nil or oldExists(id)end
    tools.definition=function(id)return extra.defs[id]or oldDefinition(id)end
    tools.stopAll=function()oldStop();for _,t in ipairs(extra.timers)do if t.running then t.remaining=math.max(0,t.deadline-os.clock());t.running=false end end;for _,d in ipairs(SALAPAO_ADDITIONS)do if d.group=='layer'and d.field=='enabled'then extra.set(d.id,false)end end;extra.set('salapao_workspace_1_grid',false)end
    local summary=info(pages.clockPage,'CountdownSummary',218);summary.Text=extra.summary()
    local elapsed=0
    track(RunService.Heartbeat,function(dt)elapsed=elapsed+dt;if elapsed>=.25 then elapsed=elapsed%.25;extra.tick(os.clock());if pages.clockPage.Visible then summary.Text=extra.summary()end end end)
    context.onCleanup(function()extra.destroy();overlay:Destroy()end)
    gui:SetAttribute('AddedControlCount',#SALAPAO_ADDITIONS)

    local function run(d,value)
        local ok,result=tools.set(d.id,value)
        if ok then
            if (d.kind=='action' or d.kind=='text')and d.id~='shoot_murderer'then notify(label(d)..' · '..word('done'))end
        else notify(word('error')..': '..tostring(result))end
        refreshRows()
        if rubyControlUI and rubyControlUI.afterRun then rubyControlUI.afterRun(d,ok,result)end
        return ok,result
    end
    for index,d in ipairs(RUBY_CONTROLS)do
        if index%24==0 then if not alive then return end;task.wait()end
        assert(tools.handlerExists(d.id),'Missing implementation: '..d.id)
        local frame=card(pages[d.page],'FeatureRow_'..d.id,(d.kind=='text') and 112 or 63)
        frame.LayoutOrder=d.id=='super_lock'and 1 or d.id=='shot_through_walls'and 2 or d.id=='shoot_murderer'and 3 or 1000+index
        local title=make('TextLabel',{Name='FeatureLabel_'..d.id,Size=UDim2.new(1,-143,0,47),Position=UDim2.fromOffset(12,8),
            BackgroundTransparency=1,BorderSizePixel=0,Text=label(d),TextColor3=C.text,Font=Enum.Font.Gotham,TextSize=12,
            TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left},frame)
        fontTargets[#fontTargets+1]=title
        local star=make('TextButton',{Name='Favorite_'..d.id,Size=UDim2.fromOffset(30,43),Position=UDim2.new(1,-36,0,10),
            BackgroundTransparency=1,BorderSizePixel=0,Text='☆',TextColor3=C.red,Font=Enum.Font.Gotham,TextSize=20},frame)
        local row={frame=frame,title=title,star=star,d=d};rows[d.id]=row
        track(star.Activated,function()favorites[d.id]=not favorites[d.id];filterRows()end)
        if d.kind=='number' or d.kind=='text'then
            local input=make('TextBox',{Name='Feature_'..d.id,Size=d.kind=='text' and UDim2.new(1,-103,0,42)or UDim2.fromOffset(90,42),
                Position=d.kind=='text' and UDim2.fromOffset(12,61)or UDim2.new(1,-132,0,10),
                BackgroundColor3=C.bg,BorderSizePixel=0,Text=tostring(d.default or ''),ClearTextOnFocus=false,
                TextColor3=C.text,Font=Enum.Font.Code,TextSize=12,TextWrapped=d.kind=='text'},frame);corner(input,8)
            input:SetAttribute('FeatureKind',d.kind);input:SetAttribute('FeatureId',d.id);row.control=input
            if d.kind=='number'then track(input.FocusLost,function()run(d,tonumber(input.Text))end)
            else
                title.Size=UDim2.new(1,-48,0,47)
                local apply=make('TextButton',{Name='Apply_'..d.id,Size=UDim2.fromOffset(76,42),Position=UDim2.new(1,-85,0,61),
                    BackgroundColor3=C.darkRed,BorderSizePixel=0,Text=word('apply'),TextColor3=C.text,TextSize=12,Font=Enum.Font.Gotham},frame)
                corner(apply,8);row.apply=apply;row.applyConnection=track(apply.Activated,function()run(d,input.Text)end)
                fontTargets[#fontTargets+1]=apply
            end
        else
            local control=make('TextButton',{Name='Feature_'..d.id,Size=UDim2.fromOffset(90,42),Position=UDim2.new(1,-132,0,10),
                BackgroundColor3=C.bg,BorderSizePixel=0,Text='',TextColor3=C.text,TextSize=11,TextWrapped=true,Font=Enum.Font.Gotham},frame);corner(control,8)
            fontTargets[#fontTargets+1]=control
            control:SetAttribute('FeatureKind',d.kind);control:SetAttribute('FeatureId',d.id);row.control=control
            row.activateConnection=track(control.Activated,function()
                if d.kind=='toggle'then run(d,not tools.get(d.id))
                elseif d.kind=='choice'then
                    local at=1;for i,v in ipairs(d.choices)do if tools.get(d.id)==v then at=i end end
                    run(d,d.choices[at%#d.choices+1])
                else run(d)end
            end)
        end
    end
    refreshRows=function()
        search.PlaceholderText=word('search');reportCopy.Text=word('copy')
        for _,row in pairs(rows)do
            local d=row.d;row.title.Text=label(d)
            if d.kind=='toggle'then row.control.Text=tr(tools.get(d.id) and 'on' or 'off');row.control.BackgroundColor3=tools.get(d.id) and C.darkRed or C.bg
            elseif d.kind=='number'then row.control.Text=tostring(tools.get(d.id))
