            elseif d.kind=='action'then row.control.Text=word('apply')
            elseif d.kind=='report'then row.control.Text=word('report')
            elseif row.apply then row.apply.Text=word('apply')end
        end
        filterRows()
        if rubyControlUI and rubyControlUI.refreshWidgets then rubyControlUI.refreshWidgets()end
    end
    rubyControlUI={rows=rows,tools=tools,context=context,run=run,refresh=function()refreshRows()end}
    track(gui:GetAttributeChangedSignal('Language'),refreshRows)
    track(search:GetPropertyChangedSignal('Text'),filterRows)
    refreshRows()
