-- A proportional recreation of the approved C layout, built from native Roblox controls.
local function installRubyReference()
    local function find(parent,name)
        if parent.Name==name then return parent end
        for _,o in ipairs(parent:GetDescendants())do if o.Name==name then return o end end
    end
    local function edge(obj,color,alpha,w)
        local stroke=obj:FindFirstChildOfClass('UIStroke')or make('UIStroke',{},obj)
        stroke.Color=color or Color3.fromRGB(241,225,208);stroke.Transparency=alpha or 0
        stroke.Thickness=w or 1;stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        return stroke
    end
    local function rect(obj,x,y,w,h)
        obj.Position=UDim2.fromOffset(x,y);obj.Size=UDim2.fromOffset(w,h)
    end
    header.BackgroundTransparency=1
    local root=make('Frame',{Name='ReferenceLayout',Size=UDim2.fromOffset(1200,630),BackgroundTransparency=1,
        BorderSizePixel=0,ClipsDescendants=true},panel)
    local scale=make('UIScale',{Name='ReferenceScale',Scale=1},root)
    for _,o in ipairs({header,nav,content,footer,wave})do o.Parent=root end
    local divider=make('Frame',{Name='SidebarDivider',BackgroundColor3=Color3.fromRGB(241,225,208),
        BorderSizePixel=0},root)
    local home=pages.home
    for _,o in ipairs(home:GetChildren())do if o:IsA('UIListLayout')or o:IsA('UIPadding')then o:Destroy()end end
    home.AutomaticCanvasSize=Enum.AutomaticSize.None;home.CanvasSize=UDim2.new();home.ScrollBarThickness=0
    local search=find(gui,'FeatureSearch')
    local section=find(gui,'SectionTitle');section.Parent=root
    local gear=find(gui,'SettingsButton');gear.Text='';gear.BackgroundTransparency=1
    local brandHome=find(gui,'BrandHome');brandHome.BackgroundTransparency=1
    hide.Text='';close.Text=''

    -- Small vector icons remain crisp at every scale and need no external font or image.
    local iconHosts={}
    local function icon(parent,name,kind,color,size)
        local host=make('Frame',{Name=name,Size=UDim2.fromOffset(size or 28,size or 28),BackgroundTransparency=1,
            BorderSizePixel=0,Active=false},parent)
        local g=make('Frame',{Name='Vector',Size=UDim2.fromOffset(24,24),BackgroundTransparency=1,BorderSizePixel=0},host)
        make('UIScale',{Scale=(size or 28)/24},g)
        color=color or C.muted
        local function line(x1,y1,x2,y2,w)
            local dx,dy=x2-x1,y2-y1
            local f=make('Frame',{Name='IconLine',Position=UDim2.fromOffset((x1+x2)/2,(y1+y2)/2),
                Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),w or 1.7),AnchorPoint=Vector2.new(.5,.5),
                Rotation=math.deg(math.atan2(dy,dx)),BorderSizePixel=0,BackgroundColor3=color},g);corner(f,2)
        end
        local function box(x,y,w,h,r,fill)
            local f=make('Frame',{Name='IconShape',Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(w,h),
                BackgroundColor3=color,BackgroundTransparency=fill and 0 or 1,BorderSizePixel=0},g)
            corner(f,r or 2);if not fill then edge(f,color,0,1.6)end
        end
