        ZH={run='执行',sit='坐下',stand='站起',searchAction='搜索',choose='选择',apply='应用',cancel='取消',done='已完成',reset='恢复默认',searchPlayer='搜索玩家…',players='选择玩家',none='未找到玩家',color='场景色调',useColor='应用颜色',invalidColor='请输入六位 HEX 颜色或调整 RGB',invalidNumber='请输入指定范围内的数字',copy='复制',save='保存',load='加载',clear='清空',restore='恢复',go='前往',stop='停止',scan='扫描',rejoin='重新加入',hop='切换服务器',view='查看报告',edit='展开编辑器',json='编辑 JSON',import='导入',typePlayer='输入用户名或选择玩家',release='松开后应用',range='范围',filter='搜索选项…'},
    }
    for _,code in ipairs(LANGS)do if not words[code]then
        words[code]=RUBY_LOCALES[code]
