    local function word(k)local code=LANGS[langIndex];if code=='TH'or code=='EN'or code=='ZH'then return words[code][k]or k end;return tr(({players='selectPlayer',reset='resetDefault'})[k]or k)end
    local function label(d)return d[LANGS[langIndex]]or d[LANGS[langIndex]:lower()]or d.en end
    local function rect(o,x,y,w,h)o.Position=UDim2.fromOffset(x,y);o.Size=UDim2.fromOffset(w,h)end
