    end
    local function finite(n)return type(n)=='number'and n==n and math.abs(n)<math.huge end
    local function fmt(n)return string.format('%.4f',n):gsub('0+$',''):gsub('%.$','')end
    local toast=make('Frame',{Name='ControlToast',AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-20,1,-20),
        Size=UDim2.fromOffset(530,84),BackgroundColor3=C.card,BorderSizePixel=0,Visible=false,ZIndex=45},root);round(toast,12);edge(toast,C.red)
    local toastText=text(toast,'ControlToastText',10,64,20);toastText.Size=UDim2.new(1,-30,0,64)
    local toastVersion=0
    local openReport
    local function notify(message,ok)
        toastVersion=toastVersion+1;local v=toastVersion
        toastText.Text=tostring(message);toastText.TextColor3=ok and Color3.fromRGB(103,229,161)or C.text;toast.Visible=true
        task.delay(3.5,function()if alive and toastVersion==v then toast.Visible=false end end)
    end
    bridge.afterRun=function(d,ok,result)
        if ok and d.kind=='report'and openReport then openReport(rows[d.id],tostring(result))
        elseif not ok then notify(label(d)..' · '..tostring(result),false)
