    -- One pointer controller serves sliders in rows and the RGB editor.
    local dragging
    local function quantize(v,lo,hi,step)
        local n=lo+math.floor((math.max(lo,math.min(hi,v))-lo)/step+.5)*step
        return tonumber(string.format('%.4f',math.max(lo,math.min(hi,n))))
    end
    local function slider(parent,name,lo,hi,step,value,commit,existing,bind)
        bind=bind or track
        local host=make('Frame',{Name='SliderGroup_'..name,BackgroundTransparency=1,BorderSizePixel=0},parent)
        local hit=make('TextButton',{Name='Slider_'..name,Position=UDim2.fromOffset(0,0),Size=UDim2.new(1,-224,0,48),
            BackgroundTransparency=1,BorderSizePixel=0,Text='',Active=true,AutoButtonColor=false},host)
        local trackBar=make('Frame',{Name='SliderTrack_'..name,Position=UDim2.new(0,10,.5,-4),Size=UDim2.new(1,-20,0,8),
            BackgroundColor3=Color3.fromRGB(241,225,208),BorderSizePixel=0},hit);round(trackBar,4)
        hit:SetAttribute('Minimum',lo);hit:SetAttribute('Maximum',hi);hit:SetAttribute('Step',step)
        local fill=make('Frame',{Name='SliderFill_'..name,Size=UDim2.fromScale(0,1),BackgroundColor3=C.red,BorderSizePixel=0},trackBar);round(fill,4)
        local thumb=make('Frame',{Name='SliderThumb_'..name,AnchorPoint=Vector2.new(.5,.5),Size=UDim2.fromOffset(23,23),
            Position=UDim2.fromScale(0,.5),BackgroundColor3=C.text,BorderSizePixel=0},trackBar);round(thumb,12)
        local minus=btn(host,'Decrease_'..name,'−');minus.Position=UDim2.new(1,-214,0,2);minus.Size=UDim2.fromOffset(42,44)
        local field=existing or input(host,'SliderInput_'..name,value);field.Parent=host;field.Position=UDim2.new(1,-164,0,2);field.Size=UDim2.fromOffset(104,44);field.TextSize=21;field.TextWrapped=false
        local plus=btn(host,'Increase_'..name,'+');plus.Position=UDim2.new(1,-52,0,2);plus.Size=UDim2.fromOffset(42,44)
        local control={host=host,bar=trackBar,thumb=thumb,field=field,lo=lo,hi=hi,step=step,value=value,commit=commit}
        function control.draw(v)
            if not finite(v)then v=lo end
            control.value=v;local t=(v-lo)/(hi-lo)
            fill.Size=UDim2.fromScale(math.max(0,math.min(1,t)),1);thumb.Position=UDim2.fromScale(math.max(0,math.min(1,t)),.5)
            field.Text=fmt(v);hit:SetAttribute('Value',v)
        end
        local function apply(v)control.draw(quantize(v,lo,hi,step));commit(control.value)end
        bind(minus.Activated,function()apply(control.value-step)end);bind(plus.Activated,function()apply(control.value+step)end)
        if not existing then bind(field.FocusLost,function()
            local n=tonumber(field.Text)
            if finite(n)and n>=lo and n<=hi then apply(n)else notify(word('invalidNumber'),false);control.draw(control.value)end
        end)end
        function control.pointer(x)
            local size=trackBar.AbsoluteSize.X;if size<=0 then return end
            local t=(x-trackBar.AbsolutePosition.X)/size
            control.draw(quantize(lo+math.max(0,math.min(1,t))*(hi-lo),lo,hi,step))
            if rubyAI.sliderFeedback then rubyAI.sliderFeedback(control)end
        end
        local function beginPointer(i)
            if dragging then return end
            if i.UserInputType~=Enum.UserInputType.Touch and i.UserInputType~=Enum.UserInputType.MouseButton1 then return end
            local page=pages[activePage];local was=page and page.ScrollingEnabled~=false
            if page then page.ScrollingEnabled=false end
            dragging={control=control,input=i,original=control.value,page=page,scrolling=was};control.pointer(i.Position.X)
        end
        bind(hit.InputBegan,beginPointer);bind(trackBar.InputBegan,beginPointer);bind(fill.InputBegan,beginPointer);bind(thumb.InputBegan,beginPointer)
        control.draw(value);return control
    end
    local function cancelDrag()
        if rubyAI.sliderFeedback then rubyAI.sliderFeedback(nil)end
        if dragging then local d=dragging;dragging=nil;if d.page then d.page.ScrollingEnabled=d.scrolling end;d.control.draw(d.original)end
    end
    track(UIS.InputChanged,function(i)
        if not dragging then return end
        local touch=dragging.input.UserInputType==Enum.UserInputType.Touch
        if (touch and i~=dragging.input)or(not touch and i.UserInputType~=Enum.UserInputType.MouseMovement)then return end
        dragging.control.pointer(i.Position.X)
    end)
    track(UIS.InputEnded,function(i)
        if not dragging then return end
        if i==dragging.input or(dragging.input.UserInputType==Enum.UserInputType.MouseButton1 and i.UserInputType==Enum.UserInputType.MouseButton1)then
            local d=dragging;dragging=nil;if rubyAI.sliderFeedback then rubyAI.sliderFeedback(nil)end;if d.page then d.page.ScrollingEnabled=d.scrolling end;d.control.commit(d.control.value)
        end
    end)

    -- Shared modal: real selectable options, searchable players, color and text editors.
    local modal=make('Frame',{Name='ControlModal',Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,ZIndex=40,Visible=false},root)
    local dismiss=make('TextButton',{Name='DismissControlModal',Size=UDim2.fromScale(1,1),Text='',BackgroundColor3=Color3.new(0,0,0),
        BackgroundTransparency=.35,BorderSizePixel=0,AutoButtonColor=false},modal)
    local dialog=make('Frame',{Name='ControlDialog',AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
        Size=UDim2.fromOffset(620,540),BackgroundColor3=C.card,BorderSizePixel=0,Active=true},modal);round(dialog,14);edge(dialog)
    local heading=text(dialog,'ControlDialogTitle',12,46,24);heading.Size=UDim2.new(1,-95,0,46);heading.Font=Enum.Font.GothamBold
    local closeDialog=btn(dialog,'CloseControlModal','×');closeDialog.Position=UDim2.new(1,-54,0,12);closeDialog.Size=UDim2.fromOffset(40,40)
    local query=input(dialog,'ControlOptionSearch','');query.Position=UDim2.fromOffset(18,70);query.Size=UDim2.new(1,-36,0,48);query.Font=Enum.Font.Gotham
    local options=make('ScrollingFrame',{Name='ControlOptions',Position=UDim2.fromOffset(18,130),Size=UDim2.new(1,-36,1,-150),
        BackgroundTransparency=1,BorderSizePixel=0,AutomaticCanvasSize=Enum.AutomaticSize.Y,CanvasSize=UDim2.new(),ScrollBarThickness=3,ScrollBarImageColor3=C.red},dialog)
    make('UIListLayout',{Padding=UDim.new(0,8),SortOrder=Enum.SortOrder.LayoutOrder},options)
    local body=make('Frame',{Name='ControlEditorBody',Position=UDim2.fromOffset(18,70),Size=UDim2.new(1,-36,1,-150),BackgroundTransparency=1,BorderSizePixel=0},dialog)
    local applyDialog=btn(dialog,'ApplyControlEditor','');applyDialog.Position=UDim2.new(0,18,1,-65);applyDialog.Size=UDim2.new(1,-36,0,48);applyDialog.BackgroundColor3=C.darkRed
    local modalMode,modalRow,renderOptions,applyEditor,modalPage,oldScroll
    local temporary={}
    local function clearTemporary()
        for _,c in ipairs(temporary)do c:Disconnect()end;temporary={}
        local list=options:GetChildren();for i=#list,1,-1 do local o=list[i];if o:IsA('TextButton')or o:IsA('TextLabel')then o:Destroy()end end
        local list=body:GetChildren();for i=#list,1,-1 do list[i]:Destroy()end
    end
    local function ephemeral(signal,fn)local c=track(signal,fn);temporary[#temporary+1]=c;return c end
    local function closeModal()
        cancelDrag();modal.Visible=false;modalMode=nil;renderOptions=nil;applyEditor=nil;modalRow=nil
        if modalPage and modalPage.Parent then modalPage.ScrollingEnabled=oldScroll end
        modalPage=nil;clearTemporary()
    end
    local function fitModal()
        dialog.Size=UDim2.fromOffset(math.min(620,root.Size.X.Offset-40),math.min(540,root.Size.Y.Offset-40))
        toast.Size=UDim2.fromOffset(math.min(530,root.Size.X.Offset-40),84)
    end
    local function openModal(mode,row,title)
        closeModal();modalMode=mode;modalRow=row;heading.Text=title;modal.Visible=true;query.Text=''
        options.Visible=mode=='choice'or mode=='players';query.Visible=options.Visible;body.Visible=not options.Visible;applyDialog.Visible=not options.Visible
        query.PlaceholderText=word(mode=='players'and'searchPlayer'or'filter')
        modalPage=pages[activePage];if modalPage then oldScroll=modalPage.ScrollingEnabled~=false;modalPage.ScrollingEnabled=false end
        fitModal()
    end
    track(closeDialog.Activated,closeModal);track(dismiss.Activated,closeModal)
    track(query:GetPropertyChangedSignal('Text'),function()if renderOptions then renderOptions()end end)
    track(applyDialog.Activated,function()if applyEditor then applyEditor()end end)
    track(root:GetPropertyChangedSignal('Size'),fitModal)
    track(gui:GetAttributeChangedSignal('ActivePage'),closeModal)
    track(panel:GetPropertyChangedSignal('Visible'),function()if not panel.Visible then closeModal()end end)
    track(UIS.InputBegan,function(i)if modal.Visible and i.KeyCode==Enum.KeyCode.Escape then closeModal()end end)
    local translations={
        Walk={'เดิน','Walk','步行'},Tween={'เคลื่อนที่ลื่น','Tween','平滑移动'},Teleport={'วาร์ป','Teleport','传送'},All={'ทุกบทบาท','All roles','全部角色'},
        Murderer={'ฆาตกร','Murderer','凶手'},Sheriff={'นายอำเภอ','Sheriff','警长'},Innocent={'ผู้บริสุทธิ์','Innocent','平民'},
        AlwaysOnTop={'แสดงทะลุกำแพง','Through walls','穿墙显示'},Occluded={'บังตามกำแพง','Occluded','墙后遮挡'},
    }
    local function choiceLabel(v)local p=translations[v];return RUBY_LOCALES[LANGS[langIndex]][v]or(p and p[langIndex])or tostring(v)end
    local function optionButton(name,caption,selected,order)
        local b=btn(options,name,caption);b.Size=UDim2.new(1,-5,0,62);b.LayoutOrder=order;b.TextXAlignment=Enum.TextXAlignment.Left
        make('UIPadding',{PaddingLeft=UDim.new(0,18)},b)
        if selected then b.BackgroundColor3=C.darkRed;edge(b,C.red)end
        return b
    end
    local function clearOptions()
        for _,c in ipairs(temporary)do c:Disconnect()end;temporary={}
        local list=options:GetChildren();for i=#list,1,-1 do local o=list[i];if o:IsA('TextButton')or o:IsA('TextLabel')then o:Destroy()end end
    end
    local function openChoices(row)
        openModal('choice',row,label(row.d))
        renderOptions=function()
            clearOptions();local q=query.Text:lower()
            for i,v in ipairs(row.d.choices)do
                if q==''or(choiceLabel(v)..' '..v):lower():find(q,1,true)then
                    local b=optionButton('Option_'..row.d.id..'_'..i,choiceLabel(v),registry.get(row.d.id)==v,i)
                    ephemeral(b.Activated,function()local ok=bridge.run(row.d,v);if ok then closeModal()end end)
                end
            end
        end;renderOptions()
    end
    local function openPlayers(row)
        openModal('players',row,word('players'))
        renderOptions=function()
            clearOptions();local q=query.Text:lower();local list=Players:GetPlayers()
            table.sort(list,function(a,b)return a.Name:lower()<b.Name:lower()end)
            local count=0
            for i,p in ipairs(list)do
                if q==''or(p.Name..' '..p.DisplayName):lower():find(q,1,true)then
                    count=count+1
                    local b=optionButton('PlayerOption_'..p.UserId,p.DisplayName..'  (@'..p.Name..')',registry.get(row.d.id)==p.Name,i)
                    ephemeral(b.Activated,function()row.control.Text=p.Name;local ok=bridge.run(row.d,p.Name);if ok then closeModal()end end)
                end
            end
            if count==0 then local l=text(options,'NoPlayerResults',0,64,21);l.Text=word('none');l.Size=UDim2.new(1,0,0,64)end
        end;renderOptions()
    end
    local function refreshPlayerOptions()if modalMode=='players'and renderOptions then renderOptions()end end
    track(Players.PlayerAdded,refreshPlayerOptions);track(Players.PlayerRemoving,function()task.defer(refreshPlayerOptions)end)
    local function rgb(value)
        local a,b,c=tostring(value or''):match('^%s*(%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*$')
        if a then return {math.min(255,tonumber(a)),math.min(255,tonumber(b)),math.min(255,tonumber(c))}end
        return {255,255,255}
    end
    local function openColor(row)
        openModal('color',row,word('color'));applyDialog.Text=word('useColor')
        local values=rgb(row.control.Text);local valid=true;local channels={}
        local preview=make('Frame',{Name='ColorPreview',Position=UDim2.fromOffset(0,0),Size=UDim2.new(1,0,0,66),BorderSizePixel=0},body);round(preview,10)
        local hex=input(preview,'ColorHex','');hex.Position=UDim2.new(1,-184,0,10);hex.Size=UDim2.fromOffset(174,46)
        local rgbLabel=text(preview,'RGBPreview',0,66,20);rgbLabel.Size=UDim2.new(1,-200,0,66);rgbLabel.TextColor3=Color3.new(1,1,1)
        local function redraw()
            valid=true;preview.BackgroundColor3=Color3.fromRGB(values[1],values[2],values[3]);hex.Text=string.format('#%02X%02X%02X',values[1],values[2],values[3])
            rgbLabel.Text=table.concat(values,', ')
            rgbLabel.TextColor3=(values[1]*.299+values[2]*.587+values[3]*.114)>155 and Color3.new(0,0,0)or Color3.new(1,1,1)
            for i,c in ipairs(channels)do c.draw(values[i])end
        end
        for i,c in ipairs({{235,41,63},{255,255,255},{15,15,18},{57,208,224},{148,83,235},{250,191,47},{62,214,131},{58,125,243}})do
            local b=btn(body,'ColorPreset_'..i,'');rect(b,(i-1)*68,80,56,38);b.BackgroundColor3=Color3.fromRGB(c[1],c[2],c[3])
            ephemeral(b.Activated,function()values={c[1],c[2],c[3]};redraw()end)
        end
        for i,k in ipairs({'R','G','B'})do
            local c=slider(body,'Color'..k,0,255,1,values[i],function(n)values[i]=n;redraw()end,nil,ephemeral)
            c.host.Position=UDim2.fromOffset(28,136+(i-1)*64);c.host.Size=UDim2.new(1,-28,0,48)
            local l=text(body,'Channel_'..k,136+(i-1)*64,48,21);l.Position=UDim2.fromOffset(0,136+(i-1)*64);l.Size=UDim2.fromOffset(24,48);l.Text=k
            channels[i]=c
        end
        ephemeral(hex.FocusLost,function()
            local v=hex.Text:gsub('^#','')
            if #v==6 and v:match('^%x+$')then values={tonumber(v:sub(1,2),16),tonumber(v:sub(3,4),16),tonumber(v:sub(5,6),16)};redraw()
            else valid=false;notify(word('invalidColor'),false)end
        end)
        applyEditor=function()
            if not valid then notify(word('invalidColor'),false);return end
            row.control.Text=table.concat(values,',');local ok=bridge.run(row.d,row.control.Text);if ok then closeModal()end
        end
        redraw()
    end
    local function openJSON(row)
        openModal('json',row,label(row.d));applyDialog.Text=word('apply')
        local editor=input(body,'ExpandedJSON',row.control.Text);editor.Size=UDim2.fromScale(1,1);editor.TextSize=21;editor.MultiLine=true
        editor.TextWrapped=true;editor.TextXAlignment=Enum.TextXAlignment.Left;editor.TextYAlignment=Enum.TextYAlignment.Top
        make('UIPadding',{PaddingTop=UDim.new(0,12),PaddingLeft=UDim.new(0,12),PaddingRight=UDim.new(0,12)},editor)
        applyEditor=function()row.control.Text=editor.Text;local ok=bridge.run(row.d,editor.Text);if ok then closeModal()end end
    end

    openReport=function(row,value)
        openModal('report',row,label(row.d));applyDialog.Text=word('copy')
        local scroll=make('ScrollingFrame',{Name='ReportScroll',Size=UDim2.fromScale(1,1),BackgroundTransparency=1,BorderSizePixel=0,
            AutomaticCanvasSize=Enum.AutomaticSize.Y,CanvasSize=UDim2.new(),ScrollBarThickness=4,ScrollBarImageColor3=C.red},body)
        local box=input(scroll,'ExpandedReport',value);box.Size=UDim2.new(1,-12,0,0);box.AutomaticSize=Enum.AutomaticSize.Y
        box.TextEditable=false;box.MultiLine=true;box.TextWrapped=true;box.TextXAlignment=Enum.TextXAlignment.Left;box.TextYAlignment=Enum.TextYAlignment.Top
        applyEditor=function()copy(value,box);notify(word('copy')..' · '..word('done'),true)end
