    local function stepFor(d)
        if d.step then return d.step end
        if d.max-d.min<=2 then return .01 elseif d.max-d.min<=10 then return .05
        elseif d.default and d.default%1~=0 then return .1 else return 1 end
    end
    local actionKeys={sit='sit',stand='stand',rejoin='rejoin',server_hop='hop',role_query='scan',lua_http_test='scan',spectate_cycle='choose',feature_search='searchAction',stop_all='stop',stop_travel='stop',stop_horizontal='stop',stop_vertical='stop',load_prefs='load'}
    local function actionText(id)
        if actionKeys[id]then return word(actionKeys[id])end
        if id:find('^go_')or id=='return_ground'then return word('go')end
        if id:find('^save_')then return word('save')end
        if id:find('^clear_')then return word('clear')end
        if id:find('^restore_')then return word('restore')end
        if id:find('^copy_')or id:find('^export_')then return word('copy')end
        return word('run')
    end
    local counters={}
    local function mark(row,kind)
        row.frame:SetAttribute('WidgetType',kind);row.control:SetAttribute('WidgetType',kind);counters[kind]=(counters[kind]or 0)+1
    end
    for _,row in pairs(rows)do
        local d,frame=row.d,row.frame
        row.title.Position=UDim2.fromOffset(18,8);row.title.Size=UDim2.new(1,-96,0,48)
