    local function refresh()
        for _,row in pairs(rows)do
            local d=row.d;local v=registry.get(d.id)
            if d.kind=='text'and v~=row.committedText then row.committedText=v;row.control.Text=tostring(v or'')end
            if row.knob then
                local on=v==true;row.control.BackgroundColor3=on and C.red or Color3.fromRGB(241,225,208)
                row.switchState.Text=tr(on and'on'or'off');row.switchState.TextColor3=on and C.red or C.muted
                row.control:SetAttribute('AccessibleLabel',label(d)..' · '..tr(on and'on'or'off'))
                if row.lastSwitch~=on then
                    if row.switchTween then row.switchTween:Cancel()end
                    if row.glowTween then row.glowTween:Cancel()end
                    if row.lastSwitch==nil then row.switchGlow.Transparency=on and .28 or .94 else row.glowTween=TweenService:Create(row.switchGlow,TweenInfo.new(gui:GetAttribute('ReduceMotion')and 0 or .22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Transparency=on and .28 or .94});row.glowTween:Play()end
                    local target=UDim2.fromOffset(on and 74 or 6,6)
                    if row.lastSwitch==nil then row.knob.Position=target else row.switchTween=TweenService:Create(row.knob,TweenInfo.new(gui:GetAttribute('ReduceMotion')and 0 or .14,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Position=target});row.switchTween:Play()end
                    row.lastSwitch=on
                end
            elseif row.slider then
                if not dragging or dragging.control~=row.slider then row.slider.draw(v)end
                row.range.Text=word('range')..': '..fmt(d.min)..' – '..fmt(d.max)..'   ·   '..word('release')
                row.reset:SetAttribute('AccessibleLabel',word('reset'))
            elseif d.kind=='choice'then row.control.Text=choiceLabel(v)
            elseif d.id=='target_player'then row.control.PlaceholderText=word('typePlayer');row.apply.Text=word('choose')
            elseif (d.id=='color_tint'or d.valueType=='color')then local c=rgb(row.control.Text);row.picker.BackgroundColor3=Color3.fromRGB(c[1],c[2],c[3]);row.picker.Text='';row.apply.Text=word('apply')
            elseif row.vector then
                local value=tostring(v or'0,0,0')
                if value~=row.vectorValue then
                    local a,b,c=value:match('^%s*([%d%.%-]+)%s*,%s*([%d%.%-]+)%s*,%s*([%d%.%-]+)%s*$')
                    local values={a or'0',b or'0',c or'0'};for i,o in ipairs(row.vector)do o.Text=values[i]end;row.vectorValue=value
                end
            elseif row.expand then row.expand.Text=word('edit');row.apply.Text=word('import')
            elseif d.kind=='report'then row.control.Text=word('view')..'  ›'
            elseif d.kind=='action'then row.control.Text=actionText(d.id)..'  ›'end
        end
    end
    local function refreshLockStatus()
        local row=rows.super_lock;if not row or not row.lockStatus then return end
        local state=gui:GetAttribute('SuperLockState')or'off'
        row.lockStatus.Text=tr('superLock_'..state)..(state=='locked'and(' · '..(gui:GetAttribute('SuperLockTarget')or''))or'')
        row.lockStatus.TextColor3=state=='locked'and C.red or C.muted
    end
    for _,key in ipairs({'SuperLockState','SuperLockTarget','Language'})do track(gui:GetAttributeChangedSignal(key),refreshLockStatus)end
    refreshLockStatus()
    bridge.refreshWidgets=refresh
    track(gui:GetAttributeChangedSignal('Language'),function()closeModal();refresh()end)
    local kinds=0;for k,n in pairs(counters)do kinds=kinds+1;gui:SetAttribute('WidgetCount_'..k:gsub('[^%w_]','_'),n)end
    gui:SetAttribute('WidgetKinds',kinds);gui:SetAttribute('WidgetControls',#RUBY_CONTROLS);gui:SetAttribute('RichControls',true)
    local cleanupBefore=onCleanup
    onCleanup=function()
        closeModal()
        for _,row in pairs(rows)do if row.switchTween then row.switchTween:Cancel()end;if row.glowTween then row.glowTween:Cancel()end end
        if cleanupBefore then cleanupBefore()end
    end
    refresh();fitModal()
end
