    end
    -- Artwork download is optional, starts after initialization and cannot hide the base UI.
    task.defer(function()
        if not alive or type(customAsset)~='function'or type(writefile)~='function'then return end
        resourceThread=task.spawn(function()
            local ok,asset=pcall(function()
                local bytes=game:HttpGet(CLOUD..'/ruby-v1-release.png')
                if not alive then return nil end
                if type(bytes)~='string'or bytes:sub(1,8)~='\137PNG\r\n\26\n'or #bytes>12000000 then return nil end
                local path='SALAPAO_release_v1.png';writefile(path,bytes);return customAsset(path)
            end)
            if alive then
                if ok and type(asset)=='string'then
                    art.Image=asset
                    local function sync()if alive then art.Visible=art.IsLoaded;fallback.Visible=not art.IsLoaded end end
                    track(art:GetPropertyChangedSignal('IsLoaded'),sync);sync()
                    gui:SetAttribute('ReleaseArtworkStatus','available')
                else gui:SetAttribute('ReleaseArtworkStatus','fallback')end
            end
        end)
    end)

end

