-- NEBULA CLOUD · RUBY motion: center split reveal, left scrolling and soft scroll edges.
local function installRubyMotion()
    local ref=assert(gui:FindFirstChild('ReferenceLayout',true),'Reference layout is unavailable')
    local groups={reveal={},page={},selection={}}
    local motionAlive=true
    local revealRevision,pageRevision=0,0
    local function stop(which)
        local list=groups[which];groups[which]={}
        for _,v in ipairs(list)do if v.connection then v.connection:Disconnect()end end
        for _,v in ipairs(list)do v.tween:Cancel()end
    end
    local function tween(which,obj,seconds,properties,finished)
        local item={tween=TweenService:Create(obj,TweenInfo.new(seconds,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),properties)}
        groups[which][#groups[which]+1]=item
        if finished then item.connection=item.tween.Completed:Connect(function(state)
            if item.connection then item.connection:Disconnect();item.connection=nil end
            if motionAlive and alive and state==Enum.PlaybackState.Completed then finished()end
        end)end
        item.tween:Play();return item.tween
    end
    local function reduced()return gui:GetAttribute('ReduceMotion')==true end
    local function zero()return UDim2.new()end
    local pageLayer=make('Frame',{Name='PageMotionLayer',Size=UDim2.fromScale(1,1),Position=zero(),
        BackgroundTransparency=1,BorderSizePixel=0,ZIndex=2},content)
    for _,p in pairs(pages)do p.Parent=pageLayer;p.ScrollBarThickness=0 end
    local arrival=make('Frame',{Name='PageArrivalVeil',Size=UDim2.fromScale(1,1),BackgroundColor3=C.bg,
        BackgroundTransparency=1,BorderSizePixel=0,Active=false,Visible=false,ZIndex=7},content)
    local fade=make('Frame',{Name='ScrollTopSoftEdge',Size=UDim2.new(1,0,0,46),Position=zero(),BackgroundColor3=C.bg,
        BackgroundTransparency=1,BorderSizePixel=0,Active=false,Visible=false,ZIndex=8},content)
    make('UIGradient',{Rotation=90,Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0),
        NumberSequenceKeypoint.new(.28,.15),NumberSequenceKeypoint.new(.65,.7),NumberSequenceKeypoint.new(1,1)})},fade)
    gui:SetAttribute('ScrollEdgeStyle','SoftFade')

    -- Native left-side category scroll; a wider, touch-friendly rail controls the current content page.
    nav.VerticalScrollBarPosition=Enum.VerticalScrollBarPosition.Left
    nav.ScrollBarThickness=6;nav.ScrollBarImageColor3=C.red;nav.ZIndex=5
    local rail=make('TextButton',{Name='ContentScrollRail',Size=UDim2.fromOffset(20,100),Text='',
        BackgroundTransparency=1,BorderSizePixel=0,AutoButtonColor=false,Visible=false,ZIndex=12},ref)
    local trackBar=make('Frame',{Name='ContentScrollTrack',Position=UDim2.fromOffset(8,4),Size=UDim2.new(0,4,1,-8),
        BackgroundColor3=C.card,BorderSizePixel=0,Active=false},rail);corner(trackBar,3)
    local thumb=make('TextButton',{Name='ContentScrollThumb',Size=UDim2.fromOffset(12,42),Position=UDim2.fromOffset(4,4),Text='',
        BackgroundColor3=C.red,BorderSizePixel=0,AutoButtonColor=false,ZIndex=13},rail);corner(thumb,6)
    local dragging=nil
    local function uiScale()local s=ref:FindFirstChild('ReferenceScale');return math.max(.01,s and s.Scale or 1)end
    local function viewport(p)
        local window=p.AbsoluteWindowSize
        local h=window and window.Y or(p.AbsoluteSize and p.AbsoluteSize.Y)or 1
        if h<=0 then h=1 end
        local canvas=p.AbsoluteCanvasSize
        local ch=canvas and canvas.Y or(p.CanvasSize and p.CanvasSize.Y.Offset)or h
        if ch<=0 then ch=h end
        return h,math.max(h,ch)
    end
    local function updateScroll()
        if not motionAlive or not alive then return end
        local p=pages[activePage];if not p then rail.Visible=false;fade.Visible=false;return end
        local hitWidth=math.clamp(28/uiScale(),20,56)
        rail.Position=UDim2.new(content.Position.X.Scale,content.Position.X.Offset-hitWidth+4,content.Position.Y.Scale,content.Position.Y.Offset)
        rail.Size=UDim2.new(0,hitWidth,content.Size.Y.Scale,content.Size.Y.Offset)
        trackBar.Position=UDim2.fromOffset(hitWidth-12,4)
        local view,canvas=viewport(p);local maximum=math.max(0,canvas-view)
        local current=p.CanvasPosition and p.CanvasPosition.Y or 0
        rail.Visible=maximum>1 and panel.Visible
        local fraction=math.clamp(view/canvas,0,1)
        local height=math.max(0,(rail.AbsoluteSize and rail.AbsoluteSize.Y/uiScale()or view)-8)
        local minimum=math.min(36,height)
        local bar=math.clamp(height*fraction,minimum,height)
        local position=maximum>0 and math.clamp(current/maximum,0,1)or 0
        thumb.Size=UDim2.new(0,12,0,bar);thumb.Position=UDim2.fromOffset(hitWidth-16,4+position*(height-bar))
        rail:SetAttribute('MaximumScroll',maximum);thumb:SetAttribute('ScrollFraction',position)
        fade.Visible=maximum>1 and current>.5
        fade.BackgroundTransparency=1-math.clamp(current/36,0,1)
        fade:SetAttribute('Strength',math.clamp(current/36,0,1))
    end
    local function beginDrag(input,fromThumb)
        if input.UserInputType~=Enum.UserInputType.Touch and input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
        local p=pages[activePage];if not p then return end
        local view,canvas=viewport(p);local maximum=canvas-view;if maximum<=0 then return end
        local rp=rail.AbsolutePosition or Vector2.new();local rs=rail.AbsoluteSize or Vector2.new(20,view)
        local scale=uiScale();local height=math.max(1,rs.Y-8*scale);local bh=math.clamp(height*view/canvas,math.min(36*scale,height),height)
        local y=input.Position.Y-rp.Y-4*scale
        local top=maximum>0 and math.clamp((p.CanvasPosition and p.CanvasPosition.Y or 0)/maximum,0,1)*(height-bh)or 0
        dragging={input=input,page=p,grab=fromThumb and math.clamp(y-top,0,bh)or bh/2}
        if not fromThumb then
            local f=math.clamp((y-bh/2)/math.max(1,height-bh),0,1)
            p.CanvasPosition=Vector2.new(p.CanvasPosition and p.CanvasPosition.X or 0,f*maximum)
        end
        gui:SetAttribute('ScrollRailDragging',true)
    end
    track(rail.InputBegan,function(input)beginDrag(input,false)end)
    track(thumb.InputBegan,function(input)beginDrag(input,true)end)
    track(UIS.InputChanged,function(input)
        if not dragging then return end
        if dragging.input.UserInputType==Enum.UserInputType.Touch and input~=dragging.input then return end
        if dragging.input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local p=dragging.page;local view,canvas=viewport(p);local rp=rail.AbsolutePosition or Vector2.new();local rs=rail.AbsoluteSize or Vector2.new(20,view)
        local scale=uiScale();local height=math.max(1,rs.Y-8*scale);local bh=math.clamp(height*view/canvas,math.min(36*scale,height),height)
        local f=math.clamp((input.Position.Y-rp.Y-4*scale-dragging.grab)/math.max(1,height-bh),0,1)
        p.CanvasPosition=Vector2.new(p.CanvasPosition and p.CanvasPosition.X or 0,f*math.max(0,canvas-view))
    end)
    track(UIS.InputEnded,function(input)
        if dragging and(input==dragging.input or dragging.input.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)then
            dragging=nil;gui:SetAttribute('ScrollRailDragging',false)
        end
    end)
    for _,p in pairs(pages)do
        for _,key in ipairs({'CanvasPosition','AbsoluteCanvasSize','AbsoluteWindowSize','AbsoluteSize'})do track(p:GetPropertyChangedSignal(key),function()if p==pages[activePage]then updateScroll()end end)end
    end

    -- One indicator slides between category buttons; it is outside the list layout.
    local selectionHost=make('Frame',{Name='CategorySelectionViewport',BackgroundTransparency=1,BorderSizePixel=0,
        ClipsDescendants=true,ZIndex=4},ref)
    local selection=make('Frame',{Name='SlidingCategorySelection',BackgroundColor3=C.darkRed,BackgroundTransparency=.42,
        BorderSizePixel=0,Visible=false},selectionHost);corner(selection,10)
    local accent=make('Frame',{Name='CategorySelectionAccent',Position=UDim2.new(0,2,.2,0),Size=UDim2.new(0,3,.6,0),
        BackgroundColor3=C.red,BorderSizePixel=0},selection);corner(accent,2)
    local switching=false
    local function updateSelection(animate)
        if not motionAlive or not alive then return end
        selectionHost.Position=nav.Position;selectionHost.Size=nav.Size
        local b=tabs[activePage]
        for _,tab in pairs(tabs)do
            tab.BackgroundTransparency=1
            local dot=tab:FindFirstChild('ActiveDot');if dot then dot.BackgroundTransparency=1 end
        end
        if not b then stop('selection');selection.Visible=false;return end
        local h=b.Size.Y.Offset;local y
        if b.AbsolutePosition and nav.AbsolutePosition then
            local scale=ref:FindFirstChild('ReferenceScale');local s=scale and scale.Scale or 1
            y=(b.AbsolutePosition.Y-nav.AbsolutePosition.Y)/math.max(.01,s)
        else y=((b.LayoutOrder or 1)-1)*(h+navLayout.Padding.Offset)-(nav.CanvasPosition and nav.CanvasPosition.Y or 0)end
        local goal=UDim2.new(0,0,0,y);local size=UDim2.new(1,-2,0,h)
        stop('selection');local hadSelection=selection.Visible;selection.Visible=true
        if animate and hadSelection and not reduced()then tween('selection',selection,.25,{Position=goal,Size=size})
        else selection.Position=goal;selection.Size=size end
        selection:SetAttribute('SelectedPage',activePage)
    end
    track(nav:GetPropertyChangedSignal('CanvasPosition'),function()updateSelection(false)end)
    for _,key in ipairs({'Position','Size'})do
        track(nav:GetPropertyChangedSignal(key),function()if not switching then updateSelection(false)end end)
        track(content:GetPropertyChangedSignal(key),updateScroll)
    end
    local oldSwitch=switchPage
    switchPage=function(key)
        local changed=key~=activePage
        pageRevision=pageRevision+1;local revision=pageRevision
        dragging=nil;gui:SetAttribute('ScrollRailDragging',false);stop('page')
        pageLayer.Position=zero();arrival.Visible=false;arrival.BackgroundTransparency=1
        switching=true;oldSwitch(key);switching=false;updateSelection(changed);updateScroll()
        if changed and open and not reduced()then
            pageLayer.Position=UDim2.fromOffset(0,22);arrival.BackgroundTransparency=.55;arrival.Visible=true
            gui:SetAttribute('PageTransition','SlideUp');gui:SetAttribute('PageTransitionTarget',key)
            tween('page',arrival,.24,{BackgroundTransparency=1})
            tween('page',pageLayer,.28,{Position=zero()},function()
                if revision==pageRevision then arrival.Visible=false;gui:SetAttribute('PageTransition','Idle')end
            end)
        else gui:SetAttribute('PageTransition','Idle')end
    end

    -- A black center bar expands, then its upper and lower curtains separate.
    local cover=make('Frame',{Name='SplitRevealCover',Position=panel.Position,Size=panel.Size,
        BackgroundTransparency=1,BorderSizePixel=0,ClipsDescendants=true,Active=true,Visible=false,ZIndex=100},surface)
    local upper=make('Frame',{Name='SplitRevealUpper',Position=UDim2.fromScale(0,.5),AnchorPoint=Vector2.new(0,1),
        Size=UDim2.fromScale(1,.5),BackgroundColor3=Color3.new(0,0,0),BorderSizePixel=0,ZIndex=101},cover)
    local lower=make('Frame',{Name='SplitRevealLower',Position=UDim2.fromScale(0,.5),
        Size=UDim2.fromScale(1,.5),BackgroundColor3=Color3.new(0,0,0),BorderSizePixel=0,ZIndex=101},cover)
    local function syncCover()cover.Position=panel.Position;cover.Size=panel.Size end
    track(panel:GetPropertyChangedSignal('Position'),syncCover);track(panel:GetPropertyChangedSignal('Size'),syncCover)
    local function cancelReveal(snap)
        revealRevision=revealRevision+1;stop('reveal');cover.Visible=false
        if snap and alive then panel.Size=UDim2.fromOffset(width,height);panel.Position=UDim2.fromOffset(targetPosition.X,targetPosition.Y)end
        if alive then gui:SetAttribute('RevealPhase','Idle')end
    end
    local baseCancel=cancelOpenTween
    cancelOpenTween=function()baseCancel();cancelReveal(true);pageRevision=pageRevision+1;stop('page');pageLayer.Position=zero();arrival.Visible=false;if alive then gui:SetAttribute('PageTransition','Idle')end end
    local function prepareReveal()
        baseCancel();cancelReveal(false)
        upper.Position=UDim2.fromScale(0,.5);lower.Position=UDim2.fromScale(0,.5)
        panel.Visible=true;panel.Size=UDim2.fromOffset(width,8)
        panel.Position=UDim2.fromOffset(targetPosition.X,targetPosition.Y+(height-8)/2)
        cover.Visible=true;syncCover();gui:SetAttribute('RevealPhase','CenterBar')
    end
    local function reveal(prepared)
        if not alive or not motionAlive or not open then return end
        if reduced()then cancelReveal(true);return end
        if not prepared then prepareReveal()end
        local revision=revealRevision
        gui:SetAttribute('RevealPhase','Expanding')
        tween('reveal',panel,.23,{Size=UDim2.fromOffset(width,height),Position=UDim2.fromOffset(targetPosition.X,targetPosition.Y)},function()
            if revision~=revealRevision or not open then return end
            gui:SetAttribute('RevealPhase','Splitting')
            tween('reveal',upper,.28,{Position=UDim2.fromScale(0,0)})
            tween('reveal',lower,.28,{Position=UDim2.fromScale(0,1)},function()
                if revision==revealRevision then cover.Visible=false;gui:SetAttribute('RevealPhase','Idle')end
            end)
        end)
    end
    local oldOpen=setOpen
    setOpen=function(value)
        pageRevision=pageRevision+1;stop('page');pageLayer.Position=zero();arrival.Visible=false;gui:SetAttribute('PageTransition','Idle')
        oldOpen(value)
        if value then reveal(false)else cancelReveal(false);dragging=nil;gui:SetAttribute('ScrollRailDragging',false)end
        updateScroll()
    end
    track(panel:GetPropertyChangedSignal('Visible'),function()
        if not panel.Visible then cancelReveal(false);stop('page');pageLayer.Position=zero();arrival.Visible=false end
        updateScroll()
    end)
    track(gui:GetAttributeChangedSignal('ReduceMotion'),function()
        if reduced()then cancelReveal(true);stop('page');pageLayer.Position=zero();arrival.Visible=false;gui:SetAttribute('PageTransition','Idle');updateSelection(false)end
    end)
    local brand=make('TextLabel',{Name='PersistentCloudBrand',Position=UDim2.new(1,-145,1,-23),Size=UDim2.fromOffset(131,20),
        Text='NEBULA CLOUD',TextSize=11,TextColor3=C.muted,Font=Enum.Font.GothamBold,BackgroundTransparency=1,
        BorderSizePixel=0,TextXAlignment=Enum.TextXAlignment.Right,ZIndex=8},ref)
    local function footerFit()footer.Size=UDim2.new(1,-180,0,20)end
    track(ref:GetPropertyChangedSignal('Size'),function()footerFit();updateSelection(false);updateScroll()end);footerFit()
    local releaseNotes={
        TH={'v1.1.1 · การเคลื่อนไหวใหม่','แท่งดำเปิดจากกลางและแยกขึ้น–ลง · แถบเลื่อนด้านซ้าย · ขอบบนฟุ้งไล่จางเมื่อเลื่อน · ตัวเลือกหมวดเลื่อนตาม · หน้าใหม่เลื่อนขึ้น'},
        EN={'v1.1.1 · Motion update','Center split reveal · Left scroll rail · Soft top edge on scroll · Sliding category indicator · Pages slide upward'},
        ZH={'v1.1.1 · 动效更新','中央分开展示 · 左侧滚动条 · 滚动顶部渐隐 · 分类指示条平滑移动 · 页面向上出现'},
        JA={'v1.1.1・モーション更新','中央から上下に開く演出・左スクロールバー・上端のグラデーション・移動するカテゴリ表示・下から現れるページ'},
        KO={'v1.1.1 · 모션 업데이트','중앙에서 위아래로 열기 · 왼쪽 스크롤바 · 상단 가장자리 페이드 · 이동하는 카테고리 표시 · 위로 나타나는 페이지'},
        ES={'v1.1.1 · Nuevas animaciones','Apertura central dividida · Barra de desplazamiento izquierda · Borde superior suave · Indicador de categoría deslizante · Páginas que suben'},
