-- NEBULA CLOUD / RUBY: fixed-catalog AI packs, applied atomically after validation.
local function installRubyLanguages()
    local meta=RUBY_LOCALES.meta
    local embedded,registry,indexByCode={},{},{}
    for _,code in ipairs(meta.embedded)do embedded[code]=true end
    for i,entry in ipairs(meta.registry)do registry[entry.code]=entry;indexByCode[entry.code]=i end
    local status=info(pages.languages,'LanguageLoadStatus',106);status.Parent.LayoutOrder=-30;status.TextSize=18
    local search=make('TextBox',{Name='LanguageSearch',Size=UDim2.new(1,0,0,54),LayoutOrder=-40,
        BackgroundColor3=C.card,BorderSizePixel=0,Text='',ClearTextOnFocus=false,TextColor3=C.text,
        PlaceholderColor3=C.muted,Font=Enum.Font.Gotham,TextSize=20,TextWrapped=true},pages.languages);corner(search,10)
    local retry=button(pages.languages,'RetryLanguage');retry.LayoutOrder=-20;retry.Visible=false
    translationNote.Parent.LayoutOrder=-50;translationNote.TextSize=18
    local note=card(pages.updates,'Language196Notes',220);note.LayoutOrder=-50
    local noteTitle=bind(text(note,'Language196Title',16,52,24),'languageUpdateTitle');noteTitle.TextColor3=C.red
    local noteBody=bind(text(note,'Language196Body',76,126,19),'languageUpdateBody');noteBody.TextColor3=C.muted
    noteBody.TextYAlignment=Enum.TextYAlignment.Top
    local generation=0
    local pending,failed,progress=nil,nil,0
    local recent={}
    local preferencePath='SALAPAO_language_v1.json'
    local function cachePath(code)return 'SALAPAO_language_'..meta.hash..'_'..code..'.json'end
    local function complete(pack,code)
        if type(pack)~='table'or pack.schema~=meta.schema or pack.hash~=meta.hash or pack.language~=code or type(pack.strings)~='table'then return false end
        local count=0;for k,v in pairs(pack.strings)do
            if type(k)~='string'or type(v)~='string'or not v:match('%S')or #v>10000 or v:find('%z')then return false end
            count=count+1
        end
        if count~=#meta.keys then return false end
        for _,k in ipairs(meta.keys)do if type(pack.strings[k])~='string'then return false end end
        return true
    end
    local function readJSON(path)
        if type(readfile)~='function'then return nil end
        local ok,value=pcall(function()local raw=readfile(path);if type(raw)~='string'or #raw>500000 then return nil end;return HttpService:JSONDecode(raw)end)
        return ok and value or nil
    end
    local function writeJSON(path,value)
        if type(writefile)=='function'then pcall(function()writefile(path,HttpService:JSONEncode(value))end)end
    end
    local function statusText()
        search.PlaceholderText=tr('languageSearch');retry.Text=tr('languageRetry')
        local current=LANGS[langIndex];local source=embedded[current]and tr('languageBundled')or tr('languageAI')
        if pending then status.Text=tr('languageLoading')..' · '..LANG_NAMES[pending]..' · '..math.floor(progress*100)..'%'
        elseif failed then status.Text=tr('languageFailed')..'\n'..LANG_NAMES[failed]
        else status.Text=tr('languageSelected')..' · '..LANG_NAMES[current]..'\n'..source end
        retry.Visible=failed~=nil and pending==nil
        for code,b in pairs(languageButtons)do
            b.Text=LANG_NAMES[code]..' · '..registry[code].english..' ['..registry[code].tag..']'..(current==code and'  ✓'or'')
            b:SetAttribute('TranslationSource',embedded[code]and'Bundled'or'AIOnDemand')
            b:SetAttribute('TranslationReady',embedded[code]or RUBY_LOCALES[code]._ready==true)
            b:SetAttribute('Selected',current==code)
        end
    end
    local function filter()
        local q=tostring(search.Text or''):lower();local count=0
        for i,code in ipairs(LANGS)do
            local entry=registry[code]
            local hay=(entry.name..' '..entry.english..' '..entry.tag..' '..entry.code):lower()
            local show=q==''or hay:find(q,1,true)~=nil
            languageButtons[code].Visible=show;languageButtons[code].LayoutOrder=i;languageButtons[code].Size=UDim2.new(1,0,0,60)
            if show then count=count+1 end
        end
        gui:SetAttribute('LanguageSearchCount',count)
    end
    local alignments=setmetatable({},{__mode='k'})
    local function direction(obj)
        if not(obj:IsA('TextLabel')or obj:IsA('TextButton')or obj:IsA('TextBox'))then return end
        -- Let Roblox shape and order Unicode; never reverse UTF-8 bytes.
        pcall(function()obj.TextDirection=Enum.TextDirection.Auto end)
        if not alignments[obj]then alignments[obj]=obj.TextXAlignment end
        local base=alignments[obj]
        if base==Enum.TextXAlignment.Left or base==Enum.TextXAlignment.Right then
            obj.TextXAlignment=registry[LANGS[langIndex]].direction=='rtl'and Enum.TextXAlignment.Right or base
        end
    end
    local function updateDirection()
        for _,obj in ipairs(gui:GetDescendants())do direction(obj)end
        gui:SetAttribute('LanguageDirection',registry[LANGS[langIndex]].direction)
    end
    local function trimCache(code)
        for i=#recent,1,-1 do if recent[i]==code then table.remove(recent,i)end end
        recent[#recent+1]=code
        while #recent>2 do
            local old=table.remove(recent,1)
            if old~=LANGS[langIndex]then
                for key in pairs(RUBY_LOCALES[old])do RUBY_LOCALES[old][key]=nil end
                for _,d in ipairs(RUBY_CONTROLS)do d[old]=nil end
            end
        end
        gui:SetAttribute('RemoteLanguageCacheCount',#recent)
    end
    local function commit(code,pack)
        if pack then
            for key,value in pairs(pack.strings)do RUBY_LOCALES[code][key]=value end
            RUBY_LOCALES[code]._ready=true
            for _,d in ipairs(RUBY_CONTROLS)do d[code]=pack.strings['feature:'..d.id]end
        end
        pending,failed,progress=nil,nil,1
        langIndex=indexByCode[code];applyLanguage()
        if not embedded[code]then trimCache(code)end
        gui:SetAttribute('LanguageLoadState','Ready');gui:SetAttribute('LanguageLoadTarget',code)
        writeJSON(preferencePath,{schema=1,language=code})
        statusText();updateDirection()
    end
    selectRubyLanguage=function(index)
        local code=LANGS[index];if not code or not alive then return end
        generation=generation+1;local revision=generation
        pending,failed,progress=code,nil,0
        gui:SetAttribute('LanguageLoadTarget',code);gui:SetAttribute('LanguageLoadState','Loading');statusText()
        if embedded[code]or RUBY_LOCALES[code]._ready then commit(code);return end
        task.spawn(function()
            local disk=readJSON(cachePath(code))
            if not alive or revision~=generation then return end
            if complete(disk,code)then commit(code,disk);return end
            local pack={schema=meta.schema,hash=meta.hash,language=code,strings={}}
            local ok=pcall(function()
                for part=0,meta.parts-1 do
                    if not alive or revision~=generation then return end
                    local data
                    for attempt=1,20 do
                        local raw=game:HttpGet(CLOUD..'/api/ruby/i18n/'..code..'/'..part..'?v='..meta.hash)
                        if not alive or revision~=generation then return end
                        if type(raw)~='string'or #raw>200000 then error('Invalid language response')end
                        data=HttpService:JSONDecode(raw)
                        if type(data)~='table'or data.status~='pending'then break end
                        task.wait(3)
                        if not alive or revision~=generation then return end
                    end
                    if type(data)~='table'or data.status~='ready'or data.language~=code or data.hash~=meta.hash or data.part~=part or data.parts~=meta.parts or type(data.strings)~='table'then error('Language unavailable')end
                    for k,v in pairs(data.strings)do if pack.strings[k]~=nil then error('Duplicate language key')end;pack.strings[k]=v end
                    progress=(part+1)/meta.parts;gui:SetAttribute('LanguageLoadProgress',progress);statusText()
                end
                if not complete(pack,code)then error('Incomplete language pack')end
            end)
            if not alive or revision~=generation then return end
            if ok and complete(pack,code)then writeJSON(cachePath(code),pack);commit(code,pack)
            else pending,failed=nil,code;gui:SetAttribute('LanguageLoadState','Error');statusText()end
        end)
    end
    track(retry.Activated,function()if failed then selectRubyLanguage(indexByCode[failed])end end)
    track(search:GetPropertyChangedSignal('Text'),filter)
    track(gui:GetAttributeChangedSignal('Language'),function()statusText();updateDirection()end)
    track(gui.DescendantAdded,direction)
    local oldCleanup=onCleanup
    onCleanup=function()generation=generation+1;alignments={};if oldCleanup then oldCleanup()end end
    gui:SetAttribute('LanguageCount',#LANGS);gui:SetAttribute('EmbeddedLanguageCount',#meta.embedded)
    gui:SetAttribute('TranslationSchemaHash',meta.hash);gui:SetAttribute('TranslationParts',meta.parts)
    gui:SetAttribute('RemoteLanguageCacheCount',0);gui:SetAttribute('LanguageLoadState','Ready')
    gui:SetAttribute('ReleaseName','v1.2.0');footer.Text='ซาลาเปา v1.2.0 · 500 · NEBULA CLOUD'
    filter();statusText();updateDirection()
    task.defer(function()
        if not alive then return end
        local pref=readJSON(preferencePath)
        if type(pref)=='table'and pref.schema==1 and indexByCode[pref.language]then selectRubyLanguage(indexByCode[pref.language])end
    end)
end
local languagesOK,languagesError=pcall(installRubyLanguages)
if not languagesOK then gui:SetAttribute('LanguagesError',tostring(languagesError));warn('ซาลาเปา languages: '..tostring(languagesError))end

