            elseif device or aiState=='connecting'then pairRevision=pairRevision+1;device=nil;rubyAI.queued=nil;rubyAI.guide=false;aiState='disconnected';rubyAI.changed()
            else error(tr('chat9NotBusy'),0)end
        elseif field=='undo_draft'then if #undo==0 then error('No previous draft',0)end;redo[#redo+1]=aiInput.Text;changeDraft(table.remove(undo))
        elseif field=='redo_draft'then if #redo==0 then error('No later draft',0)end;undo[#undo+1]=aiInput.Text;changeDraft(table.remove(redo))
        elseif field=='save_draft'then savedDraft=aiInput.Text;if type(writefile)=='function'then pcall(writefile,'SALAPAO_chat_draft.txt',savedDraft)end
        elseif field=='load_draft'then
            if not savedDraft and type(readfile)=='function'then local ok,raw=pcall(readfile,'SALAPAO_chat_draft.txt');if ok and type(raw)=='string'and #raw<=4000 and raw~=''then savedDraft=raw end end
            if savedDraft==nil then error(tr('chat9NoSavedDraft'),0)end;aiInput.Text=savedDraft
        elseif field=='clear_saved_draft'then savedDraft=nil;if type(writefile)=='function'then pcall(writefile,'SALAPAO_chat_draft.txt','')end
        elseif field=='conversation_export'then return encode(exported())
        elseif field=='conversation_import'then
            if aiBusy then error(tr('chat9Sending'),0)end
            local ok,doc=pcall(function()return HttpService:JSONDecode(value)end)
            if not ok or type(doc)~='table'or doc.schema~=1 or type(doc.history)~='table'or #doc.history>12 or #doc.history%2~=0 then error('Invalid conversation JSON',0)end
            local checked,total={},0
            for i,t in ipairs(doc.history)do
                if type(t)~='table'or t.role~=(i%2==1 and'user'or'model')or type(t.text)~='string'or t.text==''or #t.text>8000 then error('Invalid conversation turn',0)end
                total=total+#t.text;if total>20000 then error('Conversation is too large',0)end;checked[#checked+1]={role=t.role,text=t.text}
            end
            rubyAI.clear();history=checked;for _,t in ipairs(checked)do rubyAI.add(t.role=='user'and'you'or'assistant',t.text)end
        elseif field=='conversation_new'then rubyAI.clear();rubyAI.queued=nil;aiInput.Text=''
        elseif field=='history_omit_last'then if #history<2 then error(tr('chat9NoHistory'),0)end;local model=table.remove(history);local user=table.remove(history);omitted[#omitted+1]={user,model}
        elseif field=='history_restore'then
            if #omitted==0 then error(tr('chat9NoHistory'),0)end
            local pair=table.remove(omitted);local n=0;for _,t in ipairs(history)do n=n+#t.text end
            if #history>=12 or n+#pair[1].text+#pair[2].text>20000 then omitted[#omitted+1]=pair;error('Context is full',0)end
            history[#history+1]=pair[1];history[#history+1]=pair[2]
        elseif field=='history_report'then return encode({turns=#history,pairs=#history/2,history=history})
        elseif field=='copy_last_user'then for i=#messages,1,-1 do if messages[i].role=='you'then return clipboard(messages[i].value)end end;error(tr('chat9NoHistory'),0)
        elseif field=='copy_entire_conversation'then local lines={};for _,m in ipairs(messages)do lines[#lines+1]=tr(m.role)..': '..m.value end;return clipboard(table.concat(lines,'\n\n'))
        elseif field=='attach_points'then local p=bridge.tools.ultra.inspect().points;local doc={};for k,v in pairs(p)do doc[k]={x=v.X,y=v.Y,z=v.Z}end;append(encode({measurement=doc}))
        elseif field=='attach_hud'then local lines={};for metric,t in pairs(bridge.tools.ultra.inspect().tiles)do if t.Visible then lines[metric]=t.Text end end;append(encode({hud=lines}))
        elseif field=='attach_settings'then local values={};for _,spec in ipairs(RUBY_CONTROLS)do if(spec.kind=='number'or spec.kind=='toggle'or spec.kind=='choice')and bridge.tools.get(spec.id)~=spec.default then values[spec.id]=bridge.tools.get(spec.id)end end;append(encode({settings=values}))
        elseif field=='insert_newline'then aiInput.Text=aiInput.Text..'\n'
        elseif field=='insert_bullet'then aiInput.Text=aiInput.Text..'\n- '
        elseif field=='insert_codeblock'then aiInput.Text=aiInput.Text..'\n```\n\n```'
        elseif field=='connection_help'then rubyAI.guide=true;if not aiToken then rubyAI.start()else rubyAI.changed()end
        elseif field=='connection_retry'then rubyAI.disconnect();rubyAI.start()
        elseif field=='context_preview'then return encode(rubyAI.payload and rubyAI.payload(aiInput.Text)or{message=aiInput.Text,history=history})
        elseif field=='user_color'or field=='assistant_color'then rubyAI.render()
        else error('Unknown conversation command: '..tostring(field),0)end
        rubyAI.changed();return true
    end
    local cleanupBefore=onCleanup
    onCleanup=function()clearLinks();rubyAI.render=nil;if cleanupBefore then cleanupBefore()end end
    rubyAI.changed()
end
