-- NEBULA CLOUD / RUBY: additional equipment and one shared, explicit shot action.
do
local function installRubyExtraUI()
    local bridge=assert(rubyControlUI);local row=assert(bridge.rows.shoot_murderer)
    local O=bridge.context.options
    local function option(key,default)local value=O['eq_'..key];if value==nil then return default end;return value end
    local help=card(pages.extraPage,'ExtraShotHelpCard',228);help.LayoutOrder=-20
    local heading=bind(text(help,'ExtraShotHelpTitle',14,44,25),'extraPage');heading.TextColor3=C.red
    local body=bind(text(help,'ExtraShotHelpBody',68,142,19),'extraHelp');body.TextColor3=C.muted;body.TextYAlignment=Enum.TextYAlignment.Top
    row.frame.Size=UDim2.new(1,0,0,162);row.title.Size=UDim2.new(1,-282,0,80)
    local status=text(row.frame,'ExtraShotStatus',92,58,17);status.Size=UDim2.new(1,-36,0,58);status.TextColor3=C.muted
    -- This is outside the window so minimizing RUBY leaves the touch control usable.
    local fire=make('TextButton',{Name='ExtraTouchFire',Size=UDim2.fromOffset(64,64),
        BackgroundColor3=C.card,BackgroundTransparency=.08,BorderSizePixel=0,
        Text='',TextColor3=C.text,Font=Enum.Font.GothamBold,TextSize=17,
        AutoButtonColor=true,Active=true,Visible=false,ZIndex=40},surface)
    make('UICorner',{CornerRadius=UDim.new(.5,0)},fire)
    local ring=make('UIStroke',{Color=C.red,Thickness=2,Transparency=.15},fire)
    local mark=make('Frame',{Name='FireReticle',AnchorPoint=Vector2.new(.5,.5),
        Position=UDim2.new(.5,0,0,20),Size=UDim2.fromOffset(18,18),
        BackgroundTransparency=1,BorderSizePixel=0,ZIndex=41},fire)
    make('UICorner',{CornerRadius=UDim.new(.5,0)},mark)
    make('UIStroke',{Color=C.red,Thickness=2},mark)
    make('Frame',{AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
        Size=UDim2.fromOffset(4,4),BackgroundColor3=C.red,BorderSizePixel=0,ZIndex=42},mark)
    local caption=make('TextLabel',{Name='FireCaption',Size=UDim2.new(1,-6,0,22),
        Position=UDim2.new(0,3,1,-26),Text='',TextColor3=C.text,TextSize=16,
        Font=Enum.Font.GothamBold,TextWrapped=true,BackgroundTransparency=1,ZIndex=41},fire)
    fontTargets[#fontTargets+1]=caption
    local feedback=make('TextLabel',{Name='ExtraTouchFeedback',Size=UDim2.fromOffset(220,66),
        Text='',TextColor3=C.text,TextSize=14,Font=Enum.Font.Gotham,TextWrapped=true,
        BackgroundColor3=C.card,BackgroundTransparency=.08,BorderSizePixel=0,
        Visible=false,ZIndex=43},surface);corner(feedback,10);fontTargets[#fontTargets+1]=feedback
    local jump,watched=nil,{};local feedbackUntil=0;local used=false;local layout
    local function clearWatch()
        for _,connection in ipairs(watched)do connection:Disconnect()end;watched={}
    end
    local function watch(signal)
        watched[#watched+1]=signal:Connect(function()if alive then layout()end end)
    end
    local function bindJump(nextJump)
        if jump==nextJump then return end
        clearWatch();jump=nextJump
        local node=jump
        while node do
            if node:IsA('GuiObject')then
                for _,key in ipairs({'AbsolutePosition','AbsoluteSize','Visible'})do watch(node:GetPropertyChangedSignal(key))end
            elseif node:IsA('ScreenGui')then watch(node:GetPropertyChangedSignal('Enabled'))end
            node=node.Parent
        end
    end
    local function showFeedback(value)
        feedback.Text=value;feedbackUntil=os.clock()+option('fire_feedback_seconds',3);feedback.Visible=fire.Visible and option('fire_feedback',true)
    end
    layout=function()
        if not alive then return end
        local pg=player:FindFirstChildOfClass('PlayerGui')
        local touch=pg and pg:FindFirstChild('TouchGui')
        if jump and(not pg or not jump:IsDescendantOf(pg))then bindJump(nil)end
        if not jump and touch then
            local candidate=touch:FindFirstChild('JumpButton',true)
            if candidate and(candidate:IsA('ImageButton')or candidate:IsA('TextButton'))then bindJump(candidate)end
        end
        local bounds=surface.AbsoluteSize;local origin=surface.AbsolutePosition
        local width,height=bounds.X,bounds.Y
        local size=math.clamp(option('fire_size',64),48,96);local x,y=width-170,height-180
        local visible=UIS.TouchEnabled==true
        if jump then
            visible=true
            local node=jump
            while node do
                if(node:IsA('GuiObject')and not node.Visible)or(node:IsA('ScreenGui')and node.Enabled==false)then visible=false;break end
                node=node.Parent
            end
            local dimensions=jump.AbsoluteSize
            size=math.clamp(option('fire_size',64),48,96)
            -- Both AbsolutePositions are in the same GUI coordinate space; subtract
            -- the actual surface origin, including its current inset/safe area.
            x=jump.AbsolutePosition.X-origin.X-size-10
            y=jump.AbsolutePosition.Y-origin.Y-size-10
        elseif touch and touch.Enabled==false then visible=false end
        x=x+option('fire_offset_x',0);y=y+option('fire_offset_y',0)
        x=math.clamp(x,8,math.max(8,width-size-8));y=math.clamp(y,8,math.max(8,height-size-8))
        fire.Size=UDim2.fromOffset(size,size);fire.Position=UDim2.fromOffset(x,y)
        fire.BackgroundTransparency=1-option('fire_opacity',.92)
        fire.Visible=option('fire_visible',true)and visible and width>=size+16 and height>=size+16 and gui:GetAttribute('LoadingComplete')==true
        feedback.Position=UDim2.fromOffset(math.clamp(x+size/2-110,8,math.max(8,width-228)),math.max(8,y-74))
        feedback.Visible=option('fire_feedback',true)and fire.Visible and os.clock()<feedbackUntil
        gui:SetAttribute('ExtraTouchAnchor',jump and'JumpButton'or'Fallback')
        gui:SetAttribute('ExtraTouchVisible',fire.Visible)
    end
    local function render()
        if not alive then return end
        local key=gui:GetAttribute('ExtraShotState')or'idle'
        local target=gui:GetAttribute('ExtraShotTarget')or''
        status.Text=tr('extraState_'..key)..(target~=''and(' · '..target)or'')
        local fireKey=O.shot_through_walls~=false and'extraWallShoot'or'extraShoot'
        row.control.Text=tr(gui:GetAttribute('ExtraShotBusy')and'extraBusyButton'or fireKey)
        row.control:SetAttribute('AccessibleLabel',tr(fireKey))
        status.TextColor3=key=='sent'and C.red or C.muted
        caption.Visible=option('fire_caption',true)
        caption.Text=gui:GetAttribute('ExtraShotBusy')and'…'or tr(fireKey)
        local r,g,b=tostring(option('fire_color','235,60,90')):match('^(%d+),(%d+),(%d+)$')
        if r then ring.Color=Color3.fromRGB(tonumber(r),tonumber(g),tonumber(b))end
        fire:SetAttribute('AccessibleLabel',tr(fireKey))
        ring.Transparency=gui:GetAttribute('ExtraShotBusy')and .7 or .15
    end
    for _,key in ipairs({'ExtraShotState','ExtraShotTarget','ExtraShotBusy','Language'})do track(gui:GetAttributeChangedSignal(key),render)end
    local before=bridge.refreshWidgets
    bridge.refreshWidgets=function()if before then before()end;render()end
    track(fire.Activated,function()
        if not alive or not fire.Visible then return end
        used=true
        local ok,result=bridge.run(row.d)
        if not ok then showFeedback(tostring(result))
        else showFeedback(tr('extraState_'..(gui:GetAttribute('ExtraShotState')or'idle')))end
    end)
    track(gui:GetAttributeChangedSignal('ExtraShotState'),function()
        if used then showFeedback(tr('extraState_'..(gui:GetAttribute('ExtraShotState')or'idle')))end
    end)
    track(gui:GetAttributeChangedSignal('EquipmentRevision'),function()layout();render()end)
    track(gui:GetAttributeChangedSignal('LoadingComplete'),layout)
    track(surface:GetPropertyChangedSignal('AbsoluteSize'),layout)
    track(surface:GetPropertyChangedSignal('AbsolutePosition'),layout)
    track(UIS:GetPropertyChangedSignal('TouchEnabled'),layout)
    local elapsed=0
    track(RunService.Heartbeat,function(dt)
        elapsed=elapsed+dt;if elapsed<.25 then return end;elapsed=elapsed%.25;layout()
    end)
    local oldCleanup=onCleanup
    onCleanup=function()clearWatch();if oldCleanup then oldCleanup()end end
    gui:SetAttribute('ExtraReady',true);render();layout()
end
local ok,err=pcall(installRubyExtraUI)
if not ok then gui:SetAttribute('ExtraUIError',tostring(err));warn('ซาลาเปา extra: '..tostring(err))end
end

