 track(send.Activated,function()local ok,err=pcall(model.send,draft.Text);if not ok then state.Text=tr('worldError')..' · '..tostring(err)end end)
 track(draft:GetPropertyChangedSignal('Text'),function()model.setDraft(draft.Text)end)
 track(gui:GetAttributeChangedSignal('Language'),function()render(model)end)
 local oldCleanup=onCleanup
