 gui:SetAttribute('EquipmentAddedControls',50);gui:SetAttribute('WorldReady',true);render(model)
end
local ok,err=pcall(installRubyWorldUI)
if not ok then gui:SetAttribute('WorldUIError',tostring(err));warn('ซาลาเปา world: '..tostring(err))end
end

-- NEBULA CLOUD / RUBY GLASS. Native visual layers; optional artwork never gates startup.
do
local function installRubyGlass()
    local ref=assert(panel:FindFirstChild('ReferenceLayout'),'Reference layout unavailable')
    local bridge=assert(rubyControlUI);local glassAlive=true
    local motions=setmetatable({},{__mode='k'});local buttons=setmetatable({},{__mode='k'})
    local premium,iconPlates={},{ }
    local assets={};local requests={};local registered=setmetatable({},{__mode='k'})
    local function reduced()return gui:GetAttribute('ReduceMotion')==true end
    local function find(name)return gui:FindFirstChild(name,true)end
    local function finishMotion(obj,snap)
        local v=motions[obj];if not v then return end;motions[obj]=nil
        if v.conn then v.conn:Disconnect()end;v.tween:Cancel()
        if snap then for k,value in pairs(v.goal)do pcall(function()obj[k]=value end)end end
    end
    local function animate(obj,seconds,goal,complete)
        finishMotion(obj,false)
        if not glassAlive or not alive then return end
        if reduced()or seconds==0 then for k,v in pairs(goal)do obj[k]=v end;if complete then complete()end;return end
        local tween=TweenService:Create(obj,TweenInfo.new(seconds,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),goal)
        local item={tween=tween,goal=goal};motions[obj]=item
        item.conn=tween.Completed:Connect(function(state)
            if item.conn then item.conn:Disconnect();item.conn=nil end
            if motions[obj]~=item then return end;motions[obj]=nil
            if state==Enum.PlaybackState.Completed and complete and glassAlive and alive then complete()end
        end)
