        g.Color=ColorSequence.new(Color3.fromRGB(241,225,208),Color3.fromRGB(241,225,208))
        edge(o,Color3.fromRGB(193,132,94),.68,1)
        if shadow and not o:FindFirstChild('GlassShadow')then
            local s=make('Frame',{Name='GlassShadow',Position=UDim2.fromOffset(0,4),Size=UDim2.fromScale(1,1),BackgroundColor3=Color3.new(0,0,0),BackgroundTransparency=.72,BorderSizePixel=0,Active=false,ZIndex=0},o);corner(s,14)
