    local valueText=make('TextLabel',{Name='FloatingSliderNumber',Size=UDim2.fromScale(1,1),Text='',TextColor3=C.text,TextSize=18,Font=Enum.Font.Code,BackgroundTransparency=1,BorderSizePixel=0,ZIndex=96},valueBubble)
