        local tag=bind(text(cardHost,'GalleryCaption_'..d.key,10,28,13),'glassAIArtwork');tag.TextColor3=C.muted
        local heading=bind(text(cardHost,'GalleryTitle_'..d.key,296,44,24),d.prefix..'Title');heading.Font=Enum.Font.GothamBold
        local body=bind(text(cardHost,'GalleryBody_'..d.key,346,66,18),d.prefix..'Body');body.TextYAlignment=Enum.TextYAlignment.Top;body.TextColor3=C.muted
        local cta=button(cardHost,'GalleryOpen_'..d.key,d.prefix..'Action');cta.Position=UDim2.new(0,16,1,-66);cta.Size=UDim2.new(1,-32,0,50);cta.BackgroundColor3=C.darkRed;cta.TextSize=20
        track(cta.Activated,function()
            switchPage(d.page)
