        end)
        local function update()pic.Visible=pic.Image~=''and pic.IsLoaded and bridge.tools.get('plus_ui_hide_art')~=true;fallback.Visible=not pic.Visible;tag.Text=tr(assets[d.key]and assets[d.key].state=='failed'and'glassArtworkUnavailable'or'glassAIArtwork')end
        track(pic:GetPropertyChangedSignal('IsLoaded'),update)
        gallery[#gallery+1]={d=d,host=cardHost,pic=pic,fallback=fallback,tag=tag,title=heading,body=body,update=update}
    end
    local galleryRequested=false
    local function galleryImages()
        if galleryRequested then return end;galleryRequested=true
        for _,item in ipairs(gallery)do artwork(item.d.key,function(asset)if asset then item.pic.Image=asset end;item.update()end)end
    end
    local function fitGallery()
        local scale=ref:FindFirstChild('ReferenceScale');local s=scale and scale.Scale or 1
        local width=math.max(280,math.min(1100,pages.updates.AbsoluteSize.X/math.max(.01,s)));local h=math.floor(width*9/16)
        for _,item in ipairs(gallery)do
            item.host.Size=UDim2.new(1,0,0,h+214);item.pic.Size=UDim2.new(1,0,0,h);item.fallback.Size=item.pic.Size
            item.tag.Position=UDim2.fromOffset(16,h+8);item.title.Position=UDim2.fromOffset(16,h+36);item.body.Position=UDim2.fromOffset(16,h+86)
        end
