    track(ref:GetPropertyChangedSignal('Size'),function()fitGallery();styleHomeText();icons();parallax()end)
    local previousSwitch=switchPage
    switchPage=function(key)previousSwitch(key);styleHomeText();icons();if key=='updates'then galleryImages()end;valueBubble.Visible=false end
    local previousOpen=setOpen
    setOpen=function(value)previousOpen(value);if not value then valueBubble.Visible=false end;parallax()end
    local function colors()
        styleHomeText();updateHomeArt();icons()
        for _,item in ipairs(gallery)do item.update();item.host.BackgroundColor3=C.card end
    end
    track(gui:GetAttributeChangedSignal('PlusUIRevision'),colors)
    track(gui:GetAttributeChangedSignal('Language'),function()styleHomeText();typingText.Text=tr('glassTyping');for _,item in ipairs(gallery)do item.update()end end)
    track(gui:GetAttributeChangedSignal('ReduceMotion'),function()
        local pending={};for obj in pairs(motions)do pending[#pending+1]=obj end;for _,obj in ipairs(pending)do finishMotion(obj,true)end
        for b in pairs(buttons)do local s=b:FindFirstChild('GlassPressScale');if s then s.Scale=1 end;b:SetAttribute('GlassPressed',false)end
        parallax()
    end)
    track(gui.DescendantAdded,function(o)decorateButton(o)end)
    local hover,hoverStroke,hoverAlpha,hitTesting=nil,nil,nil,true;local lastPointer=0
    track(UIS.InputChanged,function(input)
        if not open then return end
        if input.UserInputType~=Enum.UserInputType.MouseMovement and input.UserInputType~=Enum.UserInputType.Touch then return end
        local now=os.clock();if now-lastPointer<1/15 then return end;lastPointer=now
        if activePage=='home'and not reduced()then
            local pos=hero.AbsolutePosition or Vector2.new();local size=hero.AbsoluteSize or Vector2.new(1,1);local p=input.Position
            if p.X>=pos.X and p.Y>=pos.Y and p.X<=pos.X+size.X and p.Y<=pos.Y+size.Y then
                pointerX=(p.X-pos.X)/math.max(1,size.X)*10-5;pointerY=(p.Y-pos.Y)/math.max(1,size.Y)*6-3
                local scroll=pages.home.CanvasPosition and pages.home.CanvasPosition.Y or 0
                animate(background,.2,{Position=UDim2.new(-.03,pointerX,-.08,math.clamp(scroll*.09,0,20)+pointerY)})
                gui:SetAttribute('HomePointerOffset',pointerX)
            end
        end
        if not hitTesting or input.UserInputType~=Enum.UserInputType.MouseMovement then return end
        local ok,hits=pcall(function()return gui.Parent:GetGuiObjectsAtPosition(input.Position.X,input.Position.Y)end)
        if not ok then hitTesting=false;return end
        local chosen
        for _,hit in ipairs(hits)do local node=hit;while node and node~=gui do if buttons[node]then chosen=node;break end;node=node.Parent end;if chosen then break end end
        if chosen==hover then return end
        if hover then hover:SetAttribute('GlassHover',false);if hoverStroke then animate(hoverStroke,.15,{Transparency=hoverAlpha})end end
        hover=chosen;hoverStroke=nil
        if hover then
            hover:SetAttribute('GlassHover',true);local stroke=hover:FindFirstChildOfClass('UIStroke')
            if stroke and stroke.Name~='SwitchGlow'then hoverStroke=stroke;hoverAlpha=stroke.Transparency or .72;animate(stroke,.12,{Transparency=.24})end
        end
    end)
    local typingClock,typingPhase=0,0
    track(RunService.Heartbeat,function(dt)
        if not glassAlive or not alive or not typing.Visible or activePage~='ai'or not open then return end
        typingClock=typingClock+dt;if typingClock<.18 then return end;typingClock=typingClock%.18;typingPhase=typingPhase%3+1
        for i,dot in ipairs(dots)do dot.BackgroundTransparency=reduced()and .25 or i==typingPhase and .08 or .7 end
    end)
    local cleanupBefore=onCleanup
    onCleanup=function()
        glassAlive=false;rubyAI.sliderFeedback=nil;rubyAI.messageDecorator=nil
        local pending={};for obj in pairs(motions)do pending[#pending+1]=obj end;for _,obj in ipairs(pending)do finishMotion(obj,false)end
        for _,thread in ipairs(requests)do if type(task.cancel)=='function'then pcall(task.cancel,thread)end end
        if cleanupBefore then cleanupBefore()end
    end
    for _,item in ipairs(gallery)do decorateButton(item.host:FindFirstChild('GalleryOpen_'..item.d.key))end
    gui:SetAttribute('VisualEdition','ซาลาเปา');gui:SetAttribute('GlassGalleryCount',#gallery);gui:SetAttribute('ButtonFeedback','SoftPress')
    gui:SetAttribute('ChatBubbleLayout','LeftRight');gui:SetAttribute('ReleaseIllustrations',9)
    styleHomeText();fitGallery();icons();parallax();rubyAI.render()
end
local glassOK,glassError=pcall(installRubyGlass)
if not glassOK then gui:SetAttribute('GlassError',tostring(glassError));warn('ซาลาเปา glass: '..tostring(glassError))end
end

-- NEBULA CLOUD / RUBY: one status workspace and user-controlled private memory.
do
local function installRubySystemUI()
 -- NEBULA CLOUD / RUBY: private per-account memory, two verified local slots.
local function createRubyMemory(ctx,policy,deps)
 local M={sequence=0,state='hmFresh',restoring=false,blocked=false};local alive=true;local dirtyAt;local lastSaved
 local account=tostring(ctx.me.UserId);local prefix='SALAPAO_memory_'..account..'_';local known={}
 for _,id in ipairs(policy.ids)do known[id]=true end
 local function blank()return{schema=1,enabled=true,rememberChat=true,aiEnabled=false,notes='',settings={},language='TH',font='Gotham',favorites={},history={},aiDraft='',worldDraft=''}end
 M.data=blank()
 local function clone(v)if type(v)~='table'then return v end;local out={};for k,x in pairs(v)do out[k]=clone(x)end;return out end
 local function equal(a,b)
  if type(a)~=type(b)then return false end;if type(a)~='table'then return a==b end
  for k,v in pairs(a)do if not equal(v,b[k])then return false end end;for k in pairs(b)do if a[k]==nil then return false end end;return true
 end
 local function redact(s)return tostring(s):gsub('neb_%x+','[token]'):gsub('AIza[%w_%-]+','[key]'):gsub('[Bb]earer%s+[^%s]+','Bearer [token]')end
 local function units(s)
  if type(s)~='string'then return math.huge end
  if not utf8 or not utf8.codes then return #s end
  local ok,n=pcall(function()local n=0;for _,cp in utf8.codes(s)do n=n+(cp>65535 and 2 or 1)end;return n end);return ok and n or math.huge
 end
 local function fail()error(ctx.translate('hmInvalid'),0)end
 function M.validate(raw)
  if type(raw)~='table'or raw.schema~=1 or type(raw.enabled)~='boolean'or type(raw.rememberChat)~='boolean'or type(raw.aiEnabled)~='boolean'or units(raw.notes)>2000 or type(raw.settings)~='table'then fail()end
  local data=blank();data.enabled=raw.enabled;data.rememberChat=raw.rememberChat;data.aiEnabled=raw.aiEnabled;data.notes=redact(raw.notes)
  for id,value in pairs(raw.settings)do local d=policy.options[id];if d then
   if d.kind=='toggle'and type(value)~='boolean'or d.kind=='number'and(type(value)~='number'or value~=value or value<d.min or value>d.max)then fail()end
   if d.kind=='choice'then local found=false;for _,v in ipairs(d.choices)do if value==v then found=true end end;if not found then fail()end end
   if d.kind=='text'then local r,g,b=tostring(value):match('^(%d+),(%d+),(%d+)$');if not r or tonumber(r)>255 or tonumber(g)>255 or tonumber(b)>255 then fail()end end
   data.settings[id]=value
  end end
  local function member(value,list)for _,v in ipairs(list)do if v==value then return true end end;return false end
