  if type(text)~='string'or units(text)>2000 then return false end
  M.data.notes=text;M.forgotten=false;M.markDirty();return true
 end
 function M.setFlag(key,value)
  if not({enabled=true,rememberChat=true,aiEnabled=true})[key]or type(value)~='boolean'then fail()end
