  if type(readfile)~='function'then notify('hmNoFiles');return false end
  local valid,invalid={},0
  for _,slot in ipairs({'a','b'})do
   local ok,raw=pcall(readfile,prefix..slot..'.json')
   if ok and raw~=nil then local parsed,doc=pcall(decoded,raw);if parsed then valid[#valid+1]=doc else invalid=invalid+1 end end
  end
