 local help=bind(text(memoryPane,'MemoryHelp',0,100,17),'hmHelp');help.Size=UDim2.new(1,0,0,100);help.LayoutOrder=1;help.ZIndex=67;help.TextColor3=C.muted
 local memoryState=text(memoryPane,'MemoryStatus',0,130,17);memoryState.Size=UDim2.new(1,0,0,130);memoryState.LayoutOrder=2;memoryState.ZIndex=67
