    rubyAI.clear();history={};for _,turn in ipairs(data.history)do history[#history+1]={role=turn.role,text=turn.text};rubyAI.add(turn.role=='user'and'you'or'assistant',turn.text)end
   end
   gui:SetAttribute('PlusUIRevision',(gui:GetAttribute('PlusUIRevision')or 0)+1);ctx.equipment.changed();ctx.changed();rubyAI.changed()
  end
