-- NEBULA CLOUD · Ruby Christmas. Local, reversible presentation layer.
do
local function installRubyChristmas()
    local root=panel:FindFirstChild('ReferenceLayout')
    if root then
        local rgb=Color3.fromRGB
        local ice=rgb(240,248,255)
        local white=rgb(255,255,255)
        local pale=rgb(219,238,253)
        local powder=rgb(174,216,247)
        local blue=rgb(54,123,180)
        local navy=rgb(20,52,81)
        local slate=rgb(67,94,120)
        local border=rgb(158,198,229)
        local frost=ColorSequence.new(white,pale)
        local enabled=false
        local saved=setmetatable({},{__mode='k'})
        local snowConnection
        local flakes={}

        local toggle=button(pages.appearance,'RubyChristmasTheme')
        toggle.LayoutOrder=-80
        toggle.TextWrapped=true
        toggle.BackgroundColor3=C.darkRed
        local shortcut=button(pages.settingsHub,'RubyChristmasShortcut')
        shortcut.LayoutOrder=5
        shortcut.TextWrapped=true
        shortcut.BackgroundColor3=C.darkRed
        local function label()
            local state=tr(enabled and 'on' or 'off')
            local caption='❄  '..tr('rubyChristmasTheme')..'  ·  '..state
            for _,control in ipairs({toggle,shortcut})do
                control.Text=caption
                control:SetAttribute('AccessibleLabel',caption)
            end
        end

        local snowfall=make('Frame',{Name='RubyChristmasSnow',Size=UDim2.fromScale(1,1),
            BackgroundTransparency=1,BorderSizePixel=0,Active=false,Visible=false,ZIndex=0,
            ClipsDescendants=true},root)
        local scene=make('Frame',{Name='RubyChristmasScene',Size=UDim2.fromScale(1,1),
            BackgroundColor3=white,BorderSizePixel=0,Active=false,Visible=false,ZIndex=3,
            ClipsDescendants=true},hero)
        corner(scene,14)
        make('UIGradient',{Color=frost,Rotation=25},scene)
        local sprites={}
        local atlasRequested,atlasTask=false,nil
        local frameSize,columns,frameCount,frameRate=128,8,40,20
        local currentFrame=0
        local pixels=""
        local rows
        local function makeRaster(parent)
            if not rows then
                rows={}
                -- Split each row in two to bound the number of stops per gradient.
                for y=0,31 do
                    for half=0,1 do
                        local colors,transparency={},{}
                        local visible=false
                        for x=0,15 do
                            local i=(y*32+half*16+x)*8+1
                            local r=tonumber(pixels:sub(i,i+1),16)
                            local g=tonumber(pixels:sub(i+2,i+3),16)
                            local b=tonumber(pixels:sub(i+4,i+5),16)
                            local a=tonumber(pixels:sub(i+6,i+7),16)
                            colors[x+1]=ColorSequenceKeypoint.new(x/15,rgb(r,g,b))
                            transparency[x+1]=NumberSequenceKeypoint.new(x/15,1-a/255)
                            visible=visible or a>6
                        end
                        if visible then rows[#rows+1]={half=half,y=y,color=ColorSequence.new(colors),
                            transparency=NumberSequence.new(transparency)}end
                    end
                end
            end
            local holder=make('Frame',{Name='ChristmasLogoRaster',BackgroundTransparency=1,
                BorderSizePixel=0,Active=false,Visible=false,ZIndex=2},parent)
            make('UIAspectRatioConstraint',{AspectRatio=1},holder)
            local art=make('Frame',{Name='ChristmasRasterArt',AnchorPoint=Vector2.new(.5,.5),
                Position=UDim2.fromScale(.5,.5),Size=UDim2.fromScale(1,1),
                BackgroundTransparency=1,BorderSizePixel=0,Active=false},holder)
            local strips={}
            for _,row in ipairs(rows)do
                local strip=make('Frame',{Position=UDim2.fromScale(row.half/2,row.y/32),
                    Size=UDim2.fromScale(.5,1/32),BackgroundColor3=white,
                    BorderSizePixel=0,Active=false},art)
                local gradient=make('UIGradient',{Color=row.color,Transparency=row.transparency},strip)
                strips[#strips+1]={frame=strip,gradient=gradient,row=row}
            end
            return {holder=holder,art=art,strips=strips}
        end
        local function turnRaster(raster,index)
            local cosine=math.cos(index*2*math.pi/frameCount)
            raster.art.Size=UDim2.fromScale(math.max(.045,math.abs(cosine)),1)
            local mirrored=cosine<0
            if raster.mirrored==mirrored then return end
            raster.mirrored=mirrored
            for _,strip in ipairs(raster.strips)do
                local row=strip.row
                local x=mirrored and 1-row.half or row.half
                strip.frame.Position=UDim2.fromScale(x/2,row.y/32)
                strip.gradient.Rotation=mirrored and 180 or 0
            end
        end
        local function sprite(parent,name,fallback)
            local image=make('ImageLabel',{Name=name,Image='',ImageRectSize=Vector2.new(frameSize,frameSize),
                ImageRectOffset=Vector2.new(),ImageTransparency=1,BackgroundTransparency=1,
                BorderSizePixel=0,Active=false,Visible=false,ScaleType=Enum.ScaleType.Fit,ZIndex=2},parent)
            local entry={image=image}
            local function alignRaster()
                local holder=entry.raster and entry.raster.holder
                if holder then
                    holder.Size=image.Size;holder.Position=image.Position
                    holder.AnchorPoint=image.AnchorPoint or Vector2.new()
                end
            end
            local function sync()
                local loaded=image.Image~='' and image.IsLoaded
                image.Visible=enabled and image.Image~=''
                image.ImageTransparency=loaded and 0 or 1
                if false and enabled and not loaded and not entry.raster then
                    entry.raster=makeRaster(parent)
                    alignRaster()
                end
                if entry.raster then
                    entry.raster.holder.Visible=enabled and not loaded
                    if entry.raster.holder.Visible then turnRaster(entry.raster,currentFrame)end
                end
                if fallback then fallback:SetAttribute('ChristmasSpriteReady',enabled)end
                if name=='ChristmasHeaderLogo'then
                    gui:SetAttribute('ChristmasLogoSource',enabled and (loaded and 'atlas' or 'native') or 'off')
                end
            end
            if fallback then
                local function align()
                    image.Size=fallback.Size;image.Position=fallback.Position
                    image.AnchorPoint=fallback.AnchorPoint or Vector2.new()
                    alignRaster()
                end
                align()
                track(fallback:GetPropertyChangedSignal('Size'),align)
                track(fallback:GetPropertyChangedSignal('Position'),align)
            end
            track(image:GetPropertyChangedSignal('IsLoaded'),sync)
            entry.sync=sync
            sprites[#sprites+1]=entry
            return image
        end
        sprite(header,'ChristmasHeaderLogo',header:FindFirstChild('RubyLogo'))
        sprite(bubble,'ChristmasFloatingLogo',bubble:FindFirstChild('FloatingRuby'))
        local heroSprite=sprite(scene,'ChristmasHeroLogo')
        heroSprite.AnchorPoint=Vector2.new(.5,.5)
        heroSprite.Position=UDim2.fromScale(.79,.53)
        heroSprite.Size=UDim2.new(.36,0,.84,0)
        make('UIAspectRatioConstraint',{AspectRatio=1},heroSprite)
        local function requestAtlas()
            if atlasRequested or type(customAsset)~='function' or type(writefile)~='function' then return end
            atlasRequested=true
            atlasTask=task.spawn(function()
                local ok,asset=pcall(function()
                    local png=decode64(LOGO_ATLAS_BASE64)
                    if not alive or type(png)~='string' or #png>2000000
                        or png:sub(1,8)~='\137PNG\r\n\26\n' then return end
                    local filename='SALAPAO_Christmas_60_Compact_v1.png'
                    writefile(filename,png)
                    return customAsset(filename)
                end)
                if not alive or not ok or type(asset)~='string' or asset=='' then return end
                local images={}
                for _,entry in ipairs(sprites)do
                    entry.image.Image=asset;entry.sync();images[#images+1]=entry.image
                end
                local provider=game:GetService('ContentProvider')
                if provider then pcall(function()provider:PreloadAsync(images)end)end
                if alive then for _,entry in ipairs(sprites)do entry.sync()end end
            end)
        end
        local function showFrame(index)
            if index==currentFrame then return end
            currentFrame=index
            local offset=Vector2.new((index%columns)*frameSize,math.floor(index/columns)*frameSize)
            for _,entry in ipairs(sprites)do
                entry.image.ImageRectOffset=offset
                if entry.raster and entry.raster.holder.Visible then turnRaster(entry.raster,index)end
            end
        end
        local function flake(parent,index,x,y,size)
            local shape=make('Frame',{Name='Snowflake_'..index,Size=UDim2.fromOffset(size,size),
                AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(x,y),BackgroundTransparency=1,
                BorderSizePixel=0,Active=false},parent)
            for angle=0,120,60 do
                local ray=make('Frame',{AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),
                    Size=UDim2.new(1,0,0,size>=18 and 2 or 1),BackgroundColor3=blue,
                    BackgroundTransparency=parent==scene and .34 or .63,BorderSizePixel=0,
                    Rotation=angle,Active=false},shape)
                corner(ray,2)
            end
            flakes[#flakes+1]={shape=shape,x=x,y=y,phase=index*.79,speed=.023+index%4*.007}
        end
        for i=1,12 do flake(snowfall,i,((i*37)%91+4)/100,((i*23)%93+3)/100,9+i%4*4)end
        for i=1,7 do flake(scene,i,.64+((i*31)%32)/100,.17+((i*23)%72)/100,13+i%4*5)end
        for i=1,9 do
            local light=make('Frame',{Name='WinterLight_'..i,AnchorPoint=Vector2.new(.5,.5),
                Position=UDim2.fromScale(.64+i*.034,.09+math.sin(i*.37)*.06),
                Size=UDim2.fromOffset(7,7),BackgroundColor3=i%3==0 and rgb(212,160,64)or powder,
                BorderSizePixel=0,Active=false},scene)
            corner(light,4)
        end

        local function channels(color)
            if type(color)=='table'then return color[1],color[2],color[3]end
            return color.R*255,color.G*255,color.B*255
        end
        local function winterColor(color,role)
            local r,g,b=channels(color)
            local red=r>g*1.22 and r>b*1.17
            local green=g>r*1.25 and g>b*1.15
            if role=='gem'then
                return r>200 and white or (r>145 and pale or powder)
            end
            if role=='text'then
                if green then return rgb(17,102,68)end
                if red then return blue end
                return (r+g+b)/3>190 and navy or slate
            end
            if role=='edge'then return red and blue or border end
            if green then return color end
            if red then return pale end
            local brightness=(r+g+b)/3
            if brightness>=200 then return white end
            return brightness<19 and white or ice
        end
        local function setColor(obj,property,role)
            local current=obj[property]
            if current==nil then return end
            local fields=saved[obj]
            local previous=fields and fields[property]
            if previous and current==previous.applied then return end
            if not fields then fields={};saved[obj]=fields end
            local new=role=='gradient' and frost or winterColor(current,role)
            fields[property]={original=current,applied=new}
            obj[property]=new
        end

        local function paint(obj)
            local class=obj.ClassName
            if class=='UIStroke'then
                setColor(obj,'Color','edge')
            elseif class=='UIGradient'then
                if obj.Name=='GlassTint' or obj.Parent==header or obj.Parent==hero
                    or obj.Parent==openAIButton then setColor(obj,'Color','gradient')end
            elseif class=='WedgePart'and obj.Name=='RubyFacet'then
                setColor(obj,'Color','gem')
            elseif obj:IsA('GuiObject') then
                setColor(obj,'BackgroundColor3','surface')
                if class=='TextLabel'or class=='TextButton'or class=='TextBox'then
                    setColor(obj,'TextColor3','text')
                end
                if class=='TextBox'then setColor(obj,'PlaceholderColor3','text')end
                if class=='ScrollingFrame'then setColor(obj,'ScrollBarImageColor3','edge')end
                if class=='ViewportFrame' and obj:FindFirstChildOfClass('WorldModel') then
                    setColor(obj,'Ambient','surface')
                    setColor(obj,'LightColor','surface')
                end
            end
        end
        local function decorative(obj)
            local parent=obj
            while parent and parent~=panel do
                if parent==snowfall or parent==scene or parent.Name=='ChristmasLogoRaster' then return true end
                parent=parent.Parent
            end
            return false
        end
        local function paintTree(start)
            if not start then return end
            paint(start)
            for _,obj in ipairs(start:GetDescendants())do
                if not decorative(obj)then paint(obj)end
            end
        end
        local function restore()
            for obj,fields in pairs(saved)do
                if obj.Parent then
                    for property,change in pairs(fields)do
                        if obj[property]==change.applied then obj[property]=change.original end
                    end
                end
            end
            saved=setmetatable({},{__mode='k'})
        end

        local time,accumulator,spinTime=0,0,0
        local function positionFlakes(still)
            for _,flake in ipairs(flakes)do
                local x=flake.x+(still and 0 or math.sin(time*.7+flake.phase)*.016)
                local y=still and flake.y or ((flake.y+time*flake.speed+.04)%1.08)-.04
                flake.shape.Position=UDim2.fromScale(x,y)
            end
        end
        local function stopSnow()
            if snowConnection then snowConnection:Disconnect();snowConnection=nil end
        end
        local function syncSnow()
            if not enabled or not panel.Visible or gui:GetAttribute('ReduceMotion')then
                stopSnow()
                if enabled then positionFlakes(true)end
                if gui:GetAttribute('ReduceMotion')then showFrame(0)end
            elseif not snowConnection then
                accumulator=0
                snowConnection=RunService.Heartbeat:Connect(function(dt)
                    time=time+dt
                    spinTime=spinning and (spinTime+dt)%(frameCount/frameRate) or 0
                    showFrame(math.floor(spinTime*frameRate)%frameCount)
                    accumulator=accumulator+dt
                    if accumulator>=1/15 then
                        accumulator=accumulator%(1/15)
                        positionFlakes(false)
                    end
                end)
            end
        end
        local function setWinter(value)
            enabled=value
            if enabled then paintTree(panel);paintTree(bubble)else restore()end
            snowfall.Visible=enabled;scene.Visible=enabled
            gui:SetAttribute('RubyTheme',enabled and 'Christmas' or 'ซาลาเปา')
            for _,entry in ipairs(sprites)do entry.sync()end
            if enabled then requestAtlas()else spinTime=0;showFrame(0)end
            label();syncSnow()
        end

        local refreshQueued=false
        local function refreshVisible()
            if not enabled or refreshQueued then return end
            refreshQueued=true
            task.defer(function()
                refreshQueued=false
                if not alive or not enabled then return end
                paintTree(nav);paintTree(header);paintTree(pages[activePage])
            end)
        end
        local function toggleTheme()setWinter(not enabled)end
        track(toggle.Activated,toggleTheme)
        track(shortcut.Activated,toggleTheme)
        track(gui:GetAttributeChangedSignal('Language'),function()label();refreshVisible()end)
        track(gui:GetAttributeChangedSignal('PlusUIRevision'),refreshVisible)
        track(gui:GetAttributeChangedSignal('ActivePage'),refreshVisible)
        track(gui:GetAttributeChangedSignal('ReduceMotion'),syncSnow)
        track(panel:GetPropertyChangedSignal('Visible'),syncSnow)
        track(panel.DescendantAdded,function(obj)
            if enabled and not decorative(obj) then task.defer(function()
                if alive and enabled and obj.Parent then paint(obj)end
            end)end
        end)
        local previousCleanup=onCleanup
        onCleanup=function()
            stopSnow()
            if atlasTask and type(task.cancel)=='function'then pcall(task.cancel,atlasTask)end
            if previousCleanup then previousCleanup()end
        end
        setWinter(false)
    end
end
local ok,err=pcall(installRubyChristmas)
if not ok then gui:SetAttribute('ChristmasThemeError',tostring(err));warn('RUBY Christmas: '..tostring(err))end
end


