    end
    local disclaimer=info(pages.updates,'SalapaoCounting',150)
    disclaimer.Text='ซาลาเปา · 15 แท็บ\n1,501 รายการ = 1,034 รายการจาก Ruby + 466 รายการสตูดิโอ + 1 โหมดยิง\nนับรวมคำสั่งและค่าปรับของแต่ละเลเยอร์ สมุด และตัวจับเวลา ไม่ใช่ 1,501 ระบบแยกกัน\nความสามารถที่เกี่ยวกับเกมขึ้นอยู่กับเกมและตัวรัน ยังไม่ได้ทดสอบบน Delta จริง'
    disclaimer.Parent.LayoutOrder=-100
    gui:SetAttribute('FeatureCount',#RUBY_CONTROLS);gui:SetAttribute('FeatureCountIncludesParameters',true)
    gui:SetAttribute('FeatureCategoryCount',15);gui:SetAttribute('PageCount',15)
    gui:SetAttribute('ProgramName','ซาลาเปา');gui:SetAttribute('LogoAnimation','GIF-derived atlas')
    gui:SetAttribute('ReleaseName','1.0.4');gui:SetAttribute('InheritedSource','Ruby v1.6.4')
    track(gui:GetAttributeChangedSignal('Language'),stamp);stamp()
