-- NEBULA CLOUD | ซาลาเปา v1.0.4 | Visual polish; existing tools stay connected.
do
    local function salapaoLayoutMetrics(w,h,s,portrait,isHome)
        s=math.max(.1,s)
        local action=math.max(48,math.ceil(40/s))
        local gap=8
        local span=3*(action+gap)
        local x=portrait and 122 or 254
        local searchY=action+24
        local top=isHome and(action+20)or(portrait and(searchY+68)or(action+20))
        local searchW=math.min(330,math.max(180,w-x-span-224))
        return {action=action,gap=gap,span=span,x=x,top=top,searchY=searchY,
            searchW=searchW,searchX=w-span-searchW-32,
            navHeight=math.max(portrait and 74 or 54,math.ceil(42/s)),
            contentHeight=math.max(100,h-top-34)}
    end
    local function installSalapaoPolish()
        local root=assert(panel:FindFirstChild('ReferenceLayout'),'Reference layout unavailable')
        local scale=root:FindFirstChild('ReferenceScale')
        local bridge=assert(rubyControlUI,'Control registry unavailable')
        local rgb=Color3.fromRGB
        local white,cream,border=rgb(255,253,249),rgb(250,237,221),rgb(225,204,183)
        local polishAlive,queued=true,false
        local appliedLabelSize
        local known=setmetatable({},{__mode='k'})
        local function find(name)return gui:FindFirstChild(name,true)end
        local function rounded(o,r)
            local c=o:FindFirstChildOfClass('UICorner')or make('UICorner',{},o)
            c.CornerRadius=UDim.new(0,r)
        end
        local function edge(o,color,alpha)
            local e=o:FindFirstChildOfClass('UIStroke')or make('UIStroke',{},o)
            e.Color=color;e.Transparency=alpha;e.Thickness=1
            e.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
            return e
        end
        local function tint(o,a,b,rotation)
            local g=o:FindFirstChildOfClass('UIGradient')or make('UIGradient',{},o)
            g.Color=ColorSequence.new(a,b);g.Rotation=rotation or 105
        end
        local function decorate(o)
            if known[o]then return end;known[o]=true
            if o:IsA('Frame')and(o.Name:find('^FeatureRow_')or o.Name:find('Card$')
                or o.Name=='HomeHero'or o.Name=='AIWorkspace')then
                o.BackgroundColor3=C.card;rounded(o,o.Name=='HomeHero'and 22 or 14)
                tint(o,white,rgb(255,248,238));edge(o,border,.46)
                local shadow=o:FindFirstChild('GlassShadow')
                if shadow then shadow.BackgroundColor3=rgb(149,113,84);shadow.BackgroundTransparency=.96 end
            elseif o:IsA('TextBox')and o.BackgroundTransparency<.99 then
                o.BackgroundColor3=white;o.PlaceholderColor3=C.muted
                rounded(o,12);edge(o,border,.32)
            end
        end
        for _,o in ipairs(gui:GetDescendants())do decorate(o)end
        for _,row in pairs(bridge.rows)do if row.knob then row.knob.BackgroundColor3=white end end
        local search=find('FeatureSearch')
        if search then
            local e=edge(search,border,.55)
            track(search.Focused,function()if polishAlive then e.Color=C.red;e.Transparency=.15 end end)
            track(search.FocusLost,function()if polishAlive then e.Color=border;e.Transparency=.55 end end)
        end
        local function colors()
            if not polishAlive or not alive or gui:GetAttribute('RubyTheme')=='Christmas'then return end
            panel.BackgroundColor3=C.bg
            local windowEdge=panel:FindFirstChildOfClass('UIStroke')
            if windowEdge then windowEdge.Color=border;windowEdge.Transparency=.18;windowEdge.Thickness=1 end
            header.BackgroundTransparency=0;header.BackgroundColor3=C.bg
            headerGradient.Color=ColorSequence.new(white,C.bg);headerGradient.Rotation=90
            tint(hero,white,cream,12);hero.BackgroundTransparency=0;edge(hero,border,.18)
            local shade=find('GlassHeroShade');if shade then shade.BackgroundTransparency=1 end
            local selection=find('SlidingCategorySelection')
            if selection then
                selection.BackgroundColor3=C.darkRed;selection.BackgroundTransparency=.1
                rounded(selection,14);tint(selection,white,C.darkRed,18);edge(selection,C.red,.65)
            end
            local divider=find('SidebarDivider');if divider then divider.BackgroundColor3=border;divider.BackgroundTransparency=.4 end
            for i=1,16 do
                local halo=surface:FindFirstChild('ReferenceGlow_'..i)
                if halo then local e=halo:FindFirstChildOfClass('UIStroke');if e then e.Transparency=math.min(.995,.966+i*.0017)end end
            end
            for key,b in pairs(tabs)do
                local l=b:FindFirstChild('CategoryLabel')
                if l then l.TextColor3=key==activePage and C.text or C.muted end
                local p=b:FindFirstChild('GlassIconPlate')
                if p then p.BackgroundTransparency=key==activePage and .08 or .58 end
            end
        end
        local function selectionLayout()
            if not polishAlive or not alive then return end
            local selected=tabs[activePage]
            local selection=find('SlidingCategorySelection')
            if not selected or not selection then return end
            local s=math.max(.1,scale and scale.Scale or 1)
            local y
            if selected.AbsolutePosition and nav.AbsolutePosition then
                y=(selected.AbsolutePosition.Y-nav.AbsolutePosition.Y)/s
            else
                y=((selected.LayoutOrder or 1)-1)*(selected.Size.Y.Offset+navLayout.Padding.Offset)
                    -(nav.CanvasPosition and nav.CanvasPosition.Y or 0)
            end
            selection.Position=UDim2.fromOffset(0,y)
            selection.Size=UDim2.new(1,-2,0,selected.Size.Y.Offset)
        end
        local function layout()
            if not polishAlive or not alive then return end
            local w=gui:GetAttribute('LogicalWidth')or root.Size.X.Offset
            local h=gui:GetAttribute('LogicalHeight')or root.Size.Y.Offset
            local s=scale and scale.Scale or 1
            local portrait=w<1000
            local home=activePage=='home'
            local m=salapaoLayoutMetrics(w,h,s,portrait,home)
            local buttons={find('SettingsButton'),hide,close}
            for i,b in ipairs(buttons)do
                b.Size=UDim2.fromOffset(m.action,m.action)
                b.Position=UDim2.fromOffset(w-16-(4-i)*(m.action+m.gap),8)
                b.BackgroundColor3=white;b.BackgroundTransparency=.1;rounded(b,14)
                edge(b,border,.55)
                for _,name in ipairs({'SettingsIcon','MinimizeIcon','CloseIcon'})do
                    local icon=b:FindFirstChild(name)
                    if icon then icon.Position=UDim2.fromOffset((m.action-28)/2,(m.action-28)/2)end
                end
            end
            header.Size=UDim2.fromOffset(w,portrait and not home and m.searchY+58 or m.action+16)
            content.Position=UDim2.fromOffset(m.x,m.top)
            content.Size=UDim2.fromOffset(w-m.x-18,m.contentHeight)
            local section=find('SectionTitle')
            if section then
                section.Position=UDim2.fromOffset(m.x,10)
                section.Size=UDim2.fromOffset(math.max(80,portrait and w-m.x-m.span-32 or m.searchX-m.x-16),m.action)
                section.TextTruncate=Enum.TextTruncate.AtEnd
            end
            if search and not home then
                if portrait then
                    search.Position=UDim2.fromOffset(m.x,m.searchY);search.Size=UDim2.fromOffset(w-m.x-18,52)
                else
                    search.Position=UDim2.fromOffset(m.searchX,10);search.Size=UDim2.fromOffset(m.searchW,m.action-4)
                end
                search.TextSize=math.min(28,math.max(21,math.ceil(13/math.max(.1,s))))
            end
            navLayout.Padding=UDim.new(0,7)
            for _,b in pairs(tabs)do
                b.Size=UDim2.new(1,-2,0,m.navHeight)
                local icon=b:FindFirstChild('CategoryIcon')
                if icon then icon.Position=UDim2.fromOffset(28,(m.navHeight-27)/2)end
                local label=b:FindFirstChild('CategoryLabel')
                if label then label.Size=UDim2.new(1,-80,1,0)end
                local plate=b:FindFirstChild('GlassIconPlate')
                if plate and icon then plate.Position=UDim2.fromOffset(22,icon.Position.Y.Offset-6)end
            end
            local right=w-m.x-18
            local logoSize=math.floor(math.min(hero.Size.Y.Offset-28,right*.38))
            heroLogo.AnchorPoint=Vector2.new(1,.5)
            heroLogo.Position=UDim2.new(1,-18,.5,6)
            heroLogo.Size=UDim2.fromOffset(logoSize,logoSize)
            for _,o in ipairs(heroLogo:GetChildren())do
                if o:IsA('ViewportFrame')or o.Name=='HeroRubyImageHost'then
                    o.Position=UDim2.new();o.Size=UDim2.fromScale(1,1)
                end
            end
            welcome.Size=UDim2.new(portrait and .53 or .6,0,0,64)
            welcome.TextColor3=C.text
            heroEdition.Text='v1.0.4';heroEdition.Size=UDim2.fromOffset(108,27)
            heroEdition.Position=UDim2.fromOffset(26,24);heroEdition.TextSize=15
            heroEdition.BackgroundColor3=white;heroEdition.BackgroundTransparency=.08
            heroEdition.TextXAlignment=Enum.TextXAlignment.Center;rounded(heroEdition,13)
            edge(heroEdition,border,.4)
            if LANGS[langIndex]=='TH'then homeBody.Text='เลือกหมวด หรือค้นหาฟีเจอร์ได้เลย'
            elseif LANGS[langIndex]=='EN'then homeBody.Text='Your controls, beautifully organized.'end
            homeBody.TextSize=math.min(26,math.max(18,math.ceil(12/math.max(.1,s))))
            homeBody.Size=UDim2.new(portrait and .53 or .56,0,0,64)
            pages.home.CanvasSize=UDim2.fromOffset(0,portrait and 894 or 576)
            local factor=bridge.tools.get('plus_ui_text')or 1
            local labelSize=math.min(28,math.max(21,math.ceil(13/math.max(.1,s))))*factor
            if labelSize~=appliedLabelSize then
                for _,row in pairs(bridge.rows)do row.title.TextSize=labelSize end
                appliedLabelSize=labelSize
            end
            footer.Text='ซาลาเปา · NEBULA CLOUD · v1.0.4';footer.TextSize=16
            gui:SetAttribute('MinimumNavigationTarget',m.navHeight*s)
            gui:SetAttribute('MinimumHeaderTarget',m.action*s)
            colors()
        end
        local function requestLayout()
            if queued or not polishAlive then return end;queued=true
            task.defer(function()queued=false;if polishAlive and alive then layout()end end)
        end
        local previousResize=resize
        resize=function(reset)previousResize(reset);layout()end
        local previousSwitch=switchPage
        switchPage=function(key)previousSwitch(key);layout()end
        track(root:GetPropertyChangedSignal('Size'),requestLayout)
        track(navLayout:GetPropertyChangedSignal('AbsoluteContentSize'),selectionLayout)
        track(gui:GetAttributeChangedSignal('Language'),requestLayout)
        track(gui:GetAttributeChangedSignal('PlusUIRevision'),requestLayout)
        track(gui:GetAttributeChangedSignal('RubyTheme'),requestLayout)
        track(gui.DescendantAdded,function(o)
            if not polishAlive or gui:GetAttribute('RubyTheme')=='Christmas'then return end
            if o:IsA('Frame')or o:IsA('TextBox')then task.defer(function()if polishAlive and alive and o.Parent then decorate(o)end end)end
        end)
        local previousCleanup=onCleanup
        onCleanup=function()polishAlive=false;if previousCleanup then previousCleanup()end end
        gui:SetAttribute('VisualRevision','1.0.4');gui:SetAttribute('VisualEdition','ซาลาเปา')
        gui:SetAttribute('LogoHasFace',false);gui:SetAttribute('VisualPolishReady',true)
        layout()
    end
    local ok,err=pcall(installSalapaoPolish)
    if not ok then gui:SetAttribute('VisualPolishError',tostring(err));warn('ซาลาเปา visual: '..tostring(err))end
end

-- NEBULA CLOUD | Live movement status and explicit farm shortcuts.
do
    local function installSalapaoFarmUI()
    local bridge=assert(rubyControlUI)
    local box=card(pages.farm,'FarmStatusCard',230);box.LayoutOrder=-30
    local heading=text(box,'FarmStatusTitle',12,35,24);heading.TextColor3=C.red
    local status=text(box,'FarmStatusText',54,88,18);status.TextColor3=C.text
    local start=button(box,'FarmTeleportStart');start.Position=UDim2.new(0,12,1,-72);start.Size=UDim2.new(.5,-18,0,54)
    local stop=button(box,'FarmStop');stop.Position=UDim2.new(.5,6,1,-72);stop.Size=UDim2.new(.5,-18,0,54)
    local labels={
        stopped={'หยุดแล้ว','Stopped'},searching={'กำลังค้นหา','Searching'},moving={'กำลังไปยังเป้าหมาย','Moving to target'},
        contact={'ถึงจุดแล้ว รอเก็บ','At target; waiting for contact'},waiting_round={'รอรอบที่เล่นอยู่','Waiting for an active round'},
        dead={'รอตัวละครเกิด','Waiting for respawn'},no_targets={'รอเหรียญหรือลูกอม','Waiting for coin/candy targets'},
        paused_safety={'พักตามเงื่อนไขความปลอดภัยที่ตั้งไว้','Paused by movement limits'},paused_typing={'พักระหว่างพิมพ์','Paused while typing'},
        paused_equipped={'พักระหว่างถืออุปกรณ์','Paused while a tool is equipped'},avoiding={'กำลังหลบผู้เล่นอันตราย','Avoiding a nearby threat'},
        limit={'ครบจำนวนหรือเวลาที่ตั้งไว้','Configured target/time limit reached'},
    }
    local function render()
        if not alive then return end
        local th=LANGS[langIndex]=='TH';local i=th and 1 or 2
        heading.Text=th and'ฟาร์มเหรียญ / ลูกอม'or'Coin / candy farming'
        start.Text=th and'เริ่มฟาร์มวาร์ป'or'Start teleport farm';stop.Text=th and'หยุดฟาร์ม'or'Stop farm'
        local key=gui:GetAttribute('FarmState')or'stopped';local words=labels[key]or labels.stopped
        local target=gui:GetAttribute('FarmTarget')or''
        local mode=bridge.tools.get('farm_mode')or'Walk'
        local reached=gui:GetAttribute('FarmTargetsReached')or 0
        status.Text=words[i]..(target~=''and(' · '..target)or'')..'\n'..mode..' · '
            ..(th and'เข้าถึงจุด 'or'Targets reached: ')..reached
            ..'\n'..(th and'จำนวนนี้เป็นจุดที่เข้าถึง ไม่ใช่ยอดเงินที่เซิร์ฟเวอร์ยืนยัน'or'Movement targets; currency totals are server-owned.')
    end
    track(start.Activated,function()
        local ok=bridge.run(bridge.rows.farm_mode.d,'Teleport')
        if ok then bridge.run(bridge.rows.auto_coins.d,true)end
        render()
    end)
    track(stop.Activated,function()bridge.run(bridge.rows.auto_coins.d,false);render()end)
    for _,key in ipairs({'FarmState','FarmTarget','FarmTargetsReached','FarmTargetsSkipped','Language'})do
        track(gui:GetAttributeChangedSignal(key),render)
    end
    local previous=bridge.refreshWidgets
    bridge.refreshWidgets=function()if previous then previous()end;render()end
    gui:SetAttribute('FarmControlsReady',true);render()
    end
    local ok,err=pcall(installSalapaoFarmUI)
    if not ok then gui:SetAttribute('FarmUIError',tostring(err));warn('ซาลาเปา farm: '..tostring(err))end
end

rubyBoot.finish()
